const c=3,n="tin-hoc",h="Tin học lớp 3",t="internal",i=[{id:"may-tinh-va-em",title:"Máy tính và em",lessons:[{id:"th3-thong-tin",title:"Thông tin quanh em",weeks:[1,2],learn:[{title:"Thông tin là gì?",text:"Những gì em nhìn, nghe, đọc được giúp em biết thêm về sự vật, sự việc. Đó là thông tin.",example:"🚦 đèn đỏ: dừng lại  ·  🥁 tiếng trống: vào lớp"},{title:"Ba dạng thông tin thường gặp",text:"Thông tin thường gặp ở ba dạng: chữ, hình ảnh và âm thanh.",example:"📖 chữ  ·  🖼️ hình ảnh  ·  🔔 âm thanh"},{title:"Thông tin giúp em quyết định",text:"Nhờ có thông tin, em biết nên làm gì cho phù hợp.",example:"🌧️ trời mây đen  ➜  mang áo mưa"}],practice:[{questions:[{id:"th3-thong-tin-01",type:"mc",q:"Tiếng trống trường vang lên sau giờ ra chơi cho em biết điều gì?",emoji:"🥁",explain:"Tiếng trống là thông tin dạng âm thanh, báo hết giờ ra chơi, vào lớp.",options:["Trời sắp mưa","Có khách đến trường","Hôm nay được nghỉ học","Đã đến giờ vào lớp"],answer:3},{id:"th3-thong-tin-02",type:"match",q:"Nối thông tin với dạng của nó.",explain:"Thông tin thường gặp ở ba dạng: chữ, hình ảnh, âm thanh.",pairs:[["Bức tranh con mèo","Hình ảnh"],["Tiếng còi xe","Âm thanh"],["Một câu trong truyện","Chữ"]]},{id:"th3-thong-tin-03",type:"mc",q:"Tấm biển ghi chữ “Thư viện” trước cửa phòng là thông tin dạng nào?",emoji:"🏫",explain:"Tấm biển có chữ viết để em đọc nên là thông tin dạng chữ.",options:["Âm thanh","Hình ảnh","Chữ"],answer:2},{id:"th3-thong-tin-04",type:"tf",q:"Đèn giao thông chuyển sang màu đỏ là một thông tin.",emoji:"🚦",explain:"Đúng. Đèn đỏ cho biết người và xe phải dừng lại.",answer:!0},{id:"th3-thong-tin-05",type:"tf",q:"Tiếng chim hót là thông tin dạng chữ.",emoji:"🐦",explain:"Sai. Tiếng chim hót em nghe được, đó là thông tin dạng âm thanh.",answer:!1},{id:"th3-thong-tin-06",type:"mc",q:"Em nghe thông tin dạng âm thanh bằng bộ phận nào?",emoji:"👂",explain:"Em dùng tai để nghe âm thanh.",options:["Tai","Mắt","Mũi","Lưỡi"],answer:0},{id:"th3-thong-tin-07",type:"mc",q:"Em nhìn bức tranh bằng bộ phận nào?",emoji:"👀",explain:"Em dùng mắt để nhìn hình ảnh.",options:["Tai","Mắt","Mũi","Miệng"],answer:1},{id:"th3-thong-tin-08",type:"multi",q:"Đâu là thông tin dạng hình ảnh?",explain:"Ảnh và tranh em nhìn thấy là hình ảnh; tiếng hát, tiếng chuông là âm thanh.",options:["Tiếng hát của bạn Lan","Tiếng chuông điện thoại","Bức ảnh gia đình","Tranh vẽ ngôi nhà"],answers:[2,3]},{id:"th3-thong-tin-09",type:"fill",q:"Thông tin thường gặp có ba dạng: chữ, hình ảnh và …",explain:"Ba dạng thông tin thường gặp là chữ, hình ảnh và âm thanh.",answer:["âm thanh"]}]},{questions:[{id:"th3-thong-tin-10",type:"mc",q:"Sáng nay trời nhiều mây đen. Thông tin này giúp em quyết định điều gì?",emoji:"🌧️",explain:"Mây đen báo trời có thể mưa nên em mang áo mưa.",options:["Đi tắm biển","Mang theo áo mưa","Phơi chăn ngoài sân","Đi thả diều thật lâu"],answer:1},{id:"th3-thong-tin-11",type:"mc",q:"Chuông báo thức reo lúc sáu giờ sáng. Thông tin này cho Lan biết điều gì?",emoji:"⏰",explain:"Chuông báo thức là thông tin dạng âm thanh, nhắc Lan thức dậy.",options:["Đã đến giờ đi ngủ","Trời sắp mưa","Đã đến giờ thức dậy","Có bạn đến chơi"],answer:2},{id:"th3-thong-tin-12",type:"mc",q:"Đèn tín hiệu dành cho người đi bộ đang bật màu đỏ. Em nên làm gì?",emoji:"🚦",explain:"Đèn đỏ báo phải dừng lại, em đứng chờ đến khi đèn xanh.",options:["Chạy nhanh qua đường","Đi chậm qua đường","Vừa đi vừa nhìn điện thoại","Đứng chờ, chưa sang đường"],answer:3},{id:"th3-thong-tin-13",type:"match",q:"Nối thông tin với quyết định phù hợp.",explain:"Thông tin giúp em biết nên làm gì cho phù hợp.",pairs:[["Trời nắng gắt","Đội mũ khi ra ngoài"],["Bụng đói","Ăn cơm"],["Trống vào lớp","Về chỗ ngồi"],["Đèn xanh cho người đi bộ","Sang đường cẩn thận"]]},{id:"th3-thong-tin-14",type:"tf",q:"Thông tin không giúp ích gì khi em cần quyết định làm một việc.",explain:"Sai. Thông tin giúp em biết nên làm gì cho phù hợp.",answer:!1},{id:"th3-thong-tin-15",type:"tf",q:"Một tin chỉ có thể viết bằng chữ, không thể nói ra bằng âm thanh.",explain:"Sai. Cùng một tin có thể nói ra bằng lời hoặc viết bằng chữ.",answer:!1},{id:"th3-thong-tin-16",type:"mc",q:"Bảng tin của lớp có ảnh chụp và lời giới thiệu viết bên dưới. Bảng tin có những dạng thông tin nào?",emoji:"📋",explain:"Ảnh chụp là hình ảnh, lời giới thiệu viết ra là chữ.",options:["Chỉ có âm thanh","Chỉ có chữ","Âm thanh và chữ","Hình ảnh và chữ"],answer:3},{id:"th3-thong-tin-17",type:"multi",q:"Thông tin nào em nhận được bằng tai?",explain:"Tiếng còi, lời giảng, tiếng mưa là âm thanh; bức tranh em nhìn bằng mắt.",options:["Tiếng còi xe cứu thương","Lời cô giáo giảng bài","Bức tranh phong cảnh","Tiếng mưa rơi"],answers:[0,1,3]},{id:"th3-thong-tin-18",type:"mc",q:"Khi xem một đoạn phim hoạt hình có lời nói, em nhận được thông tin dạng nào?",emoji:"🎬",explain:"Phim có hình em nhìn thấy và tiếng em nghe được.",options:["Chỉ có chữ","Hình ảnh và âm thanh","Chỉ có âm thanh","Không có thông tin nào"],answer:1}]},{questions:[{id:"th3-thong-tin-19",type:"mc",q:"Trên hộp sữa, hạn sử dụng đã qua mấy ngày rồi. Em nên làm gì?",emoji:"🥛",explain:"Sữa quá hạn sử dụng có thể làm em đau bụng, không nên uống.",options:["Uống ngay","Cho bạn uống","Không uống hộp sữa đó","Cất lại để uống sau"],answer:2},{id:"th3-thong-tin-20",type:"mc",q:"Nhiệt kế cho thấy Chi bị sốt. Thông tin này giúp mẹ quyết định gì?",emoji:"🌡️",explain:"Biết Chi bị sốt, mẹ cho Chi nghỉ ngơi và đưa đi khám.",options:["Cho Chi nghỉ ngơi và đưa đi khám","Cho Chi đi bơi","Cho Chi ăn kem","Để Chi chạy chơi ngoài nắng"],answer:0},{id:"th3-thong-tin-21",type:"mc",q:"Tùng muốn biết ngày mai trời có mưa không. Tùng nên tìm thông tin ở đâu?",emoji:"📺",explain:"Bản tin dự báo thời tiết cho biết trời nắng hay mưa.",options:["Quyển truyện cổ tích","Bản tin dự báo thời tiết","Bài hát thiếu nhi về mùa hè","Quyển vở bài tập Toán"],answer:1},{id:"th3-thong-tin-22",type:"match",q:"Nối việc em làm với dạng thông tin em nhận được.",explain:"Nghe là âm thanh, đọc là chữ, xem ảnh là hình ảnh.",pairs:[["Nghe đài phát thanh","Âm thanh"],["Đọc thời khóa biểu","Chữ"],["Xem ảnh chụp cả lớp","Hình ảnh"]]},{id:"th3-thong-tin-23",type:"tf",q:"Thấy biển ghi chữ “Cấm bơi” ở bờ hồ, em vẫn có thể xuống bơi nếu trời nóng.",emoji:"🚫",explain:"Sai. Biển “Cấm bơi” báo nơi đó nguy hiểm, em không được xuống bơi.",answer:!1},{id:"th3-thong-tin-24",type:"mc",q:"Phúc thấy khói đen bốc lên từ một căn nhà. Phúc nên làm gì?",emoji:"💨",explain:"Khói đen có thể là có cháy, em cần báo ngay cho người lớn.",options:["Báo ngay cho người lớn","Chạy vào trong nhà xem","Đứng một chỗ để xem cho biết","Đi về nhà, không nói với ai"],answer:0},{id:"th3-thong-tin-25",type:"order",q:"Sắp xếp các việc khi em nghe tiếng trống vào lớp.",explain:"Em nhận thông tin, hiểu thông tin rồi mới làm việc phù hợp.",items:["Nghe tiếng trống","Hiểu là đã đến giờ vào lớp","Xếp hàng vào lớp"]},{id:"th3-thong-tin-26",type:"mc",q:"Vy đọc tờ thông báo: “Thứ Hai mặc đồng phục”. Sáng thứ Hai, Vy nên làm gì?",emoji:"👕",explain:"Thông báo bằng chữ cho Vy biết thứ Hai cần mặc đồng phục.",options:["Mặc đồ ngủ đến trường","Ở nhà không đi học","Mặc đồng phục đến trường","Mặc áo mưa đến trường"],answer:2}]}],challenge:{questions:[{id:"th3-thong-tin-27",type:"mc",q:"Lan nghe bản tin: “Ngày mai có mưa to, gió mạnh”. Quyết định nào hợp lí nhất?",emoji:"🌬️",explain:"Mưa to, gió mạnh thì cần áo mưa và hạn chế ra ngoài cho an toàn.",options:["Rủ bạn đi thả diều ngoài đồng","Đem chăn ra sân phơi cho khô","Rủ các bạn đi tắm sông","Chuẩn bị áo mưa, hạn chế ra ngoài"],answer:3},{id:"th3-thong-tin-28",type:"multi",q:"Đâu là thông tin dạng âm thanh?",explain:"Tiếng còi tàu, tiếng mèo kêu là âm thanh; tấm biển là chữ, bức tranh là hình ảnh.",options:["Tiếng còi tàu","Tiếng mèo kêu","Tấm biển ghi chữ “Lối ra”","Bức tranh con cá"],answers:[0,1]},{id:"th3-thong-tin-29",type:"tf",q:"Thông tin giờ vào lớp có thể báo bằng tiếng trống, cũng có thể viết bằng chữ trên thời khóa biểu.",explain:"Đúng. Một thông tin có thể được thể hiện ở nhiều dạng khác nhau.",answer:!0},{id:"th3-thong-tin-02",type:"match",q:"Nối thông tin với dạng của nó.",explain:"Thông tin thường gặp ở ba dạng: chữ, hình ảnh, âm thanh.",pairs:[["Bức tranh con mèo","Hình ảnh"],["Tiếng còi xe","Âm thanh"],["Một câu trong truyện","Chữ"]]},{id:"th3-thong-tin-12",type:"mc",q:"Đèn tín hiệu dành cho người đi bộ đang bật màu đỏ. Em nên làm gì?",emoji:"🚦",explain:"Đèn đỏ báo phải dừng lại, em đứng chờ đến khi đèn xanh.",options:["Chạy nhanh qua đường","Đi chậm qua đường","Vừa đi vừa nhìn điện thoại","Đứng chờ, chưa sang đường"],answer:3},{id:"th3-thong-tin-13",type:"match",q:"Nối thông tin với quyết định phù hợp.",explain:"Thông tin giúp em biết nên làm gì cho phù hợp.",pairs:[["Trời nắng gắt","Đội mũ khi ra ngoài"],["Bụng đói","Ăn cơm"],["Trống vào lớp","Về chỗ ngồi"],["Đèn xanh cho người đi bộ","Sang đường cẩn thận"]]},{id:"th3-thong-tin-22",type:"match",q:"Nối việc em làm với dạng thông tin em nhận được.",explain:"Nghe là âm thanh, đọc là chữ, xem ảnh là hình ảnh.",pairs:[["Nghe đài phát thanh","Âm thanh"],["Đọc thời khóa biểu","Chữ"],["Xem ảnh chụp cả lớp","Hình ảnh"]]}]},summary:["Thông tin là những gì em nhìn, nghe, đọc được giúp em hiểu biết.","Ba dạng thông tin thường gặp: chữ, hình ảnh, âm thanh.","Thông tin giúp em quyết định nên làm gì cho phù hợp."]},{id:"th3-xu-li-thong-tin",title:"Xử lí thông tin",weeks:[3,4],learn:[{title:"Thu nhận thông tin",text:"Mắt, tai, mũi, lưỡi, da giúp em thu nhận thông tin từ xung quanh.",example:"👀 nhìn  ·  👂 nghe  ·  👃 ngửi"},{title:"Bộ não xử lí thông tin",text:"Bộ não suy nghĩ về thông tin nhận được để em biết phải làm gì.",example:"🧠 suy nghĩ"},{title:"Ba bước",text:"Thu nhận thông tin, xử lí thông tin, rồi đưa ra kết quả là một quyết định hay việc làm.",example:"👀 nhận  ➜  🧠 xử lí  ➜  🏃 làm"},{title:"Máy tính cũng xử lí thông tin",text:"Máy tính nhận thông tin từ bàn phím, chuột, xử lí trong thân máy rồi đưa kết quả ra màn hình, loa.",example:"⌨️ 🖱️  ➜  🖥️ 🔊"}],practice:[{questions:[{id:"th3-xu-li-thong-tin-01",type:"mc",q:"Bộ phận nào của con người xử lí thông tin?",emoji:"🧠",explain:"Bộ não giúp con người suy nghĩ, xử lí thông tin.",options:["Bàn chân","Mái tóc","Móng tay","Bộ não"],answer:3},{id:"th3-xu-li-thong-tin-02",type:"mc",q:"Bộ phận nào giúp em thu nhận thông tin dạng hình ảnh?",emoji:"👀",explain:"Mắt giúp em nhìn thấy hình ảnh, chữ viết.",options:["Mắt","Tai","Mũi","Lưỡi"],answer:0},{id:"th3-xu-li-thong-tin-03",type:"match",q:"Nối giác quan với thông tin em nhận được.",explain:"Mỗi giác quan giúp em thu nhận một loại thông tin.",pairs:[["Mắt","Màu sắc của bông hoa"],["Tai","Tiếng nhạc"],["Mũi","Mùi thơm của bánh"],["Lưỡi","Vị ngọt của kẹo"]]},{id:"th3-xu-li-thong-tin-04",type:"tf",q:"Máy tính cũng có thể xử lí thông tin.",emoji:"🖥️",explain:"Đúng. Máy tính nhận thông tin, xử lí và đưa ra kết quả.",answer:!0},{id:"th3-xu-li-thong-tin-05",type:"tf",q:"Tai giúp em nhìn thấy chữ trên bảng.",explain:"Sai. Em nhìn chữ bằng mắt, tai dùng để nghe.",answer:!1},{id:"th3-xu-li-thong-tin-06",type:"order",q:"Sắp xếp các bước của quá trình xử lí thông tin.",explain:"Đầu tiên thu nhận, sau đó xử lí, cuối cùng đưa ra kết quả.",items:["Thu nhận thông tin","Xử lí thông tin","Đưa ra kết quả"]},{id:"th3-xu-li-thong-tin-07",type:"mc",q:"Máy tính đưa kết quả ra đâu để em nhìn thấy?",emoji:"🖥️",explain:"Màn hình hiện kết quả cho em nhìn thấy.",options:["Bàn phím","Màn hình","Chuột","Dây điện"],answer:1},{id:"th3-xu-li-thong-tin-08",type:"fill",q:"Bộ … giúp con người suy nghĩ và xử lí thông tin.",explain:"Bộ não là nơi xử lí thông tin của con người.",answer:["não"]},{id:"th3-xu-li-thong-tin-09",type:"mc",q:"Em ngửi thấy mùi khét trong bếp. Bộ phận nào nhận thông tin đó?",emoji:"👃",explain:"Mũi giúp em ngửi thấy mùi.",options:["Tai","Mắt","Tóc","Mũi"],answer:3}]},{questions:[{id:"th3-xu-li-thong-tin-10",type:"mc",q:"Em chạm tay vào cốc nước nóng rồi rụt tay lại. Thông tin “nóng” được nhận bằng gì?",emoji:"☕",explain:"Da cảm nhận nóng lạnh, bộ não xử lí và bảo tay rụt lại.",options:["Tai","Da","Mắt","Tóc"],answer:1},{id:"th3-xu-li-thong-tin-11",type:"mc",q:"Đèn đỏ bật, người lái xe dừng xe lại. Việc dừng xe là bước nào?",emoji:"🚗",explain:"Người lái xe nhìn đèn, suy nghĩ rồi dừng xe; dừng xe là kết quả.",options:["Thu nhận thông tin","Đưa ra kết quả","Không liên quan đến thông tin"],answer:1},{id:"th3-xu-li-thong-tin-12",type:"mc",q:"Khi em gõ phím trên bàn phím, máy tính đang làm gì?",emoji:"⌨️",explain:"Bàn phím giúp đưa thông tin vào máy tính.",options:["Tự tắt máy rồi bật lại","Phát bài hát ra loa","In tất cả ra giấy","Nhận thông tin em gõ vào"],answer:3},{id:"th3-xu-li-thong-tin-13",type:"match",q:"Nối bộ phận của máy tính với việc của nó.",explain:"Bàn phím nhận thông tin, thân máy xử lí, màn hình và loa đưa kết quả ra.",pairs:[["Bàn phím","Nhận chữ em gõ vào"],["Thân máy","Xử lí thông tin"],["Màn hình","Hiện kết quả cho em xem"],["Loa","Phát ra âm thanh"]]},{id:"th3-xu-li-thong-tin-14",type:"tf",q:"Mắt là bộ phận xử lí thông tin của con người.",explain:"Sai. Mắt thu nhận thông tin, bộ não mới xử lí thông tin.",answer:!1},{id:"th3-xu-li-thong-tin-15",type:"mc",q:"An nghe cô hỏi, suy nghĩ rồi giơ tay trả lời. Việc suy nghĩ là bước nào?",emoji:"🙋",explain:"Suy nghĩ về câu hỏi chính là xử lí thông tin.",options:["Thu nhận thông tin","Đưa ra kết quả","Xử lí thông tin"],answer:2},{id:"th3-xu-li-thong-tin-16",type:"multi",q:"Những bộ phận nào giúp con người thu nhận thông tin?",explain:"Mắt, tai, mũi thu nhận thông tin; mái tóc thì không.",options:["Mái tóc","Mắt","Tai","Mũi"],answers:[1,2,3]},{id:"th3-xu-li-thong-tin-17",type:"tf",q:"Loa máy tính đưa ra kết quả dạng âm thanh.",emoji:"🔊",explain:"Đúng. Loa phát ra âm thanh như bài hát, tiếng nói.",answer:!0},{id:"th3-xu-li-thong-tin-18",type:"order",q:"Sắp xếp các bước khi máy tính làm một phép tính.",explain:"Máy tính nhận thông tin, xử lí rồi đưa kết quả ra màn hình.",items:["Em gõ phép tính bằng bàn phím","Máy tính tính toán","Kết quả hiện ra trên màn hình"]}]},{questions:[{id:"th3-xu-li-thong-tin-19",type:"mc",q:"Hà nhìn thấy bạn bị ngã nên chạy lại đỡ bạn. Việc Hà nhìn thấy bạn ngã là bước nào?",explain:"Nhìn thấy là thu nhận thông tin bằng mắt.",options:["Thu nhận thông tin","Xử lí thông tin","Đưa ra kết quả"],answer:0},{id:"th3-xu-li-thong-tin-20",type:"mc",q:"Hà thấy bạn ngã nên chạy lại đỡ bạn dậy. Việc chạy lại đỡ bạn là bước nào?",explain:"Chạy lại đỡ bạn là việc làm sau khi Hà đã suy nghĩ, đó là kết quả.",options:["Thu nhận thông tin","Đưa ra kết quả","Xử lí thông tin"],answer:1},{id:"th3-xu-li-thong-tin-21",type:"order",q:"Sắp xếp các bước khi em nghe chuông báo thức.",emoji:"⏰",explain:"Tai thu nhận, não xử lí, rồi em làm việc phù hợp.",items:["Tai nghe tiếng chuông","Bộ não hiểu đã đến giờ dậy","Em ra khỏi giường"]},{id:"th3-xu-li-thong-tin-22",type:"mc",q:"Em gõ câu hỏi vào máy tính, máy tính hiện câu trả lời trên màn hình. Thông tin đưa vào máy tính là gì?",explain:"Câu hỏi em gõ là thông tin vào; câu trả lời là kết quả.",options:["Câu hỏi em gõ vào","Câu trả lời trên màn hình"],answer:0},{id:"th3-xu-li-thong-tin-23",type:"tf",q:"Em dùng máy tính tính 25 + 17, số 42 hiện trên màn hình là kết quả xử lí của máy tính.",explain:"Đúng. Máy tính xử lí phép tính và đưa kết quả 42 ra màn hình.",answer:!0},{id:"th3-xu-li-thong-tin-24",type:"multi",q:"Việc nào là đưa ra kết quả sau khi xử lí thông tin?",explain:"Mở ô, bịt tai là việc làm sau khi suy nghĩ; nhìn và nghe là thu nhận thông tin.",options:["Mở ô khi trời mưa","Bịt tai khi nghe tiếng ồn lớn","Nhìn thấy trời mưa","Nghe tiếng ồn"],answers:[0,1]},{id:"th3-xu-li-thong-tin-25",type:"mc",q:"Nam đọc đề toán, suy nghĩ rồi viết đáp số. Bộ phận nào giúp Nam suy nghĩ?",explain:"Bộ não giúp Nam suy nghĩ, xử lí đề toán.",options:["Bàn tay","Bộ não","Đôi mắt","Cái bút"],answer:1},{id:"th3-xu-li-thong-tin-26",type:"mc",q:"Máy tính và con người giống nhau ở điểm nào?",explain:"Cả hai đều thu nhận, xử lí thông tin và đưa ra kết quả.",options:["Đều cần ăn cơm mỗi ngày","Đều phải đi ngủ buổi tối","Đều xử lí được thông tin","Đều có tóc trên đầu"],answer:2}]}],challenge:{questions:[{id:"th3-xu-li-thong-tin-27",type:"order",q:"Sắp xếp quá trình máy tính phát một bài hát khi em nháy chuột.",emoji:"🎵",explain:"Chuột đưa thông tin vào, thân máy xử lí, loa đưa kết quả ra.",items:["Em nháy chuột vào bài hát","Thân máy xử lí yêu cầu","Loa phát ra bài hát"]},{id:"th3-xu-li-thong-tin-28",type:"mc",q:"Ngọc ngửi thấy mùi khét, nghĩ có thứ bị cháy nên báo ngay cho mẹ. Thông tin vào là gì?",explain:"Mùi khét là thông tin Ngọc thu nhận bằng mũi.",options:["Mùi khét","Việc báo cho mẹ","Suy nghĩ của Ngọc"],answer:0},{id:"th3-xu-li-thong-tin-29",type:"tf",q:"Muốn máy tính làm việc, em cần đưa thông tin vào máy, ví dụ bằng bàn phím hoặc chuột.",explain:"Đúng. Máy tính cần thông tin vào thì mới xử lí được.",answer:!0},{id:"th3-xu-li-thong-tin-03",type:"match",q:"Nối giác quan với thông tin em nhận được.",explain:"Mỗi giác quan giúp em thu nhận một loại thông tin.",pairs:[["Mắt","Màu sắc của bông hoa"],["Tai","Tiếng nhạc"],["Mũi","Mùi thơm của bánh"],["Lưỡi","Vị ngọt của kẹo"]]},{id:"th3-xu-li-thong-tin-13",type:"match",q:"Nối bộ phận của máy tính với việc của nó.",explain:"Bàn phím nhận thông tin, thân máy xử lí, màn hình và loa đưa kết quả ra.",pairs:[["Bàn phím","Nhận chữ em gõ vào"],["Thân máy","Xử lí thông tin"],["Màn hình","Hiện kết quả cho em xem"],["Loa","Phát ra âm thanh"]]},{id:"th3-xu-li-thong-tin-19",type:"mc",q:"Hà nhìn thấy bạn bị ngã nên chạy lại đỡ bạn. Việc Hà nhìn thấy bạn ngã là bước nào?",explain:"Nhìn thấy là thu nhận thông tin bằng mắt.",options:["Thu nhận thông tin","Xử lí thông tin","Đưa ra kết quả"],answer:0},{id:"th3-xu-li-thong-tin-24",type:"multi",q:"Việc nào là đưa ra kết quả sau khi xử lí thông tin?",explain:"Mở ô, bịt tai là việc làm sau khi suy nghĩ; nhìn và nghe là thu nhận thông tin.",options:["Mở ô khi trời mưa","Bịt tai khi nghe tiếng ồn lớn","Nhìn thấy trời mưa","Nghe tiếng ồn"],answers:[0,1]}]},summary:["Con người thu nhận thông tin bằng các giác quan và xử lí bằng bộ não.","Xử lí thông tin gồm: thu nhận, xử lí, đưa ra kết quả.","Máy tính cũng nhận thông tin, xử lí và đưa kết quả ra màn hình, loa."]},{id:"th3-may-tinh",title:"Máy tính và tư thế ngồi đúng",weeks:[5,6],learn:[{title:"Các loại máy tính",text:"Có máy tính để bàn, máy tính xách tay, máy tính bảng, điện thoại thông minh.",example:"🖥️ để bàn  ·  💻 xách tay  ·  📱 bảng, điện thoại"},{title:"Bốn bộ phận cơ bản",text:"Máy tính để bàn có bốn bộ phận cơ bản: màn hình, thân máy, bàn phím và chuột.",example:"🖥️ màn hình  ·  🗄️ thân máy  ·  ⌨️ bàn phím  ·  🖱️ chuột"},{title:"Tư thế ngồi đúng",text:"Lưng thẳng, mắt nhìn thẳng màn hình, ngồi cách màn hình vừa phải, hai chân đặt trên sàn, tay thả lỏng.",example:"🪑 ngồi thẳng lưng"},{title:"Dùng máy an toàn",text:"Không chạm tay ướt vào máy, ổ điện; không ăn uống cạnh máy; dùng lâu thì nghỉ cho mắt.",example:"⚡ cẩn thận điện  ·  💧 tránh nước"}],practice:[{questions:[{id:"th3-may-tinh-01",type:"mc",q:"Bộ phận nào của máy tính hiển thị chữ và hình ảnh?",emoji:"🖥️",explain:"Màn hình hiển thị chữ, hình ảnh để em nhìn thấy.",options:["Bàn phím","Chuột","Màn hình","Thân máy"],answer:2},{id:"th3-may-tinh-02",type:"mc",q:"Bộ phận nào dùng để gõ chữ vào máy tính?",emoji:"⌨️",explain:"Em gõ chữ, số vào máy tính bằng bàn phím.",options:["Màn hình","Loa","Chuột","Bàn phím"],answer:3},{id:"th3-may-tinh-03",type:"match",q:"Nối bộ phận với việc của nó.",explain:"Mỗi bộ phận của máy tính có một việc riêng.",pairs:[["Màn hình","Hiện chữ và hình ảnh"],["Bàn phím","Gõ chữ, gõ số"],["Chuột","Điều khiển con trỏ"],["Thân máy","Xử lí thông tin"]]},{id:"th3-may-tinh-04",type:"number",q:"Máy tính để bàn có bao nhiêu bộ phận cơ bản?",explain:"Bốn bộ phận cơ bản là màn hình, thân máy, bàn phím và chuột.",answer:4,unit:"bộ phận"},{id:"th3-may-tinh-05",type:"tf",q:"Khi ngồi trước máy tính, em nên ngồi thẳng lưng.",emoji:"🪑",explain:"Đúng. Ngồi thẳng lưng giúp em không bị đau lưng, mỏi cổ.",answer:!0},{id:"th3-may-tinh-06",type:"tf",q:"Em có thể chạm vào ổ điện khi tay đang ướt.",emoji:"⚡",explain:"Sai. Tay ướt chạm vào điện rất nguy hiểm, có thể bị điện giật.",answer:!1},{id:"th3-may-tinh-07",type:"multi",q:"Đâu là máy tính?",explain:"Quạt điện không phải máy tính vì không xử lí thông tin.",options:["Máy tính để bàn","Máy tính xách tay","Máy tính bảng","Quạt điện"],answers:[0,1,2]},{id:"th3-may-tinh-08",type:"mc",q:"Chuột máy tính dùng để làm gì?",emoji:"🖱️",explain:"Di chuột thì con trỏ trên màn hình di chuyển theo.",options:["Phát ra âm thanh, tiếng nhạc","Điều khiển con trỏ trên màn hình","Hiển thị hình ảnh và chữ","In bài làm ra giấy"],answer:1},{id:"th3-may-tinh-09",type:"fill",q:"Bộ phận chứa các bộ phận xử lí thông tin của máy tính để bàn là … máy.",explain:"Thân máy chứa các bộ phận xử lí thông tin.",answer:["thân"]}]},{questions:[{id:"th3-may-tinh-10",type:"mc",q:"Loại máy tính nào gấp gọn được, có màn hình và bàn phím gắn liền, dễ mang đi?",emoji:"💻",explain:"Máy tính xách tay gấp gọn, mang đi dễ dàng.",options:["Máy tính xách tay","Máy tính để bàn","Máy giặt","Ti vi"],answer:0},{id:"th3-may-tinh-11",type:"multi",q:"Đâu là tư thế ngồi đúng khi dùng máy tính?",explain:"Cúi sát mặt vào màn hình làm hại mắt và mỏi cổ.",options:["Mắt nhìn thẳng vào màn hình","Hai chân đặt trên sàn","Cúi sát mặt vào màn hình","Lưng thẳng, vai thả lỏng"],answers:[0,1,3]},{id:"th3-may-tinh-12",type:"mc",q:"Vì sao không nên ngồi quá gần màn hình máy tính?",explain:"Ngồi quá gần màn hình làm mắt nhanh mỏi, lâu ngày hại mắt.",options:["Vì màn hình sẽ vỡ","Vì chuột không chạy","Vì dễ mỏi mắt, hại mắt","Vì máy tính sẽ tắt"],answer:2},{id:"th3-may-tinh-13",type:"tf",q:"Ăn uống ngay cạnh bàn phím không thể làm hỏng máy tính.",explain:"Sai. Nước và vụn thức ăn rơi vào có thể làm hỏng bàn phím, máy tính.",answer:!1},{id:"th3-may-tinh-14",type:"match",q:"Nối việc em muốn làm với bộ phận cần dùng.",explain:"Mỗi việc cần dùng một bộ phận phù hợp.",pairs:[["Gõ chữ","Bàn phím"],["Xem hình ảnh","Màn hình"],["Nghe nhạc","Loa"],["Di chuyển con trỏ","Chuột"]]},{id:"th3-may-tinh-15",type:"mc",q:"Phòng máy nên có ánh sáng như thế nào?",emoji:"💡",explain:"Phòng đủ sáng và không bị chói giúp mắt đỡ mỏi.",options:["Tắt hết đèn cho phòng thật tối","Đủ sáng, không bị chói màn hình","Nắng chiếu thẳng vào màn hình","Chỉ có ánh sáng từ màn hình"],answer:1},{id:"th3-may-tinh-16",type:"tf",q:"Ngồi dùng máy tính liên tục nhiều giờ liền không nghỉ là tốt cho sức khỏe.",explain:"Sai. Dùng máy lâu cần nghỉ giải lao cho mắt và cơ thể.",answer:!1},{id:"th3-may-tinh-17",type:"multi",q:"Việc nào giúp dùng máy tính an toàn?",explain:"Tự tháo thân máy rất nguy hiểm và dễ làm hỏng máy.",options:["Tự tháo thân máy ra xem","Không chạm tay ướt vào máy và ổ điện","Không kéo, giật dây điện","Không để cốc nước gần bàn phím"],answers:[1,2,3]},{id:"th3-may-tinh-18",type:"mc",q:"Điện thoại thông minh có phải là một loại máy tính không?",emoji:"📱",explain:"Điện thoại thông minh cũng nhận, xử lí thông tin như máy tính.",options:["Có, vì nó cũng xử lí thông tin","Không, vì nó quá nhỏ để là máy tính"],answer:0}]},{questions:[{id:"th3-may-tinh-19",type:"mc",q:"Bình ngồi dùng máy tính mà lưng cong, mặt sát màn hình. Em nhắc Bình thế nào?",explain:"Ngồi thẳng lưng, cách màn hình vừa phải là tư thế đúng.",options:["Cúi sát hơn nữa để nhìn cho rõ","Ngồi thẳng lưng, lùi xa màn hình một chút","Nằm gục ra bàn mà dùng cho đỡ mỏi","Không cần nhắc vì Bình đang vui"],answer:1},{id:"th3-may-tinh-20",type:"mc",q:"Lan thấy dây điện của máy tính bị hở. Lan nên làm gì?",emoji:"⚡",explain:"Dây điện hở rất nguy hiểm, cần báo người lớn xử lí.",options:["Lấy băng dính tự quấn lại dây điện","Kéo mạnh dây ra khỏi ổ điện","Vẫn dùng máy như bình thường","Không chạm vào, báo ngay người lớn"],answer:3},{id:"th3-may-tinh-21",type:"mc",q:"Khoa dùng máy tính đã lâu, mắt thấy mỏi. Khoa nên làm gì?",explain:"Nghỉ ngơi, nhìn ra xa giúp mắt đỡ mỏi.",options:["Nghỉ ngơi, nhìn ra xa","Dụi mắt thật mạnh","Ngồi sát màn hình hơn","Dùng tiếp thêm vài giờ"],answer:0},{id:"th3-may-tinh-22",type:"order",q:"Sắp xếp các việc khi làm bài ở phòng máy.",explain:"Bật máy, làm bài, xong việc thì tắt máy đúng cách.",items:["Bật máy tính theo hướng dẫn","Làm bài theo yêu cầu","Tắt máy đúng cách khi xong việc"]},{id:"th3-may-tinh-23",type:"tf",q:"Khi không thấy rõ chữ trên màn hình, em nên dí sát mắt vào màn hình.",explain:"Sai. Em nên nhờ thầy cô chỉnh cỡ chữ hoặc độ sáng, không dí sát mắt.",answer:!1},{id:"th3-may-tinh-24",type:"mc",q:"Nắng chiếu vào màn hình làm chói mắt. Cách xử lí hợp lí là gì?",emoji:"☀️",explain:"Kéo rèm hoặc đổi vị trí máy giúp màn hình không bị chói.",options:["Kéo rèm hoặc nhờ thầy cô đổi chỗ máy","Nheo mắt lại rồi nhìn tiếp","Tắt màn hình đi rồi gõ tiếp bài"],answer:0},{id:"th3-may-tinh-25",type:"multi",q:"Thiết bị nào em có thể mang theo dễ dàng khi đi xa?",explain:"Máy tính để bàn có nhiều bộ phận rời, khó mang đi.",options:["Máy tính xách tay","Máy tính bảng","Điện thoại thông minh","Máy tính để bàn"],answers:[0,1,2]},{id:"th3-may-tinh-26",type:"mc",q:"Minh muốn nghe bài hát trên máy tính. Minh cần bộ phận nào?",emoji:"🎧",explain:"Loa hoặc tai nghe phát ra âm thanh.",options:["Bàn phím và chuột","Loa hoặc tai nghe","Máy in","Thân máy"],answer:1}]}],challenge:{questions:[{id:"th3-may-tinh-27",type:"mc",q:"Thiết bị nào KHÔNG thuộc bốn bộ phận cơ bản của máy tính để bàn?",emoji:"🖨️",explain:"Máy in là thiết bị thêm; bốn bộ phận cơ bản là màn hình, thân máy, bàn phím, chuột.",options:["Màn hình","Bàn phím","Máy in","Chuột"],answer:2},{id:"th3-may-tinh-28",type:"multi",q:"Bạn nào đang ngồi đúng tư thế?",explain:"Chi và Thảo ngồi đúng; Dũng và Tùng ngồi sai tư thế.",options:["Tùng cúi gập lưng sát màn hình","Chi ngồi thẳng lưng, mắt nhìn thẳng màn hình","Dũng ngồi vắt chân lên ghế","Thảo đặt hai chân trên sàn, tay thả lỏng"],answers:[1,3]},{id:"th3-may-tinh-29",type:"tf",q:"Rút phích cắm điện khi máy đang chạy là cách tắt máy tính đúng.",explain:"Sai. Em tắt máy theo hướng dẫn trên màn hình, không rút điện đột ngột.",answer:!1},{id:"th3-may-tinh-11",type:"multi",q:"Đâu là tư thế ngồi đúng khi dùng máy tính?",explain:"Cúi sát mặt vào màn hình làm hại mắt và mỏi cổ.",options:["Mắt nhìn thẳng vào màn hình","Hai chân đặt trên sàn","Cúi sát mặt vào màn hình","Lưng thẳng, vai thả lỏng"],answers:[0,1,3]},{id:"th3-may-tinh-17",type:"multi",q:"Việc nào giúp dùng máy tính an toàn?",explain:"Tự tháo thân máy rất nguy hiểm và dễ làm hỏng máy.",options:["Tự tháo thân máy ra xem","Không chạm tay ướt vào máy và ổ điện","Không kéo, giật dây điện","Không để cốc nước gần bàn phím"],answers:[1,2,3]},{id:"th3-may-tinh-20",type:"mc",q:"Lan thấy dây điện của máy tính bị hở. Lan nên làm gì?",emoji:"⚡",explain:"Dây điện hở rất nguy hiểm, cần báo người lớn xử lí.",options:["Lấy băng dính tự quấn lại dây điện","Kéo mạnh dây ra khỏi ổ điện","Vẫn dùng máy như bình thường","Không chạm vào, báo ngay người lớn"],answer:3},{id:"th3-may-tinh-14",type:"match",q:"Nối việc em muốn làm với bộ phận cần dùng.",explain:"Mỗi việc cần dùng một bộ phận phù hợp.",pairs:[["Gõ chữ","Bàn phím"],["Xem hình ảnh","Màn hình"],["Nghe nhạc","Loa"],["Di chuyển con trỏ","Chuột"]]}]},summary:["Máy tính để bàn có bốn bộ phận cơ bản: màn hình, thân máy, bàn phím, chuột.","Ngồi thẳng lưng, mắt nhìn thẳng màn hình, cách màn hình vừa phải.","Dùng máy tính an toàn: tránh nước, cẩn thận với điện, nghỉ ngơi cho mắt."]},{id:"th3-chuot",title:"Làm quen với chuột máy tính",weeks:[7,8],learn:[{title:"Cầm chuột đúng cách",text:"Úp bàn tay lên chuột, ngón trỏ đặt lên nút trái, ngón giữa đặt lên nút phải, ngón cái và các ngón còn lại giữ hai bên chuột.",example:"🖱️ nút trái  ·  nút phải"},{title:"Con trỏ chuột",text:"Khi em di chuyển chuột trên bàn, con trỏ chuột trên màn hình di chuyển theo.",example:"🖱️ di chuột  ➜  ↖️ con trỏ"},{title:"Nháy chuột và nháy đúp",text:"Nháy chuột: nhấn nút trái một lần rồi thả. Nháy đúp: nhấn nhanh hai lần liên tiếp nút trái. Nháy chuột phải: nhấn nút phải một lần.",example:"👆 một lần  ·  👆👆 hai lần nhanh"},{title:"Kéo thả chuột",text:"Nhấn và giữ nút trái chuột, di chuyển chuột đến chỗ mới rồi thả nút chuột ra.",example:"✊ giữ  ➜  ↔️ kéo  ➜  ✋ thả"}],practice:[{questions:[{id:"th3-chuot-01",type:"mc",q:"Khi cầm chuột, ngón trỏ đặt lên đâu?",emoji:"🖱️",explain:"Ngón trỏ đặt lên nút trái, ngón giữa đặt lên nút phải.",options:["Nút phải của chuột","Mặt dưới của chuột","Nút trái của chuột"],answer:2},{id:"th3-chuot-02",type:"mc",q:"Khi cầm chuột, ngón giữa đặt lên nút nào?",explain:"Ngón giữa đặt lên nút phải của chuột.",options:["Nút phải","Nút trái","Không đặt lên nút nào"],answer:0},{id:"th3-chuot-03",type:"match",q:"Nối thao tác với cách làm.",explain:"Đây là các thao tác cơ bản với chuột.",pairs:[["Nháy chuột","Nhấn nút trái một lần rồi thả"],["Nháy đúp chuột","Nhấn nhanh hai lần nút trái"],["Nháy chuột phải","Nhấn nút phải một lần"],["Kéo thả chuột","Giữ nút trái, di chuyển rồi thả"]]},{id:"th3-chuot-04",type:"tf",q:"Khi em di chuyển chuột trên bàn, con trỏ chuột trên màn hình cũng di chuyển theo.",explain:"Đúng. Con trỏ chuột di chuyển theo chuột.",answer:!0},{id:"th3-chuot-05",type:"tf",q:"Nháy đúp chuột là nhấn nút phải một lần.",explain:"Sai. Nháy đúp là nhấn nhanh hai lần liên tiếp nút trái chuột.",answer:!1},{id:"th3-chuot-06",type:"fill",q:"Nhấn nhanh hai lần liên tiếp nút trái chuột gọi là nháy …",explain:"Nhấn nhanh hai lần nút trái gọi là nháy đúp chuột.",answer:["đúp"]},{id:"th3-chuot-07",type:"mc",q:"Mũi tên nhỏ di chuyển trên màn hình khi em di chuột gọi là gì?",emoji:"↖️",explain:"Mũi tên đó là con trỏ chuột.",options:["Nút bàn phím","Thân máy tính","Con trỏ chuột"],answer:2},{id:"th3-chuot-08",type:"tf",q:"Em nên cầm chuột nhẹ nhàng, không đập mạnh chuột xuống bàn.",explain:"Đúng. Đập mạnh có thể làm hỏng chuột.",answer:!0},{id:"th3-chuot-09",type:"multi",q:"Thao tác nào dùng nút trái chuột?",explain:"Nháy chuột phải dùng nút phải; các thao tác còn lại dùng nút trái.",options:["Kéo thả chuột","Nháy chuột phải","Nháy chuột","Nháy đúp chuột"],answers:[0,2,3]}]},{questions:[{id:"th3-chuot-10",type:"mc",q:"Muốn mở một biểu tượng trên màn hình nền, em thường làm thao tác nào?",explain:"Nháy đúp chuột vào biểu tượng để mở nó.",options:["Nháy đúp chuột vào biểu tượng","Nhấn phím cách hai lần","Lắc chuột thật mạnh","Kéo dây chuột ra khỏi máy tính"],answer:0},{id:"th3-chuot-11",type:"mc",q:"Muốn di chuyển một hình sang chỗ khác trên màn hình, em dùng thao tác nào?",explain:"Kéo thả chuột giúp đưa hình sang chỗ mới.",options:["Kéo thả chuột","Nháy chuột phải","Nháy đúp chuột"],answer:0},{id:"th3-chuot-12",type:"order",q:"Sắp xếp các bước kéo thả chuột.",explain:"Trỏ vào hình, giữ nút trái, di chuyển rồi thả.",items:["Đưa con trỏ chuột vào hình cần di chuyển","Nhấn và giữ nút trái chuột","Di chuyển chuột đến vị trí mới","Thả nút trái chuột"]},{id:"th3-chuot-13",type:"tf",q:"Khi kéo thả, em phải giữ nút trái chuột trong lúc di chuyển chuột.",explain:"Đúng. Giữ nút trái trong lúc di chuyển thì hình mới đi theo.",answer:!0},{id:"th3-chuot-14",type:"mc",q:"Để chọn nút “Bắt đầu chơi” trên màn hình, em làm gì?",explain:"Nháy chuột vào nút lệnh để chọn nút đó.",options:["Nháy chuột vào nút đó","Kéo thả nút đó","Nhấn giữ nút phải thật lâu"],answer:0},{id:"th3-chuot-15",type:"match",q:"Nối việc cần làm với thao tác chuột.",explain:"Mỗi việc dùng một thao tác chuột phù hợp.",pairs:[["Mở một thư mục","Nháy đúp chuột"],["Chọn một nút lệnh","Nháy chuột"],["Đưa mảnh ghép sang ô khác","Kéo thả chuột"]]},{id:"th3-chuot-16",type:"tf",q:"Khi nháy đúp, hai lần nhấn phải cách nhau thật lâu.",explain:"Sai. Hai lần nhấn phải nhanh, liền nhau thì máy mới hiểu là nháy đúp.",answer:!1},{id:"th3-chuot-17",type:"mc",q:"Khi cầm chuột đúng cách, ngón cái đặt ở đâu?",explain:"Ngón cái giữ bên cạnh chuột.",options:["Bên cạnh chuột","Trên nút trái","Trên nút phải"],answer:0},{id:"th3-chuot-18",type:"mc",q:"Chuột chạy ra sát mép bàn, không di chuyển tiếp được. Em làm thế nào?",explain:"Nhấc chuột lên thì con trỏ đứng yên, đặt lại vào giữa rồi di tiếp.",options:["Nhấc chuột lên, đặt vào giữa bàn","Đẩy chuột rơi xuống đất cho xong","Lắc chuột thật mạnh","Tắt máy tính"],answer:0}]},{questions:[{id:"th3-chuot-19",type:"mc",q:"An nháy đúp vào biểu tượng nhưng chưa mở được vì nhấn hai lần quá chậm. An nên làm gì?",explain:"Nháy đúp cần nhấn hai lần thật nhanh, liền nhau.",options:["Nhấn nút phải thật nhiều lần","Nháy đúp lại, nhấn nhanh hơn","Đập chuột xuống bàn","Rút dây chuột ra"],answer:1},{id:"th3-chuot-20",type:"mc",q:"Trò chơi ghép hình yêu cầu đưa mảnh ghép vào đúng chỗ. Em dùng thao tác nào?",emoji:"🧩",explain:"Kéo thả chuột để đưa mảnh ghép đến chỗ mới.",options:["Kéo thả chuột","Nháy chuột phải","Gõ phím cách"],answer:0},{id:"th3-chuot-21",type:"order",q:"Sắp xếp các bước mở một biểu tượng trò chơi trên màn hình.",explain:"Đưa con trỏ đến biểu tượng rồi nháy đúp để mở.",items:["Di chuột đưa con trỏ đến biểu tượng","Nháy đúp chuột vào biểu tượng","Chờ trò chơi mở ra"]},{id:"th3-chuot-22",type:"multi",q:"Bạn nào cầm chuột đúng cách?",explain:"Chi và Vy cầm chuột đúng; Nam và Dũng cầm sai.",options:["Nam nắm chặt chuột, nhấc lên cao","Vy đặt ngón giữa lên nút phải, cổ tay thả lỏng","Dũng cầm dây chuột để kéo chuột đi","Chi úp bàn tay lên chuột, ngón trỏ ở nút trái"],answers:[1,3]},{id:"th3-chuot-23",type:"tf",q:"Ở nhiều chỗ trên màn hình, nháy chuột phải sẽ mở ra một bảng chọn nhỏ.",explain:"Đúng. Nháy chuột phải thường mở bảng chọn với các lệnh thường dùng.",answer:!0},{id:"th3-chuot-24",type:"mc",q:"Hà muốn đưa con trỏ chuột sang bên phải màn hình. Hà làm thế nào?",explain:"Di chuột sang phải thì con trỏ cũng sang phải.",options:["Nhấn giữ nút phải của chuột","Nháy đúp chuột","Nhấc chuột lên cao","Di chuột trên bàn sang phải"],answer:3},{id:"th3-chuot-25",type:"mc",q:"Trong trò chơi tô màu, Ngọc muốn tô bông hoa màu đỏ. Ngọc làm thế nào?",emoji:"🌺",explain:"Chọn màu trước, rồi nháy chuột vào chỗ cần tô.",options:["Nháy chuột phải vào phím cách","Kéo thả bông hoa ra ngoài màn hình","Chọn màu đỏ, rồi nháy vào bông hoa"],answer:2},{id:"th3-chuot-26",type:"tf",q:"Dùng chuột xong, em có thể để chuột lung tung, treo lủng lẳng mép bàn.",explain:"Sai. Em để chuột gọn gàng để giữ gìn đồ dùng chung.",answer:!1}]}],challenge:{questions:[{id:"th3-chuot-27",type:"match",q:"Nối tình huống với thao tác chuột phù hợp.",explain:"Chọn đúng thao tác giúp em làm việc nhanh với máy tính.",pairs:[["Mở thư mục bài hát","Nháy đúp chuột"],["Xếp quả táo vào giỏ trong trò chơi","Kéo thả chuột"],["Chọn đáp án A trong bài tập","Nháy chuột"],["Mở bảng chọn nhỏ","Nháy chuột phải"]]},{id:"th3-chuot-28",type:"order",q:"Sắp xếp các bước đưa quả táo vào giỏ trên màn hình.",emoji:"🍎",explain:"Đây là các bước kéo thả chuột.",items:["Đưa con trỏ chuột đến quả táo","Nhấn giữ nút trái chuột","Kéo quả táo đến chiếc giỏ","Thả nút trái chuột"]},{id:"th3-chuot-29",type:"multi",q:"Câu nào nói đúng về chuột máy tính?",explain:"Nháy đúp là nhấn nhanh hai lần nút trái, không phải nút phải.",options:["Chuột thường có nút trái và nút phải","Di chuột thì con trỏ di chuyển theo","Nháy đúp là nhấn nút phải hai lần","Kéo thả cần giữ nút trái chuột"],answers:[0,1,3]},{id:"th3-chuot-03",type:"match",q:"Nối thao tác với cách làm.",explain:"Đây là các thao tác cơ bản với chuột.",pairs:[["Nháy chuột","Nhấn nút trái một lần rồi thả"],["Nháy đúp chuột","Nhấn nhanh hai lần nút trái"],["Nháy chuột phải","Nhấn nút phải một lần"],["Kéo thả chuột","Giữ nút trái, di chuyển rồi thả"]]},{id:"th3-chuot-12",type:"order",q:"Sắp xếp các bước kéo thả chuột.",explain:"Trỏ vào hình, giữ nút trái, di chuyển rồi thả.",items:["Đưa con trỏ chuột vào hình cần di chuyển","Nhấn và giữ nút trái chuột","Di chuyển chuột đến vị trí mới","Thả nút trái chuột"]},{id:"th3-chuot-15",type:"match",q:"Nối việc cần làm với thao tác chuột.",explain:"Mỗi việc dùng một thao tác chuột phù hợp.",pairs:[["Mở một thư mục","Nháy đúp chuột"],["Chọn một nút lệnh","Nháy chuột"],["Đưa mảnh ghép sang ô khác","Kéo thả chuột"]]},{id:"th3-chuot-22",type:"multi",q:"Bạn nào cầm chuột đúng cách?",explain:"Chi và Vy cầm chuột đúng; Nam và Dũng cầm sai.",options:["Nam nắm chặt chuột, nhấc lên cao","Vy đặt ngón giữa lên nút phải, cổ tay thả lỏng","Dũng cầm dây chuột để kéo chuột đi","Chi úp bàn tay lên chuột, ngón trỏ ở nút trái"],answers:[1,3]}]},summary:["Ngón trỏ đặt lên nút trái, ngón giữa đặt lên nút phải của chuột.","Các thao tác với chuột: nháy chuột, nháy đúp, nháy chuột phải, kéo thả.","Di chuột trên bàn thì con trỏ trên màn hình di chuyển theo."]},{id:"th3-ban-phim",title:"Bàn phím và hàng phím cơ sở",weeks:[9,11],learn:[{title:"Các hàng phím",text:"Khu vực chính của bàn phím có hàng phím số, hàng phím trên, hàng phím cơ sở, hàng phím dưới và hàng có phím cách.",example:"⌨️ số  ·  trên  ·  cơ sở  ·  dưới"},{title:"Hàng phím cơ sở",text:"Hàng phím cơ sở có các phím A, S, D, F, G, H, J, K, L. Hai phím F và J có gờ nổi nhỏ để đặt hai ngón trỏ.",example:"A S D F G H J K L"},{title:"Đặt tay đúng",text:"Tay trái: ngón út ở A, áp út ở S, giữa ở D, trỏ ở F. Tay phải: trỏ ở J, giữa ở K, áp út ở L. Hai ngón cái đặt trên phím cách.",example:"🤚 A S D F  ·  J K L 🤚"},{title:"Gõ phím đúng cách",text:"Gõ nhẹ, dứt khoát; gõ xong đưa ngón tay về hàng phím cơ sở; tập gõ mà mắt nhìn màn hình.",example:"👀 nhìn màn hình"}],practice:[{questions:[{id:"th3-ban-phim-01",type:"mc",q:"Hai phím nào trên hàng phím cơ sở có gờ nổi nhỏ?",emoji:"⌨️",explain:"Phím F và J có gờ nổi để đặt hai ngón trỏ.",options:["A và L","G và H","D và K","F và J"],answer:3},{id:"th3-ban-phim-02",type:"mc",q:"Ngón trỏ tay trái đặt lên phím nào?",explain:"Ngón trỏ tay trái đặt lên phím F.",options:["F","J","A","D"],answer:0},{id:"th3-ban-phim-03",type:"mc",q:"Ngón trỏ tay phải đặt lên phím nào?",explain:"Ngón trỏ tay phải đặt lên phím J.",options:["F","J","K","H"],answer:1},{id:"th3-ban-phim-04",type:"tf",q:"Hai ngón cái đặt trên phím cách.",explain:"Đúng. Hai ngón cái đặt nhẹ trên phím cách.",answer:!0},{id:"th3-ban-phim-05",type:"match",q:"Nối ngón tay trái với phím trên hàng phím cơ sở.",explain:"Tay trái đặt lần lượt trên A, S, D, F.",pairs:[["Ngón út","A"],["Ngón áp út","S"],["Ngón giữa","D"],["Ngón trỏ","F"]]},{id:"th3-ban-phim-06",type:"fill",q:"Hàng phím có hai phím F và J được gọi là hàng phím …",explain:"Đó là hàng phím cơ sở, nơi em đặt tay khi gõ.",answer:["cơ sở"]},{id:"th3-ban-phim-07",type:"tf",q:"Phím A nằm trên hàng phím cơ sở.",explain:"Đúng. Phím A ở đầu bên trái hàng phím cơ sở.",answer:!0},{id:"th3-ban-phim-08",type:"multi",q:"Những phím nào nằm trên hàng phím cơ sở?",explain:"A, S, K thuộc hàng cơ sở; Q ở hàng trên, M ở hàng dưới.",options:["A","S","Q","K","M"],answers:[0,1,3]},{id:"th3-ban-phim-09",type:"tf",q:"Khi gõ phím, em nên đập thật mạnh để máy nhận chữ.",explain:"Sai. Em gõ nhẹ, dứt khoát là máy đã nhận chữ.",answer:!1}]},{questions:[{id:"th3-ban-phim-10",type:"mc",q:"Ngón giữa tay phải đặt lên phím nào?",explain:"Ngón giữa tay phải đặt lên phím K.",options:["D","K","L","J"],answer:1},{id:"th3-ban-phim-11",type:"match",q:"Nối ngón tay phải với phím trên hàng phím cơ sở.",explain:"Tay phải đặt lần lượt trên J, K, L.",pairs:[["Ngón trỏ","J"],["Ngón giữa","K"],["Ngón áp út","L"]]},{id:"th3-ban-phim-12",type:"mc",q:"Vì sao hai phím F và J có gờ nổi nhỏ?",explain:"Sờ thấy gờ nổi, em biết đã đặt đúng ngón trỏ.",options:["Để trang trí cho bàn phím đẹp hơn","Vì phím bị hỏng","Để gõ chữ in hoa","Để đặt đúng ngón trỏ không cần nhìn"],answer:3},{id:"th3-ban-phim-13",type:"mc",q:"Phím G do ngón nào gõ?",explain:"Ngón trỏ tay trái gõ phím F và phím G bên cạnh.",options:["Ngón trỏ tay trái","Ngón trỏ tay phải","Ngón út tay trái","Ngón cái"],answer:0},{id:"th3-ban-phim-14",type:"mc",q:"Phím H do ngón nào gõ?",explain:"Ngón trỏ tay phải gõ phím J và phím H bên cạnh.",options:["Ngón trỏ tay trái","Ngón trỏ tay phải","Ngón út tay phải","Ngón giữa tay phải"],answer:1},{id:"th3-ban-phim-15",type:"tf",q:"Gõ xong một phím, ngón tay nên trở về hàng phím cơ sở.",explain:"Đúng. Ngón tay về hàng cơ sở để gõ phím tiếp theo cho chính xác.",answer:!0},{id:"th3-ban-phim-16",type:"order",q:"Sắp xếp các hàng phím từ trên xuống dưới.",explain:"Từ trên xuống: hàng số, hàng trên, hàng cơ sở, hàng dưới.",items:["Hàng phím số","Hàng phím trên","Hàng phím cơ sở","Hàng phím dưới"]},{id:"th3-ban-phim-17",type:"mc",q:"Hàng phím nào nằm ngay trên hàng phím cơ sở?",explain:"Hàng phím trên có Q, W, E… nằm ngay trên hàng cơ sở.",options:["Hàng phím trên","Hàng phím dưới","Hàng phím số"],answer:0},{id:"th3-ban-phim-18",type:"multi",q:"Những phím nào thuộc hàng phím trên?",explain:"Q, W, E ở hàng phím trên; A ở hàng cơ sở, Z ở hàng dưới.",options:["W","E","A","Z","Q"],answers:[0,1,4]}]},{questions:[{id:"th3-ban-phim-19",type:"mc",q:"Khi gõ chữ “an”, ngón nào gõ phím A?",explain:"Phím A do ngón út tay trái gõ.",options:["Ngón trỏ tay phải","Ngón cái","Ngón út tay trái","Ngón giữa tay trái"],answer:2},{id:"th3-ban-phim-20",type:"mc",q:"Khi gõ chữ “la”, phím L do ngón nào gõ?",explain:"Phím L do ngón áp út tay phải gõ.",options:["Ngón áp út tay phải","Ngón út tay trái","Ngón trỏ tay phải","Ngón giữa tay phải"],answer:0},{id:"th3-ban-phim-21",type:"order",q:"Sắp xếp các bước chuẩn bị gõ phím.",explain:"Ngồi đúng, tìm F và J, đặt ngón trỏ rồi đặt các ngón còn lại.",items:["Ngồi đúng tư thế","Tìm hai phím có gờ F và J","Đặt hai ngón trỏ lên F và J","Đặt các ngón còn lại lên hàng phím cơ sở"]},{id:"th3-ban-phim-22",type:"mc",q:"Phúc vừa gõ vừa cúi xuống nhìn bàn phím. Cách gõ tốt hơn là gì?",explain:"Đặt tay đúng và tập nhìn màn hình giúp gõ nhanh, ít mỏi cổ.",options:["Cúi thật sát xuống nhìn bàn phím mãi","Chỉ gõ bằng một ngón","Đặt tay đúng, tập gõ mà nhìn màn hình","Gõ thật mạnh"],answer:2},{id:"th3-ban-phim-23",type:"tf",q:"Khi đã luyện tập, gõ bàn phím bằng mười ngón giúp gõ nhanh và chính xác hơn.",explain:"Đúng. Mỗi ngón phụ trách một số phím nên gõ nhanh hơn.",answer:!0},{id:"th3-ban-phim-24",type:"mc",q:"Để gõ chữ “sa”, em dùng những ngón nào của tay trái?",explain:"Phím S do ngón áp út, phím A do ngón út tay trái gõ.",options:["Ngón trỏ và ngón giữa","Ngón áp út và ngón út","Ngón cái và ngón trỏ"],answer:1},{id:"th3-ban-phim-25",type:"mc",q:"Khi luyện gõ, Chi gõ phím D bằng ngón trỏ tay phải. Chi gõ đúng chưa?",explain:"Phím D do ngón giữa tay trái gõ.",options:["Đúng rồi","Chưa đúng, phím D do ngón út tay phải gõ","Chưa đúng, phím D do ngón giữa tay trái gõ"],answer:2},{id:"th3-ban-phim-26",type:"multi",q:"Những phím nào do các ngón tay trái gõ khi đặt tay ở hàng phím cơ sở?",explain:"A, S, D do tay trái gõ; J, K do tay phải gõ.",options:["A","S","D","J","K"],answers:[0,1,2]}]}],challenge:{questions:[{id:"th3-ban-phim-27",type:"match",q:"Nối phím với ngón tay gõ phím đó.",explain:"Mỗi phím trên hàng cơ sở có một ngón tay phụ trách.",pairs:[["F","Ngón trỏ tay trái"],["J","Ngón trỏ tay phải"],["S","Ngón áp út tay trái"],["K","Ngón giữa tay phải"]]},{id:"th3-ban-phim-28",type:"mc",q:"Khi gõ chữ “lan”, phím N nằm ở hàng phím nào?",explain:"Phím N nằm ở hàng phím dưới, cùng hàng với Z, X, C, V, B, M.",options:["Hàng phím dưới","Hàng phím cơ sở","Hàng phím trên","Hàng phím số"],answer:0},{id:"th3-ban-phim-29",type:"multi",q:"Câu nào đúng về cách gõ phím?",explain:"Phím J do ngón trỏ tay phải gõ, không phải ngón út tay trái.",options:["Ngón trỏ phải gõ phím J và H","Ngón cái gõ phím cách","Ngón út trái gõ phím J","Ngón trỏ trái gõ phím F và G"],answers:[0,1,3]},{id:"th3-ban-phim-05",type:"match",q:"Nối ngón tay trái với phím trên hàng phím cơ sở.",explain:"Tay trái đặt lần lượt trên A, S, D, F.",pairs:[["Ngón út","A"],["Ngón áp út","S"],["Ngón giữa","D"],["Ngón trỏ","F"]]},{id:"th3-ban-phim-12",type:"mc",q:"Vì sao hai phím F và J có gờ nổi nhỏ?",explain:"Sờ thấy gờ nổi, em biết đã đặt đúng ngón trỏ.",options:["Để trang trí cho bàn phím đẹp hơn","Vì phím bị hỏng","Để gõ chữ in hoa","Để đặt đúng ngón trỏ không cần nhìn"],answer:3},{id:"th3-ban-phim-21",type:"order",q:"Sắp xếp các bước chuẩn bị gõ phím.",explain:"Ngồi đúng, tìm F và J, đặt ngón trỏ rồi đặt các ngón còn lại.",items:["Ngồi đúng tư thế","Tìm hai phím có gờ F và J","Đặt hai ngón trỏ lên F và J","Đặt các ngón còn lại lên hàng phím cơ sở"]},{id:"th3-ban-phim-25",type:"mc",q:"Khi luyện gõ, Chi gõ phím D bằng ngón trỏ tay phải. Chi gõ đúng chưa?",explain:"Phím D do ngón giữa tay trái gõ.",options:["Đúng rồi","Chưa đúng, phím D do ngón út tay phải gõ","Chưa đúng, phím D do ngón giữa tay trái gõ"],answer:2}]},summary:["Hàng phím cơ sở có A, S, D, F, G, H, J, K, L; phím F và J có gờ nổi.","Hai ngón trỏ đặt trên F và J, hai ngón cái đặt trên phím cách.","Gõ nhẹ, gõ xong đưa ngón tay về hàng phím cơ sở."]}]},{id:"mang-may-tinh-internet",title:"Mạng máy tính và Internet",lessons:[{id:"th3-internet",title:"Khám phá thông tin trên Internet",weeks:[12,13],learn:[{title:"Internet là gì?",text:"Internet là mạng kết nối rất nhiều máy tính trên khắp thế giới. Trên Internet có tin tức, bài học, truyện, phim, trò chơi.",example:"🌐 Internet"},{title:"Xem tin tức, giải trí",text:"Em có thể xem tin tức, nghe nhạc thiếu nhi, xem video học tập, đọc truyện trên các trang phù hợp lứa tuổi.",example:"📰 tin tức  ·  🎵 nhạc  ·  📚 truyện"},{title:"Phù hợp và không phù hợp",text:"Có thông tin bổ ích, phù hợp với em. Có thông tin không phù hợp như hình ảnh bạo lực, đáng sợ, lời lẽ thô tục.",example:"✅ bổ ích  ·  ❌ không phù hợp"},{title:"Dùng Internet đúng lúc",text:"Em dùng Internet khi được bố mẹ, thầy cô cho phép và trong thời gian hợp lí. Gặp thông tin xấu, em tắt đi và báo người lớn.",example:"⏰ đúng giờ  ·  👨‍👩‍👧 hỏi người lớn"}],practice:[{questions:[{id:"th3-internet-01",type:"mc",q:"Internet là gì?",emoji:"🌐",explain:"Internet là mạng kết nối rất nhiều máy tính trên khắp thế giới.",options:["Mạng kết nối nhiều máy tính trên thế giới","Một loại bàn phím mới có nhiều phím","Một quyển sách giấy rất dày","Một trò chơi chơi ngoài sân trường"],answer:0},{id:"th3-internet-02",type:"multi",q:"Em có thể làm gì trên Internet?",explain:"Ăn cơm là việc ngoài đời, không làm trên Internet.",options:["Xem video bài học","Nghe nhạc thiếu nhi","Ăn cơm","Xem tin tức"],answers:[0,1,3]},{id:"th3-internet-03",type:"tf",q:"Mọi thông tin trên Internet đều phù hợp với trẻ em.",explain:"Sai. Trên Internet có cả thông tin không phù hợp với trẻ em.",answer:!1},{id:"th3-internet-04",type:"tf",q:"Khi gặp hình ảnh đáng sợ trên Internet, em nên tắt đi và báo cho người lớn.",explain:"Đúng. Người lớn sẽ giúp em xử lí và chọn nội dung phù hợp.",answer:!0},{id:"th3-internet-05",type:"mc",q:"Em nên dùng Internet khi nào?",explain:"Em dùng Internet khi được người lớn cho phép, vào giờ hợp lí.",options:["Bất cứ lúc nào, kể cả nửa đêm","Khi được bố mẹ, thầy cô cho phép","Trong lúc cô giáo đang giảng bài"],answer:1},{id:"th3-internet-06",type:"mc",q:"Đâu là thông tin bổ ích, phù hợp với em?",emoji:"📄",explain:"Video gấp giấy giúp em học thêm điều hay, phù hợp lứa tuổi.",options:["Phim có cảnh đánh nhau","Trò chơi có lời lẽ thô tục","Video hướng dẫn gấp giấy"],answer:2},{id:"th3-internet-07",type:"fill",q:"Mạng kết nối các máy tính trên khắp thế giới gọi là …",explain:"Đó là mạng Internet.",answer:["Internet","mạng Internet","in-tơ-nét"]},{id:"th3-internet-08",type:"tf",q:"Trên Internet không thể tìm được bài hát thiếu nhi.",emoji:"🎵",explain:"Sai. Trên Internet có rất nhiều bài hát thiếu nhi.",answer:!1},{id:"th3-internet-09",type:"mc",q:"Thiết bị nào sau đây có thể dùng để vào Internet?",emoji:"📱",explain:"Máy tính bảng có thể kết nối Internet.",options:["Máy tính bảng","Thước kẻ","Hộp bút","Quả bóng"],answer:0}]},{questions:[{id:"th3-internet-10",type:"multi",q:"Thông tin nào KHÔNG phù hợp với học sinh lớp 3?",explain:"Bạo lực, tục tĩu là không phù hợp; truyện cổ tích, video loài vật là bổ ích.",options:["Truyện cổ tích","Video về các loài vật","Hình ảnh bạo lực","Lời nói tục tĩu"],answers:[2,3]},{id:"th3-internet-11",type:"match",q:"Nối điều em muốn biết với thông tin cần tìm.",explain:"Em chọn thông tin phù hợp với điều mình cần tìm.",pairs:[["Ngày mai trời có mưa không","Bản tin dự báo thời tiết"],["Cách gấp con hạc giấy","Video hướng dẫn gấp giấy"],["Bài hát cho thiếu nhi","Trang nhạc thiếu nhi"]]},{id:"th3-internet-12",type:"mc",q:"Đang xem video học tập thì hiện quảng cáo mời bấm vào để nhận quà. Em nên làm gì?",emoji:"🎁",explain:"Quảng cáo nhận quà có thể là lừa đảo, em không bấm vào.",options:["Bấm ngay vào để nhận quà","Nhập tên, địa chỉ để nhận quà","Không bấm, báo cho người lớn"],answer:2},{id:"th3-internet-13",type:"tf",q:"Xem video trên mạng quá lâu có thể làm mỏi mắt và ảnh hưởng việc học.",explain:"Đúng. Em cần dùng Internet trong thời gian hợp lí.",answer:!0},{id:"th3-internet-14",type:"mc",q:"Vì sao em nên xem tin tức, video cùng bố mẹ hoặc thầy cô?",explain:"Người lớn giúp em chọn thông tin phù hợp, an toàn.",options:["Để người lớn làm bài tập hộ em","Để được giúp chọn nội dung phù hợp","Vì Internet chỉ dành cho người lớn"],answer:1},{id:"th3-internet-15",type:"tf",q:"Thấy thông tin lạ trên mạng, em nên tin ngay mà không cần hỏi ai.",explain:"Sai. Thông tin trên mạng có thể sai, em nên hỏi người lớn.",answer:!1},{id:"th3-internet-16",type:"mc",q:"Một trang web có nhiều hình ảnh đánh nhau, máu me. Trang này thế nào với em?",explain:"Hình ảnh bạo lực không phù hợp với trẻ em.",options:["Không phù hợp","Rất bổ ích","Nên xem nhiều"],answer:0},{id:"th3-internet-17",type:"multi",q:"Đâu là thông tin giải trí lành mạnh trên Internet?",explain:"Trò chơi bạo lực không lành mạnh với em.",options:["Bài hát thiếu nhi","Truyện tranh về tình bạn","Trò chơi có cảnh bạo lực","Phim hoạt hình cho thiếu nhi"],answers:[0,1,3]},{id:"th3-internet-18",type:"mc",q:"Bố mẹ cho Nam xem video 30 phút. Hết giờ, Nam nên làm gì?",emoji:"⏰",explain:"Nam giữ đúng giờ bố mẹ cho phép.",options:["Xem thêm vài tiếng nữa","Giấu máy để xem lén","Tắt máy, làm việc khác"],answer:2}]},{questions:[{id:"th3-internet-19",type:"mc",q:"Vy tìm hiểu về cá heo cho bài học. Vy nên chọn thông tin nào?",emoji:"🐬",explain:"Video giới thiệu cá heo đúng với điều Vy cần tìm hiểu.",options:["Video giới thiệu cá heo cho thiếu nhi","Trò chơi bắn súng trên mạng","Video quảng cáo bánh kẹo mới"],answer:0},{id:"th3-internet-20",type:"mc",q:"Tùng đọc trên mạng tin “Ngày mai được nghỉ học”, không rõ ai đăng. Tùng nên làm gì?",explain:"Tin không rõ nguồn có thể sai, cần hỏi lại người lớn.",options:["Tin ngay và nghỉ học","Hỏi lại thầy cô, bố mẹ","Chia sẻ ngay cho cả lớp"],answer:1},{id:"th3-internet-21",type:"order",q:"Sắp xếp các bước xem một video học tập trên máy tính.",explain:"Xin phép, chọn video, xem rồi tắt máy đúng giờ.",items:["Xin phép bố mẹ","Cùng bố mẹ chọn video phù hợp","Xem video và ghi nhớ điều bổ ích","Tắt máy khi hết thời gian"]},{id:"th3-internet-22",type:"tf",q:"Khi tìm thông tin trên Internet, em nên chọn thông tin phù hợp với lứa tuổi và việc học.",explain:"Đúng. Chọn thông tin phù hợp giúp em học tốt và an toàn.",answer:!0},{id:"th3-internet-23",type:"mc",q:"Đang xem hoạt hình, Ngọc gặp một đoạn video làm em sợ hãi. Ngọc nên làm gì?",explain:"Kể cho bố mẹ để được giúp đỡ và tránh nội dung xấu.",options:["Cố xem tiếp một mình","Tắt video, kể cho bố mẹ","Giấu không cho ai biết"],answer:1},{id:"th3-internet-24",type:"multi",q:"Việc nào giúp em dùng Internet lành mạnh?",explain:"Thức khuya xem video có hại cho sức khỏe.",options:["Chọn trang dành cho thiếu nhi","Xem cùng người lớn","Thức khuya để xem video","Dùng trong thời gian hợp lí"],answers:[0,1,3]},{id:"th3-internet-25",type:"mc",q:"Minh muốn biết cách trồng cây đậu. Minh nên gõ tìm kiếm cụm từ nào?",emoji:"🌱",explain:"Cụm từ tìm kiếm cần đúng với điều Minh muốn biết.",options:["cách trồng cây đậu","trò chơi vui nhộn","phim hoạt hình mới"],answer:0},{id:"th3-internet-26",type:"tf",q:"Thông tin trên Internet luôn đúng nên em không cần kiểm tra lại.",explain:"Sai. Thông tin trên Internet có thể sai, em nên hỏi lại người lớn.",answer:!1}]}],challenge:{questions:[{id:"th3-internet-27",type:"mc",q:"Hà xem video dạy làm thiệp thì thấy dòng chữ “Bấm vào đây để nhận điện thoại miễn phí”. Hà nên làm gì?",explain:"Lời mời nhận quà miễn phí thường là lừa đảo.",options:["Bấm ngay để nhận quà","Gửi cho các bạn cùng bấm","Không bấm, báo người lớn"],answer:2},{id:"th3-internet-28",type:"multi",q:"Bình được dùng Internet 30 phút. Bình nên chọn những việc nào?",explain:"Bình chọn nội dung bổ ích, phù hợp, tránh bạo lực và người lạ.",options:["Đọc truyện cổ tích trên trang thiếu nhi","Xem phim có cảnh đánh nhau","Trò chuyện với người lạ","Xem video học tiếng Anh cho thiếu nhi"],answers:[0,3]},{id:"th3-internet-29",type:"tf",q:"Thông tin có nhiều người xem thì chắc chắn đúng và phù hợp với em.",explain:"Sai. Nhiều người xem không có nghĩa là đúng hay phù hợp với em.",answer:!1},{id:"th3-internet-10",type:"multi",q:"Thông tin nào KHÔNG phù hợp với học sinh lớp 3?",explain:"Bạo lực, tục tĩu là không phù hợp; truyện cổ tích, video loài vật là bổ ích.",options:["Truyện cổ tích","Video về các loài vật","Hình ảnh bạo lực","Lời nói tục tĩu"],answers:[2,3]},{id:"th3-internet-12",type:"mc",q:"Đang xem video học tập thì hiện quảng cáo mời bấm vào để nhận quà. Em nên làm gì?",emoji:"🎁",explain:"Quảng cáo nhận quà có thể là lừa đảo, em không bấm vào.",options:["Bấm ngay vào để nhận quà","Nhập tên, địa chỉ để nhận quà","Không bấm, báo cho người lớn"],answer:2},{id:"th3-internet-20",type:"mc",q:"Tùng đọc trên mạng tin “Ngày mai được nghỉ học”, không rõ ai đăng. Tùng nên làm gì?",explain:"Tin không rõ nguồn có thể sai, cần hỏi lại người lớn.",options:["Tin ngay và nghỉ học","Hỏi lại thầy cô, bố mẹ","Chia sẻ ngay cho cả lớp"],answer:1},{id:"th3-internet-21",type:"order",q:"Sắp xếp các bước xem một video học tập trên máy tính.",explain:"Xin phép, chọn video, xem rồi tắt máy đúng giờ.",items:["Xin phép bố mẹ","Cùng bố mẹ chọn video phù hợp","Xem video và ghi nhớ điều bổ ích","Tắt máy khi hết thời gian"]}]},summary:["Internet là mạng kết nối rất nhiều máy tính trên khắp thế giới.","Em chọn thông tin bổ ích, phù hợp lứa tuổi; tránh thông tin bạo lực, đáng sợ.","Dùng Internet khi được người lớn cho phép, trong thời gian hợp lí."]},{id:"th3-an-toan-internet",title:"Dùng Internet an toàn",weeks:[14,15],learn:[{title:"Cẩn thận với người lạ",text:"Em không kết bạn, không trò chuyện và không hẹn gặp người lạ quen trên mạng.",example:"🚫 người lạ"},{title:"Giữ kín thông tin",text:"Không cho người lạ biết họ tên đầy đủ, địa chỉ nhà, số điện thoại, tên trường lớp và mật khẩu của em.",example:"🔒 giữ bí mật"},{title:"Không bấm vào thứ lạ",text:"Không bấm vào đường liên kết, quảng cáo lạ; không tự tải trò chơi, ứng dụng khi chưa hỏi bố mẹ.",example:"⚠️ quảng cáo lạ"},{title:"Báo ngay cho người lớn",text:"Khi bị đe dọa, bị trêu chọc hay gặp điều lạ trên mạng, em báo ngay cho bố mẹ, thầy cô.",example:"👨‍👩‍👧 bố mẹ  ·  👩‍🏫 thầy cô"}],practice:[{questions:[{id:"th3-an-toan-internet-01",type:"tf",q:"Em không nên kết bạn, trò chuyện với người lạ trên mạng.",explain:"Đúng. Người lạ trên mạng có thể là kẻ xấu.",answer:!0},{id:"th3-an-toan-internet-02",type:"mc",q:"Một người lạ trên mạng rủ em đi gặp mặt. Em nên làm gì?",explain:"Không bao giờ đi gặp người lạ quen trên mạng, hãy báo bố mẹ.",options:["Đi gặp một mình cho vui","Giữ bí mật với mọi người","Từ chối, báo ngay bố mẹ"],answer:2},{id:"th3-an-toan-internet-03",type:"multi",q:"Thông tin nào em KHÔNG được tự ý cho người lạ trên mạng biết?",explain:"Địa chỉ, số điện thoại, mật khẩu là thông tin cần giữ kín.",options:["Số điện thoại của bố mẹ","Mật khẩu","Màu sắc em thích","Địa chỉ nhà"],answers:[0,1,3]},{id:"th3-an-toan-internet-04",type:"tf",q:"Bấm vào quảng cáo lạ có thể làm máy tính bị nhiễm vi rút.",explain:"Đúng. Quảng cáo lạ có thể chứa phần mềm độc hại.",answer:!0},{id:"th3-an-toan-internet-05",type:"mc",q:"Khi bị ai đó đe dọa, nói lời xấu trên mạng, em nên làm gì?",explain:"Người lớn sẽ giúp em xử lí và bảo vệ em.",options:["Nói lời xấu lại với họ","Im lặng chịu đựng một mình","Báo ngay bố mẹ, thầy cô"],answer:2},{id:"th3-an-toan-internet-06",type:"tf",q:"Em được tự ý tải trò chơi lạ về máy khi chưa hỏi bố mẹ.",explain:"Sai. Em cần hỏi bố mẹ trước khi tải bất cứ thứ gì về máy.",answer:!1},{id:"th3-an-toan-internet-07",type:"fill",q:"Gặp điều lạ trên mạng, em cần báo ngay cho người …",explain:"Em báo ngay cho người lớn như bố mẹ, thầy cô.",answer:["lớn"]},{id:"th3-an-toan-internet-08",type:"mc",q:"Không biết một trang web có an toàn không, em nên hỏi ai?",explain:"Bố mẹ, thầy cô sẽ giúp em biết trang web có an toàn không.",options:["Người lạ trên mạng","Không cần hỏi ai cả","Bố mẹ hoặc thầy cô"],answer:2},{id:"th3-an-toan-internet-09",type:"tf",q:"Em có thể cho bạn mới quen trên mạng biết mật khẩu của mình.",emoji:"🔑",explain:"Sai. Mật khẩu phải giữ bí mật, chỉ em và bố mẹ biết.",answer:!1}]},{questions:[{id:"th3-an-toan-internet-10",type:"mc",q:"Tin nhắn lạ báo: “Bạn trúng thưởng, hãy gửi địa chỉ nhà để nhận quà”. Đây có thể là gì?",emoji:"📩",explain:"Tin nhắn trúng thưởng bất ngờ đòi thông tin thường là lừa đảo.",options:["Món quà thật","Một trò lừa đảo","Thư của cô giáo"],answer:1},{id:"th3-an-toan-internet-11",type:"match",q:"Nối tình huống với cách xử lí.",explain:"Mỗi tình huống cần cách xử lí an toàn.",pairs:[["Người lạ xin địa chỉ nhà","Không trả lời, báo bố mẹ"],["Thấy quảng cáo lạ nhấp nháy","Không bấm vào"],["Bị bạn nói lời xấu trên mạng","Kể với thầy cô, bố mẹ"]]},{id:"th3-an-toan-internet-12",type:"multi",q:"Việc làm nào an toàn khi dùng Internet?",explain:"Kết bạn với người lạ là không an toàn.",options:["Kết bạn với mọi người lạ","Hỏi bố mẹ trước khi tải ứng dụng","Không bấm vào đường liên kết lạ","Giữ bí mật mật khẩu"],answers:[1,2,3]},{id:"th3-an-toan-internet-13",type:"tf",q:"Người lạ trên mạng có thể giả làm bạn cùng tuổi để lừa trẻ em.",explain:"Đúng. Vì vậy em không tin và không kết bạn với người lạ.",answer:!0},{id:"th3-an-toan-internet-14",type:"mc",q:"Vì sao không nên cho người lạ biết tên trường, lớp của em?",explain:"Biết tên trường, lớp, kẻ xấu có thể tìm đến em.",options:["Vì tên trường em không hay","Vì máy tính sẽ bị hỏng ngay","Vì kẻ xấu có thể tìm đến em"],answer:2},{id:"th3-an-toan-internet-15",type:"mc",q:"Lan nhận được ảnh của một bạn bị chỉnh sửa để trêu chọc. Lan nên làm gì?",explain:"Không lan truyền và báo người lớn để bảo vệ bạn.",options:["Không gửi tiếp, báo thầy cô","Gửi cho cả lớp cùng xem","Viết bình luận chê bạn"],answer:0},{id:"th3-an-toan-internet-16",type:"tf",q:"Nếu người lạ hứa tặng quà, em có thể gửi ảnh của mình cho họ.",explain:"Sai. Không gửi ảnh cho người lạ dù được hứa tặng quà.",answer:!1},{id:"th3-an-toan-internet-17",type:"mc",q:"Dùng máy tính chung ở phòng máy xong, em nên làm gì với tài khoản của mình?",explain:"Đăng xuất để người khác không dùng được tài khoản của em.",options:["Để nguyên cho bạn khác dùng","Dán mật khẩu lên màn hình","Đăng xuất khỏi tài khoản"],answer:2},{id:"th3-an-toan-internet-18",type:"multi",q:"Dấu hiệu nào cho thấy một tin nhắn có thể là lừa đảo?",explain:"Trúng thưởng bất ngờ, đòi mật khẩu, giục làm ngay là dấu hiệu lừa đảo.",options:["Đòi gửi mật khẩu","Giục làm ngay kẻo mất quà","Mẹ nhắn hỏi em ăn cơm chưa","Báo trúng thưởng bất ngờ"],answers:[0,1,3]}]},{questions:[{id:"th3-an-toan-internet-19",type:"mc",q:"Đang chơi trò chơi trên mạng, một người lạ hỏi: “Nhà em ở đâu?”. Khoa nên làm gì?",explain:"Không cho người lạ biết địa chỉ nhà, hãy báo bố mẹ.",options:["Nói rõ địa chỉ nhà mình","Không trả lời, báo bố mẹ","Hẹn người đó đến nhà chơi"],answer:1},{id:"th3-an-toan-internet-20",type:"order",q:"Sắp xếp cách xử lí khi nhận tin nhắn lạ đe dọa em.",explain:"Không trả lời, báo người lớn, rồi cùng người lớn chặn người gửi.",items:["Dừng lại, không trả lời","Báo cho bố mẹ hoặc thầy cô","Cùng người lớn chặn người gửi"]},{id:"th3-an-toan-internet-21",type:"mc",q:"Dũng muốn đặt mật khẩu. Mật khẩu nào khó đoán hơn?",emoji:"🔑",explain:"Mật khẩu có chữ và số lẫn lộn khó đoán hơn.",options:["Dãy chữ và số lẫn lộn","Chính tên của Dũng","Dãy số 123456"],answer:0},{id:"th3-an-toan-internet-22",type:"tf",q:"Thấy thông báo “Máy của bạn bị hỏng, bấm vào đây để sửa”, em nên bấm ngay.",explain:"Sai. Đây có thể là trò lừa, em hỏi người lớn trước.",answer:!1},{id:"th3-an-toan-internet-23",type:"mc",q:"Thảo thấy một bạn trong lớp bị trêu chọc trên nhóm tin nhắn. Thảo nên làm gì?",explain:"Không hùa theo và báo thầy cô để giúp bạn.",options:["Hùa theo trêu bạn cho vui","Chụp lại gửi đi khắp nơi","Không hùa theo, báo thầy cô"],answer:2},{id:"th3-an-toan-internet-24",type:"multi",q:"Phúc muốn tải một trò chơi mới. Phúc nên làm gì?",explain:"Tự tải từ trang lạ có thể làm hỏng máy hoặc gặp nội dung xấu.",options:["Hỏi ý kiến bố mẹ trước","Cùng bố mẹ chọn trò chơi hợp lứa tuổi","Tự tải từ một trang lạ"],answers:[0,1]},{id:"th3-an-toan-internet-25",type:"mc",q:"Người lạ nhắn: “Đừng kể với bố mẹ chuyện chúng mình nói nhé”. Em nên làm gì?",explain:"Người lạ bảo giữ bí mật là dấu hiệu nguy hiểm, phải kể bố mẹ.",options:["Giữ bí mật như lời dặn","Kể ngay cho bố mẹ","Tiếp tục trò chuyện"],answer:1},{id:"th3-an-toan-internet-26",type:"tf",q:"Người lớn có thể giúp em chặn hoặc báo cáo người có lời lẽ xấu trên mạng.",explain:"Đúng. Em hãy nhờ bố mẹ, thầy cô giúp đỡ.",answer:!0}]}],challenge:{questions:[{id:"th3-an-toan-internet-27",type:"match",q:"Nối tình huống với việc nên làm.",explain:"Đây là những cách giữ an toàn khi dùng Internet.",pairs:[["Người lạ xin ảnh của em","Từ chối, báo bố mẹ"],["Đường liên kết lạ hứa tặng quà","Không bấm vào"],["Muốn cài ứng dụng mới","Hỏi bố mẹ trước"],["Dùng xong máy tính chung","Đăng xuất tài khoản"]]},{id:"th3-an-toan-internet-28",type:"multi",q:"Thông tin nào cần giữ kín với người lạ?",explain:"Họ tên, địa chỉ, mật khẩu là thông tin cá nhân cần giữ kín.",options:["Họ tên đầy đủ","Địa chỉ nhà","Mật khẩu","Tên một loài hoa"],answers:[0,1,2]},{id:"th3-an-toan-internet-29",type:"mc",q:"Người lạ khen Vy dễ thương và hứa tặng quà nếu Vy gửi số điện thoại. Vy nên làm gì?",explain:"Không gửi thông tin cho người lạ, dù được hứa tặng quà.",options:["Gửi ngay để nhận quà","Gửi số của bạn thân","Không gửi, báo bố mẹ"],answer:2},{id:"th3-an-toan-internet-10",type:"mc",q:"Tin nhắn lạ báo: “Bạn trúng thưởng, hãy gửi địa chỉ nhà để nhận quà”. Đây có thể là gì?",emoji:"📩",explain:"Tin nhắn trúng thưởng bất ngờ đòi thông tin thường là lừa đảo.",options:["Món quà thật","Một trò lừa đảo","Thư của cô giáo"],answer:1},{id:"th3-an-toan-internet-11",type:"match",q:"Nối tình huống với cách xử lí.",explain:"Mỗi tình huống cần cách xử lí an toàn.",pairs:[["Người lạ xin địa chỉ nhà","Không trả lời, báo bố mẹ"],["Thấy quảng cáo lạ nhấp nháy","Không bấm vào"],["Bị bạn nói lời xấu trên mạng","Kể với thầy cô, bố mẹ"]]},{id:"th3-an-toan-internet-19",type:"mc",q:"Đang chơi trò chơi trên mạng, một người lạ hỏi: “Nhà em ở đâu?”. Khoa nên làm gì?",explain:"Không cho người lạ biết địa chỉ nhà, hãy báo bố mẹ.",options:["Nói rõ địa chỉ nhà mình","Không trả lời, báo bố mẹ","Hẹn người đó đến nhà chơi"],answer:1},{id:"th3-an-toan-internet-23",type:"mc",q:"Thảo thấy một bạn trong lớp bị trêu chọc trên nhóm tin nhắn. Thảo nên làm gì?",explain:"Không hùa theo và báo thầy cô để giúp bạn.",options:["Hùa theo trêu bạn cho vui","Chụp lại gửi đi khắp nơi","Không hùa theo, báo thầy cô"],answer:2}]},summary:["Không kết bạn, trò chuyện hay hẹn gặp người lạ trên mạng.","Giữ kín địa chỉ, số điện thoại, mật khẩu; không bấm vào quảng cáo lạ.","Gặp điều lạ hay bị đe dọa trên mạng, báo ngay cho bố mẹ, thầy cô."]}]},{id:"luu-tru-tim-kiem",title:"Tổ chức lưu trữ, tìm kiếm và trao đổi thông tin",lessons:[{id:"th3-sap-xep",title:"Sắp xếp để dễ tìm",weeks:[16,17],learn:[{title:"Sắp xếp giúp tìm nhanh",text:"Đồ vật được xếp gọn gàng, có thứ tự thì em tìm nhanh hơn.",example:"📚 sách  ·  👕 quần áo  ·  🖍️ bút màu"},{title:"Nhiều cách sắp xếp",text:"Có thể sắp xếp theo loại, theo màu, theo kích thước, theo thứ tự chữ cái hoặc theo thứ tự số.",example:"🔤 A B C  ·  🔢 1 2 3"},{title:"Ví dụ quanh em",text:"Thư viện xếp sách theo loại. Danh sách lớp xếp theo chữ cái của tên. Hộp đựng đồ được dán nhãn.",example:"🏷️ dán nhãn"}],practice:[{questions:[{id:"th3-sap-xep-01",type:"tf",q:"Đồ dùng được sắp xếp gọn gàng thì em tìm nhanh hơn.",explain:"Đúng. Sắp xếp có thứ tự giúp tìm đồ nhanh.",answer:!0},{id:"th3-sap-xep-02",type:"mc",q:"Thư viện thường xếp sách như thế nào để dễ tìm?",emoji:"📚",explain:"Xếp sách theo loại giúp tìm sách nhanh.",options:["Theo từng loại sách","Để lộn xộn dưới sàn","Chồng hết vào một chỗ"],answer:0},{id:"th3-sap-xep-03",type:"multi",q:"Cách nào giúp sắp xếp đồ vật để dễ tìm?",explain:"Vứt lung tung làm em khó tìm đồ.",options:["Xếp theo màu","Xếp theo kích thước","Vứt lung tung","Xếp theo loại"],answers:[0,1,3]},{id:"th3-sap-xep-04",type:"mc",q:"Bút màu được xếp theo từng màu giúp em điều gì?",emoji:"🖍️",explain:"Xếp theo màu giúp em lấy đúng màu nhanh hơn.",options:["Bút màu tự vẽ đẹp hơn trước","Bút màu không bao giờ bị hết","Lấy đúng màu cần dùng nhanh hơn"],answer:2},{id:"th3-sap-xep-05",type:"order",q:"Sắp xếp các số từ bé đến lớn.",explain:"3 bé nhất, rồi đến 7, 12 và 20.",items:["3","7","12","20"]},{id:"th3-sap-xep-06",type:"order",q:"Sắp xếp các tên theo thứ tự chữ cái đầu.",explain:"Theo bảng chữ cái: A, B, C, D.",items:["An","Bình","Chi","Dũng"]},{id:"th3-sap-xep-07",type:"tf",q:"Tủ quần áo xếp áo một ngăn, quần một ngăn thì khó tìm đồ hơn.",emoji:"👕",explain:"Sai. Xếp riêng từng loại giúp em tìm đồ nhanh hơn.",answer:!1},{id:"th3-sap-xep-08",type:"fill",q:"Sắp xếp đồ vật gọn gàng, có thứ tự giúp em dễ … đồ hơn.",explain:"Sắp xếp có thứ tự giúp em dễ tìm đồ hơn.",answer:["tìm"]},{id:"th3-sap-xep-09",type:"mc",q:"Hộp đồ chơi lộn xộn đủ thứ. Tìm một món đồ trong đó sẽ thế nào?",emoji:"🧸",explain:"Đồ để lộn xộn thì tìm lâu.",options:["Tìm được rất nhanh","Mất nhiều thời gian","Đồ tự nhảy ra ngoài"],answer:1}]},{questions:[{id:"th3-sap-xep-10",type:"match",q:"Nối đồ vật với cách sắp xếp phù hợp.",explain:"Mỗi loại đồ vật có cách sắp xếp phù hợp.",pairs:[["Sách trong thư viện","Theo loại sách"],["Danh sách học sinh","Theo chữ cái của tên"],["Bút màu","Theo màu"],["Giày dép","Theo đôi"]]},{id:"th3-sap-xep-11",type:"mc",q:"Trong từ điển, các từ được sắp xếp theo thứ tự nào?",emoji:"📖",explain:"Từ điển xếp các từ theo bảng chữ cái để dễ tra.",options:["Theo bảng chữ cái","Theo màu sắc","Theo độ dài từ"],answer:0},{id:"th3-sap-xep-12",type:"tf",q:"Siêu thị xếp hàng hóa cùng loại vào một khu để người mua dễ tìm.",emoji:"🛒",explain:"Đúng. Hàng cùng loại xếp một khu giúp tìm nhanh.",answer:!0},{id:"th3-sap-xep-13",type:"mc",q:"Lan xếp sách vở theo thời khóa biểu mỗi ngày. Việc đó giúp Lan điều gì?",explain:"Xếp theo thời khóa biểu giúp Lan mang đủ sách vở.",options:["Cặp sách nặng hơn mọi ngày","Sách vở bị nhàu nát hết","Không quên sách vở cần dùng"],answer:2},{id:"th3-sap-xep-14",type:"multi",q:"Cách nào giúp góc học tập gọn gàng, dễ tìm đồ?",explain:"Để đồ ăn lẫn với sách vừa bẩn vừa khó tìm.",options:["Cất bút vào hộp bút","Dán nhãn lên các ngăn","Để đồ ăn lẫn với sách","Để sách một chỗ, vở một chỗ"],answers:[0,1,3]},{id:"th3-sap-xep-15",type:"order",q:"Sắp xếp các bạn theo chiều cao từ thấp đến cao: Nam cao 125 xăng-ti-mét, An cao 130 xăng-ti-mét, Chi cao 120 xăng-ti-mét.",explain:"Chi thấp nhất, rồi đến Nam, cao nhất là An.",items:["Chi","Nam","An"]},{id:"th3-sap-xep-16",type:"mc",q:"Vì sao danh sách lớp thường xếp theo thứ tự chữ cái của tên?",explain:"Xếp theo chữ cái giúp tìm tên nhanh.",options:["Để ai cũng được ngồi bàn đầu","Để danh sách dài hơn trước","Để tìm tên một bạn nhanh hơn"],answer:2},{id:"th3-sap-xep-17",type:"tf",q:"Sắp xếp đồ vật chỉ có một cách duy nhất.",explain:"Sai. Có thể sắp xếp theo loại, màu, kích thước, chữ cái…",answer:!1},{id:"th3-sap-xep-18",type:"mc",q:"Mẹ dán nhãn “Gia vị”, “Đồ khô” lên các hộp trong bếp. Việc dán nhãn giúp gì?",emoji:"🏷️",explain:"Nhãn cho biết trong hộp có gì nên lấy đồ nhanh hơn.",options:["Làm cho hộp nặng hơn trước","Biết hộp đựng gì để lấy nhanh","Làm cho hộp đổi sang màu khác"],answer:1}]},{questions:[{id:"th3-sap-xep-19",type:"mc",q:"Phúc có nhiều truyện tranh và sách giáo khoa để lẫn lộn. Cách xếp nào giúp Phúc dễ tìm nhất?",explain:"Xếp mỗi loại một ngăn giúp Phúc tìm nhanh.",options:["Chất tất cả thành một chồng","Cho hết vào một bao tải lớn","Mỗi loại sách một ngăn riêng"],answer:2},{id:"th3-sap-xep-20",type:"order",q:"Sắp xếp các từ theo thứ tự chữ cái đầu.",explain:"Thứ tự chữ cái đầu: c, g, m, v.",items:["cá","gà","mèo","voi"]},{id:"th3-sap-xep-21",type:"multi",q:"Khi xếp lại góc học tập, Hà làm việc nào đúng?",explain:"Phân loại, xếp riêng và dán nhãn giúp dễ tìm.",options:["Xếp mỗi loại vào một chỗ","Dán nhãn để dễ nhận ra","Nhét đồ dùng xuống gầm giường","Phân loại sách, vở, đồ dùng"],answers:[0,1,3]},{id:"th3-sap-xep-22",type:"mc",q:"Ở thư viện, Khoa muốn mượn truyện cổ tích. Khoa nên tìm ở đâu?",explain:"Sách được xếp theo loại, Khoa tìm ở giá truyện cổ tích.",options:["Một giá sách bất kì","Trong phòng giáo viên","Giá ghi “Truyện cổ tích”"],answer:2},{id:"th3-sap-xep-23",type:"tf",q:"Xếp đồ chơi vào hộp có dán nhãn thì lần sau em sẽ tìm lâu hơn.",explain:"Sai. Hộp có nhãn giúp em tìm đồ chơi nhanh hơn.",answer:!1},{id:"th3-sap-xep-24",type:"mc",q:"Ngọc xếp các số 15, 8, 23, 4 theo thứ tự từ bé đến lớn. Số nào đứng đầu?",explain:"Số 4 bé nhất nên đứng đầu.",options:["4","8","15","23"],answer:0},{id:"th3-sap-xep-25",type:"order",q:"Sắp xếp các bước dọn tủ sách.",explain:"Lấy sách ra, phân loại, xếp từng ngăn rồi dán nhãn.",items:["Lấy hết sách ra","Chia sách thành từng loại","Xếp từng loại vào một ngăn","Dán nhãn tên cho mỗi ngăn"]},{id:"th3-sap-xep-26",type:"mc",q:"Trong danh sách xếp theo chữ cái, tên nào đứng trước tên “Lan”?",explain:"Chữ H đứng trước chữ L trong bảng chữ cái.",options:["Hà","Minh","Tùng"],answer:0}]}],challenge:{questions:[{id:"th3-sap-xep-27",type:"mc",q:"Danh sách lớp xếp theo chữ cái của tên. Muốn tìm bạn tên “Vy”, em nên nhìn ở phần nào?",explain:"Chữ V gần cuối bảng chữ cái nên tên Vy ở gần cuối danh sách.",options:["Đầu danh sách","Gần cuối danh sách","Chính giữa danh sách"],answer:1},{id:"th3-sap-xep-28",type:"multi",q:"Việc nào là sắp xếp để dễ tìm?",explain:"Để giấy tờ khắp nhà làm khó tìm.",options:["Xếp sách theo môn học","Xếp áo theo mùa","Ghi tên rõ ràng lên hộp đựng","Để giấy tờ khắp nhà"],answers:[0,1,2]},{id:"th3-sap-xep-29",type:"order",q:"Sắp xếp các tên theo thứ tự chữ cái đầu.",explain:"Thứ tự chữ cái đầu: B, H, N, T.",items:["Bình","Hà","Ngọc","Thảo"]},{id:"th3-sap-xep-10",type:"match",q:"Nối đồ vật với cách sắp xếp phù hợp.",explain:"Mỗi loại đồ vật có cách sắp xếp phù hợp.",pairs:[["Sách trong thư viện","Theo loại sách"],["Danh sách học sinh","Theo chữ cái của tên"],["Bút màu","Theo màu"],["Giày dép","Theo đôi"]]},{id:"th3-sap-xep-14",type:"multi",q:"Cách nào giúp góc học tập gọn gàng, dễ tìm đồ?",explain:"Để đồ ăn lẫn với sách vừa bẩn vừa khó tìm.",options:["Cất bút vào hộp bút","Dán nhãn lên các ngăn","Để đồ ăn lẫn với sách","Để sách một chỗ, vở một chỗ"],answers:[0,1,3]},{id:"th3-sap-xep-19",type:"mc",q:"Phúc có nhiều truyện tranh và sách giáo khoa để lẫn lộn. Cách xếp nào giúp Phúc dễ tìm nhất?",explain:"Xếp mỗi loại một ngăn giúp Phúc tìm nhanh.",options:["Chất tất cả thành một chồng","Cho hết vào một bao tải lớn","Mỗi loại sách một ngăn riêng"],answer:2},{id:"th3-sap-xep-25",type:"order",q:"Sắp xếp các bước dọn tủ sách.",explain:"Lấy sách ra, phân loại, xếp từng ngăn rồi dán nhãn.",items:["Lấy hết sách ra","Chia sách thành từng loại","Xếp từng loại vào một ngăn","Dán nhãn tên cho mỗi ngăn"]}]},summary:["Sắp xếp gọn gàng, có thứ tự giúp tìm đồ nhanh.","Có thể sắp xếp theo loại, màu, kích thước, chữ cái hoặc số.","Dán nhãn, đặt tên rõ ràng giúp nhận ra đồ vật dễ dàng."]},{id:"th3-thu-muc",title:"Thư mục và tệp trong máy tính",weeks:[18,20],learn:[{title:"Tệp",text:"Mỗi bức tranh, bài hát, bài viết được lưu trong máy tính là một tệp.",example:"🖼️ tranh  ·  🎵 bài hát  ·  📝 bài viết"},{title:"Thư mục",text:"Thư mục giống như chiếc hộp hay ngăn tủ, dùng để chứa các tệp và các thư mục khác gọi là thư mục con.",example:"📁 thư mục  ·  📂 thư mục con"},{title:"Cây thư mục",text:"Thư mục lớn chứa thư mục con, thư mục con lại chứa tệp, xếp thành nhiều tầng như cành cây.",example:"📁 Học tập  ➜  📁 Toán  ➜  📄 Bài tập"},{title:"Đặt tên rõ ràng",text:"Đặt tên thư mục, tệp rõ nghĩa như “Tranh vẽ”, “Âm nhạc” để dễ tìm. Nháy đúp chuột để mở thư mục.",example:"📁 Tranh vẽ  ·  📁 Âm nhạc"}],practice:[{questions:[{id:"th3-thu-muc-01",type:"mc",q:"Biểu tượng trong tranh thường dùng để chỉ gì trong máy tính?",emoji:"📁",explain:"Biểu tượng hình chiếc cặp hồ sơ màu vàng thường là thư mục.",options:["Con chuột","Thư mục","Bàn phím"],answer:1},{id:"th3-thu-muc-02",type:"tf",q:"Thư mục có thể chứa các tệp.",explain:"Đúng. Thư mục dùng để chứa tệp.",answer:!0},{id:"th3-thu-muc-03",type:"tf",q:"Thư mục không thể chứa thư mục khác bên trong.",explain:"Sai. Thư mục có thể chứa thư mục con.",answer:!1},{id:"th3-thu-muc-04",type:"mc",q:"Bức tranh em vẽ và lưu trong máy tính được gọi là gì?",emoji:"🖼️",explain:"Mỗi bức tranh lưu trong máy là một tệp.",options:["Một bàn phím","Một tệp","Một con chuột"],answer:1},{id:"th3-thu-muc-05",type:"fill",q:"Thư mục nằm bên trong một thư mục khác gọi là thư mục …",explain:"Đó là thư mục con.",answer:["con"]},{id:"th3-thu-muc-06",type:"mc",q:"Thư mục trong máy tính giống với đồ vật nào?",explain:"Thư mục chứa tệp giống như ngăn tủ chứa đồ.",options:["Tủ có nhiều ngăn đựng đồ","Cái bảng đen trong lớp","Cái quạt trần đang quay"],answer:0},{id:"th3-thu-muc-07",type:"tf",q:"Tên thư mục nên đặt rõ ràng, dễ hiểu.",explain:"Đúng. Tên rõ ràng giúp biết bên trong có gì.",answer:!0},{id:"th3-thu-muc-08",type:"mc",q:"Muốn mở một thư mục, em thường làm thao tác nào?",emoji:"🖱️",explain:"Nháy đúp chuột vào thư mục để mở.",options:["Nhấn phím cách hai lần","Kéo dây chuột thật mạnh","Nháy đúp chuột vào thư mục"],answer:2},{id:"th3-thu-muc-09",type:"multi",q:"Những gì có thể là một tệp trong máy tính?",explain:"Chiếc ghế là đồ vật thật, không phải tệp.",options:["Một bức ảnh","Một bài hát","Một bài văn em gõ","Một chiếc ghế"],answers:[0,1,2]}]},{questions:[{id:"th3-thu-muc-10",type:"mc",q:"Tên thư mục nào cho em biết ngay bên trong chứa tranh vẽ?",explain:"Tên “Tranh vẽ” cho biết rõ nội dung bên trong.",options:["Thư mục mới","Tranh vẽ","abc"],answer:1},{id:"th3-thu-muc-11",type:"match",q:"Nối tệp với thư mục phù hợp.",explain:"Mỗi tệp được cất vào thư mục đúng loại.",pairs:[["Bài hát thiếu nhi","Âm nhạc"],["Bức tranh con mèo","Tranh vẽ"],["Ảnh chụp cả lớp","Ảnh lớp em"]]},{id:"th3-thu-muc-12",type:"tf",q:"Để tất cả các tệp lẫn lộn một chỗ giúp tìm kiếm nhanh hơn.",explain:"Sai. Chia tệp vào các thư mục theo loại mới tìm nhanh.",answer:!1},{id:"th3-thu-muc-13",type:"mc",q:"Cây thư mục là gì?",emoji:"🌳",explain:"Thư mục lớn chứa thư mục con, xếp thành nhiều tầng như cành cây.",options:["Một cái cây trồng ở trong phòng máy","Cách xếp thư mục nhiều tầng như cành cây","Một trò chơi trồng cây trên máy tính"],answer:1},{id:"th3-thu-muc-14",type:"mc",q:"Thư mục “Học tập” có thư mục “Toán” bên trong. Thư mục “Toán” là gì của thư mục “Học tập”?",explain:"Thư mục nằm bên trong thư mục khác là thư mục con.",options:["Một bức ảnh","Một bài hát","Thư mục con"],answer:2},{id:"th3-thu-muc-15",type:"multi",q:"Việc nào giúp tìm tệp nhanh hơn?",explain:"Đặt tên giống nhau, vô nghĩa làm khó tìm.",options:["Đặt tên mọi tệp là “aaa”","Đặt tên tệp rõ nghĩa","Chia tệp vào thư mục theo loại","Tạo thư mục con cho từng môn"],answers:[1,2,3]},{id:"th3-thu-muc-16",type:"tf",q:"Thư mục giống như ngăn tủ, còn tệp giống như quyển vở cất trong ngăn tủ.",explain:"Đúng. Thư mục chứa tệp như ngăn tủ chứa vở.",answer:!0},{id:"th3-thu-muc-17",type:"mc",q:"Thư mục “Ảnh gia đình” nên chứa tệp nào?",emoji:"👨‍👩‍👧",explain:"Ảnh cả nhà đúng với tên thư mục “Ảnh gia đình”.",options:["Bài tập môn Toán","Bài hát tiếng Anh","Ảnh cả nhà đi chơi"],answer:2},{id:"th3-thu-muc-18",type:"order",q:"Sắp xếp theo thứ tự từ ngoài vào trong để đi đến bài tập.",explain:"Thư mục lớn ở ngoài, thư mục con ở trong, tệp nằm trong thư mục con.",items:["Thư mục “Học tập”","Thư mục “Toán”","Tệp “Bài tập số 1”"]}]},{questions:[{id:"th3-thu-muc-19",type:"mc",q:"Minh lưu tranh vẽ con mèo vào thư mục “Bài hát”. Như vậy có hợp lí không?",explain:"Tranh vẽ nên lưu vào thư mục “Tranh vẽ” cho dễ tìm.",options:["Hợp lí, để đâu cũng được","Chưa, nên lưu vào “Tranh vẽ”","Chưa, nên xóa tranh đi"],answer:1},{id:"th3-thu-muc-20",type:"mc",q:"Vy muốn tìm bài vẽ con voi. Vy nên mở thư mục nào?",emoji:"🐘",explain:"Bài vẽ được lưu trong thư mục “Tranh vẽ”.",options:["Âm nhạc","Ảnh gia đình","Tranh vẽ"],answer:2},{id:"th3-thu-muc-21",type:"order",q:"Tệp “Bài tập số 1” nằm trong thư mục “Toán”, thư mục “Toán” nằm trong thư mục “Học tập”. Sắp xếp các bước mở tệp.",explain:"Mở lần lượt từ thư mục ngoài vào thư mục trong rồi mới đến tệp.",items:["Nháy đúp mở thư mục “Học tập”","Nháy đúp mở thư mục “Toán”","Nháy đúp mở tệp “Bài tập số 1”"]},{id:"th3-thu-muc-22",type:"multi",q:"Hà muốn sắp xếp các tệp của mình. Cách nào hợp lí?",explain:"Để tệp lộn xộn làm khó tìm.",options:["Để mọi tệp lộn xộn ngoài màn hình","Tạo thư mục “Tranh vẽ” chứa tranh","Tạo thư mục “Âm nhạc” chứa bài hát","Đặt tên tệp rõ ràng"],answers:[1,2,3]},{id:"th3-thu-muc-23",type:"tf",q:"Hai tệp khác nhau trong cùng một thư mục nên có tên khác nhau để dễ phân biệt.",explain:"Đúng. Tên khác nhau giúp nhận ra từng tệp.",answer:!0},{id:"th3-thu-muc-24",type:"mc",q:"Thư mục “Lớp 3” có các thư mục con “Toán”, “Tiếng Việt”, “Tin học”. Bài trình chiếu về máy tính nên lưu ở đâu?",explain:"Bài về máy tính thuộc môn Tin học.",options:["Thư mục “Tin học”","Thư mục “Toán”","Thư mục “Tiếng Việt”"],answer:0},{id:"th3-thu-muc-25",type:"mc",q:"Thảo đặt tên tệp là “Tranh con mèo”. Tên này có ưu điểm gì?",explain:"Tên rõ nghĩa giúp biết ngay tệp chứa gì.",options:["Tên dài nên trông đẹp hơn","Nhìn tên là biết nội dung","Không có ưu điểm gì cả"],answer:1},{id:"th3-thu-muc-26",type:"tf",q:"Em được tự ý xóa, sửa tệp của bạn khác trong máy tính dùng chung.",explain:"Sai. Không được tự ý xóa, sửa tệp của người khác.",answer:!1}]}],challenge:{questions:[{id:"th3-thu-muc-27",type:"match",q:"Nối tệp với thư mục phù hợp.",explain:"Mỗi tệp được cất vào thư mục đúng nội dung.",pairs:[["Ảnh đi chơi công viên","Ảnh gia đình"],["Bài tập cộng trừ","Toán"],["Bài hát thiếu nhi","Âm nhạc"],["Tranh vẽ ngôi trường","Tranh vẽ"]]},{id:"th3-thu-muc-28",type:"mc",q:"Thư mục “Học tập” chứa thư mục “Toán”, thư mục “Toán” chứa tệp “Bài tập số 1”. Thư mục nào nằm ngoài cùng?",explain:"Thư mục “Học tập” chứa tất cả nên nằm ngoài cùng.",options:["Toán","Học tập","Bài tập số 1"],answer:1},{id:"th3-thu-muc-29",type:"multi",q:"Câu nào đúng về thư mục và tệp?",explain:"Tệp không chứa được thư mục; thư mục mới chứa tệp.",options:["Tệp chứa được thư mục","Đặt tên rõ ràng giúp tìm nhanh","Thư mục có thể chứa tệp","Thư mục có thể chứa thư mục con"],answers:[1,2,3]},{id:"th3-thu-muc-11",type:"match",q:"Nối tệp với thư mục phù hợp.",explain:"Mỗi tệp được cất vào thư mục đúng loại.",pairs:[["Bài hát thiếu nhi","Âm nhạc"],["Bức tranh con mèo","Tranh vẽ"],["Ảnh chụp cả lớp","Ảnh lớp em"]]},{id:"th3-thu-muc-14",type:"mc",q:"Thư mục “Học tập” có thư mục “Toán” bên trong. Thư mục “Toán” là gì của thư mục “Học tập”?",explain:"Thư mục nằm bên trong thư mục khác là thư mục con.",options:["Một bức ảnh","Một bài hát","Thư mục con"],answer:2},{id:"th3-thu-muc-19",type:"mc",q:"Minh lưu tranh vẽ con mèo vào thư mục “Bài hát”. Như vậy có hợp lí không?",explain:"Tranh vẽ nên lưu vào thư mục “Tranh vẽ” cho dễ tìm.",options:["Hợp lí, để đâu cũng được","Chưa, nên lưu vào “Tranh vẽ”","Chưa, nên xóa tranh đi"],answer:1},{id:"th3-thu-muc-21",type:"order",q:"Tệp “Bài tập số 1” nằm trong thư mục “Toán”, thư mục “Toán” nằm trong thư mục “Học tập”. Sắp xếp các bước mở tệp.",explain:"Mở lần lượt từ thư mục ngoài vào thư mục trong rồi mới đến tệp.",items:["Nháy đúp mở thư mục “Học tập”","Nháy đúp mở thư mục “Toán”","Nháy đúp mở tệp “Bài tập số 1”"]}]},summary:["Mỗi bức tranh, bài hát, bài viết lưu trong máy tính là một tệp.","Thư mục chứa tệp và thư mục con, tạo thành cây thư mục.","Đặt tên rõ ràng, cất tệp đúng thư mục giúp tìm nhanh."]}]},{id:"dao-duc-moi-truong-so",title:"Đạo đức, pháp luật và văn hóa trong môi trường số",lessons:[{id:"th3-bao-ve-thong-tin",title:"Bảo vệ thông tin của em và gia đình",weeks:[21,22],learn:[{title:"Thông tin cá nhân",text:"Họ tên, ngày sinh, địa chỉ nhà, số điện thoại, tên trường lớp, ảnh của em là thông tin cá nhân.",example:"🪪 họ tên  ·  🏠 địa chỉ  ·  📞 số điện thoại"},{title:"Thông tin gia đình",text:"Địa chỉ nhà, số điện thoại, nơi làm việc của bố mẹ, giờ cả nhà đi vắng là thông tin của gia đình.",example:"👨‍👩‍👧 gia đình"},{title:"Giữ kín với người lạ",text:"Không cho người lạ biết; không đăng lên mạng khi chưa hỏi bố mẹ. Mật khẩu chỉ em và bố mẹ biết.",example:"🔒 mật khẩu"},{title:"Lưu trữ cẩn thận",text:"Thông tin có thể lưu trong sổ tay, máy tính, điện thoại. Em cất giữ cẩn thận, không để người lạ xem.",example:"📒 sổ tay  ·  💻 máy tính  ·  📱 điện thoại"}],practice:[{questions:[{id:"th3-bao-ve-thong-tin-01",type:"multi",q:"Đâu là thông tin cá nhân của em?",explain:"Tên một bài hát không phải thông tin về em.",options:["Địa chỉ nhà","Tên một bài hát thiếu nhi","Họ và tên","Ngày sinh"],answers:[0,2,3]},{id:"th3-bao-ve-thong-tin-02",type:"tf",q:"Số điện thoại của bố mẹ là thông tin cần giữ kín với người lạ.",emoji:"📞",explain:"Đúng. Kẻ xấu có thể lợi dụng số điện thoại để lừa gia đình em.",answer:!0},{id:"th3-bao-ve-thong-tin-03",type:"mc",q:"Ai được biết mật khẩu tài khoản học tập của em?",emoji:"🔑",explain:"Mật khẩu chỉ em và bố mẹ biết.",options:["Bất kì ai hỏi","Bạn mới quen","Em và bố mẹ"],answer:2},{id:"th3-bao-ve-thong-tin-04",type:"tf",q:"Em có thể tự đăng ảnh nhà mình kèm địa chỉ lên mạng mà không cần hỏi bố mẹ.",explain:"Sai. Em phải hỏi bố mẹ, và không đăng địa chỉ nhà lên mạng.",answer:!1},{id:"th3-bao-ve-thong-tin-05",type:"multi",q:"Thông tin có thể được lưu trữ ở đâu?",explain:"Sổ tay, máy tính, điện thoại đều lưu được thông tin.",options:["Điện thoại thông minh","Quả bóng bay","Sổ tay","Máy tính"],answers:[0,2,3]},{id:"th3-bao-ve-thong-tin-06",type:"fill",q:"Họ tên, địa chỉ, số điện thoại của em là thông tin cá …",explain:"Đó là thông tin cá nhân.",answer:["nhân"]},{id:"th3-bao-ve-thong-tin-07",type:"mc",q:"Người lạ gọi điện hỏi: “Bố mẹ cháu có nhà không?”. Em nên làm gì?",emoji:"☎️",explain:"Không cho người lạ biết nhà chỉ có mình em; nhờ người lớn nghe máy.",options:["Nhờ người lớn nghe máy","Nói bố mẹ đi vắng cả ngày","Đọc địa chỉ nhà cho họ"],answer:0},{id:"th3-bao-ve-thong-tin-08",type:"tf",q:"Sổ ghi số điện thoại người thân nên để lung tung cho ai xem cũng được.",emoji:"📒",explain:"Sai. Em cất sổ ở nơi an toàn, không để người lạ xem.",answer:!1},{id:"th3-bao-ve-thong-tin-09",type:"mc",q:"Thông tin nào có thể vui vẻ chia sẻ với bạn bè trong lớp?",explain:"Món ăn yêu thích không làm ảnh hưởng đến an toàn của em.",options:["Mật khẩu của em","Giờ nhà em đi vắng","Món ăn em thích"],answer:2}]},{questions:[{id:"th3-bao-ve-thong-tin-10",type:"match",q:"Nối thông tin với cách giữ gìn.",explain:"Mỗi loại thông tin cần cách chia sẻ phù hợp.",pairs:[["Mật khẩu","Chỉ em và bố mẹ biết"],["Bài vẽ đẹp của em","Có thể khoe với thầy cô"],["Địa chỉ nhà","Không nói cho người lạ"]]},{id:"th3-bao-ve-thong-tin-11",type:"mc",q:"Vì sao không nên cho người lạ biết giờ cả nhà đi vắng?",explain:"Kẻ xấu biết nhà vắng người có thể vào lấy trộm đồ.",options:["Người lạ sẽ thấy buồn","Kẻ xấu có thể vào nhà","Vì như thế là bất lịch sự"],answer:1},{id:"th3-bao-ve-thong-tin-12",type:"tf",q:"Ảnh em mặc áo đồng phục in tên trường có thể cho người lạ biết em học ở đâu.",explain:"Đúng. Vì vậy em cần cẩn thận khi đăng ảnh lên mạng.",answer:!0},{id:"th3-bao-ve-thong-tin-13",type:"multi",q:"Việc nào giúp bảo vệ thông tin của gia đình?",explain:"Đọc số điện thoại của mẹ cho người lạ là không an toàn.",options:["Đọc số điện thoại của mẹ cho người lạ","Không kể chuyện riêng của nhà cho người lạ","Hỏi bố mẹ trước khi đăng ảnh","Giữ kín mật khẩu"],answers:[1,2,3]},{id:"th3-bao-ve-thong-tin-14",type:"mc",q:"Bạn thân hỏi mượn mật khẩu tài khoản học tập của Nam. Nam nên làm gì?",explain:"Mật khẩu cần giữ riêng, kể cả với bạn thân.",options:["Cho bạn biết ngay","Từ chối nhẹ nhàng","Viết mật khẩu lên bảng"],answer:1},{id:"th3-bao-ve-thong-tin-15",type:"tf",q:"Em nên ghi mật khẩu lên giấy rồi dán cạnh màn hình máy tính ở phòng máy.",explain:"Sai. Dán mật khẩu như vậy thì ai cũng đọc được.",answer:!1},{id:"th3-bao-ve-thong-tin-16",type:"mc",q:"Một trò chơi đòi nhập họ tên, địa chỉ để nhận vật phẩm. Em nên làm gì?",explain:"Em hỏi bố mẹ trước khi nhập thông tin cá nhân ở bất cứ đâu.",options:["Hỏi bố mẹ trước đã","Nhập ngay để nhận quà","Nhập địa chỉ của bạn"],answer:0},{id:"th3-bao-ve-thong-tin-17",type:"mc",q:"Em nhớ số điện thoại của bố mẹ để làm gì?",explain:"Nhớ số điện thoại bố mẹ giúp em liên lạc khi cần.",options:["Khoe với người lạ","Liên lạc khi cần giúp","Đăng lên trên mạng"],answer:1},{id:"th3-bao-ve-thong-tin-18",type:"multi",q:"Thông tin nào thuộc về gia đình em?",explain:"Tên con vật trong truyện không phải thông tin gia đình.",options:["Địa chỉ nhà","Số điện thoại của bố mẹ","Nơi làm việc của bố mẹ","Tên một con vật trong truyện"],answers:[0,1,2]}]},{questions:[{id:"th3-bao-ve-thong-tin-19",type:"mc",q:"Chi muốn đăng ảnh sinh nhật có cả nhà lên mạng. Chi nên làm gì trước?",emoji:"🎂",explain:"Chi cần hỏi bố mẹ trước khi đăng ảnh gia đình.",options:["Hỏi ý kiến bố mẹ","Đăng ngay lên mạng","Ghi thêm địa chỉ nhà"],answer:0},{id:"th3-bao-ve-thong-tin-20",type:"mc",q:"Một người gọi điện, nói là bạn của bố và hỏi địa chỉ nhà. Bố mẹ đi vắng. Bình nên làm gì?",explain:"Bình không nói địa chỉ cho người chưa quen, chờ bố mẹ về rồi kể lại.",options:["Nói ngay địa chỉ nhà","Không nói, báo lại bố mẹ","Mời người đó đến chơi"],answer:1},{id:"th3-bao-ve-thong-tin-21",type:"order",q:"Sắp xếp việc nên làm khi một trang web hỏi họ tên, địa chỉ của em.",explain:"Dừng lại, hỏi bố mẹ rồi làm theo hướng dẫn.",items:["Dừng lại, chưa nhập gì","Hỏi ý kiến bố mẹ","Làm theo hướng dẫn của bố mẹ"]},{id:"th3-bao-ve-thong-tin-22",type:"tf",q:"Bạn mới quen trên mạng không phải người lạ nên có thể cho biết địa chỉ nhà.",explain:"Sai. Bạn mới quen trên mạng vẫn là người lạ, em không cho biết địa chỉ.",answer:!1},{id:"th3-bao-ve-thong-tin-23",type:"mc",q:"Tùng thấy bạn quên đăng xuất tài khoản trên máy ở phòng máy. Tùng nên làm gì?",explain:"Tùng nhắc bạn đăng xuất, không xem trộm thông tin của bạn.",options:["Vào xem tin nhắn","Nhắc bạn đăng xuất","Đổi mật khẩu để trêu"],answer:1},{id:"th3-bao-ve-thong-tin-24",type:"multi",q:"Em có thể ghi thông tin nào vào bài giới thiệu bản thân ở lớp?",explain:"Mật khẩu phải giữ bí mật.",options:["Mật khẩu của em","Sở thích của em","Món ăn em thích"],answers:[1,2]},{id:"th3-bao-ve-thong-tin-25",type:"mc",q:"Mẹ dặn Ngọc: “Đừng cho người lạ biết số nhà mình”. Lời mẹ giúp bảo vệ điều gì?",explain:"Giữ kín địa chỉ giúp gia đình an toàn.",options:["An toàn cho cả nhà","Đồ chơi của Ngọc","Cây xanh trong vườn"],answer:0},{id:"th3-bao-ve-thong-tin-26",type:"tf",q:"Thấy thông tin của mình bị người khác đăng lên mạng mà em không muốn, em nên báo bố mẹ hoặc thầy cô.",explain:"Đúng. Người lớn sẽ giúp em xử lí.",answer:!0}]}],challenge:{questions:[{id:"th3-bao-ve-thong-tin-27",type:"multi",q:"Trong một bức ảnh của em đăng lên mạng, chi tiết nào có thể làm lộ thông tin cá nhân?",explain:"Biển số nhà và tên trường cho biết em ở đâu, học ở đâu.",options:["Bông hoa trong chậu","Biển số nhà phía sau","Tên trường trên áo đồng phục"],answers:[1,2]},{id:"th3-bao-ve-thong-tin-28",type:"mc",q:"Một số lạ nhắn cho Minh: “Mẹ đây, điện thoại mẹ hỏng, gửi mật khẩu cho mẹ nhé”. Minh nên làm gì?",explain:"Có thể là kẻ xấu giả làm mẹ, Minh cần gọi cho mẹ để hỏi lại.",options:["Gọi lại cho mẹ để hỏi","Gửi ngay mật khẩu","Gửi luôn số của bố"],answer:0},{id:"th3-bao-ve-thong-tin-29",type:"tf",q:"Bảo vệ thông tin cá nhân là giữ an toàn cho em và gia đình.",explain:"Đúng. Giữ kín thông tin giúp kẻ xấu không lợi dụng được.",answer:!0},{id:"th3-bao-ve-thong-tin-10",type:"match",q:"Nối thông tin với cách giữ gìn.",explain:"Mỗi loại thông tin cần cách chia sẻ phù hợp.",pairs:[["Mật khẩu","Chỉ em và bố mẹ biết"],["Bài vẽ đẹp của em","Có thể khoe với thầy cô"],["Địa chỉ nhà","Không nói cho người lạ"]]},{id:"th3-bao-ve-thong-tin-13",type:"multi",q:"Việc nào giúp bảo vệ thông tin của gia đình?",explain:"Đọc số điện thoại của mẹ cho người lạ là không an toàn.",options:["Đọc số điện thoại của mẹ cho người lạ","Không kể chuyện riêng của nhà cho người lạ","Hỏi bố mẹ trước khi đăng ảnh","Giữ kín mật khẩu"],answers:[1,2,3]},{id:"th3-bao-ve-thong-tin-19",type:"mc",q:"Chi muốn đăng ảnh sinh nhật có cả nhà lên mạng. Chi nên làm gì trước?",emoji:"🎂",explain:"Chi cần hỏi bố mẹ trước khi đăng ảnh gia đình.",options:["Hỏi ý kiến bố mẹ","Đăng ngay lên mạng","Ghi thêm địa chỉ nhà"],answer:0},{id:"th3-bao-ve-thong-tin-20",type:"mc",q:"Một người gọi điện, nói là bạn của bố và hỏi địa chỉ nhà. Bố mẹ đi vắng. Bình nên làm gì?",explain:"Bình không nói địa chỉ cho người chưa quen, chờ bố mẹ về rồi kể lại.",options:["Nói ngay địa chỉ nhà","Không nói, báo lại bố mẹ","Mời người đó đến chơi"],answer:1}]},summary:["Họ tên, địa chỉ, số điện thoại, mật khẩu là thông tin cần bảo vệ.","Không cho người lạ biết thông tin của em và gia đình.","Hỏi bố mẹ trước khi đăng ảnh hay nhập thông tin lên mạng."]},{id:"th3-ton-trong-thong-tin",title:"Tôn trọng thông tin của người khác",weeks:[23,24],learn:[{title:"Không tự ý xem, sửa",text:"Không tự ý xem, sửa, xóa tệp, tin nhắn, nhật kí của người khác khi chưa được cho phép.",example:"🚫 xem trộm"},{title:"Xin phép trước",text:"Muốn dùng máy, đọc tài liệu hay dùng ảnh, tranh của người khác, em phải xin phép trước.",example:"🙋 xin phép"},{title:"Lời nói đẹp trên mạng",text:"Dùng lời lẽ lịch sự; không nói tục, không trêu chọc, không chia sẻ tin đồn chưa rõ đúng sai.",example:"💬 lịch sự"},{title:"Giữ gìn máy dùng chung",text:"Ở phòng máy, em giữ gìn máy, không tự cài đặt hay xóa gì khi chưa được thầy cô cho phép.",example:"🖥️ của chung"}],practice:[{questions:[{id:"th3-ton-trong-thong-tin-01",type:"tf",q:"Em được tự ý đọc tin nhắn trên điện thoại của người khác.",emoji:"📱",explain:"Sai. Đọc tin nhắn của người khác cần được cho phép.",answer:!1},{id:"th3-ton-trong-thong-tin-02",type:"mc",q:"Muốn dùng máy tính của anh trai, em cần làm gì?",explain:"Dùng đồ của người khác thì phải xin phép.",options:["Tự mở máy ra dùng","Xin phép anh trước","Đợi anh vắng nhà"],answer:1},{id:"th3-ton-trong-thong-tin-03",type:"tf",q:"Khi viết bình luận trên mạng, em dùng lời lẽ lịch sự.",explain:"Đúng. Trên mạng em cũng cần nói năng lịch sự.",answer:!0},{id:"th3-ton-trong-thong-tin-04",type:"mc",q:"Trong phòng máy, em thấy tệp bài làm của bạn khác. Em nên làm gì?",explain:"Không xóa, không sửa tệp của bạn khi chưa được phép.",options:["Để nguyên, không động vào","Xóa đi cho máy gọn","Sửa lại bài của bạn"],answer:0},{id:"th3-ton-trong-thong-tin-05",type:"multi",q:"Việc nào thể hiện tôn trọng thông tin của người khác?",explain:"Đọc tin nhắn của bố khi chưa được phép là không tôn trọng.",options:["Không xem trộm nhật kí của bạn","Xin phép trước khi dùng ảnh của bạn","Không sửa bài làm của bạn","Đọc tin nhắn của bố khi bố không biết"],answers:[0,1,2]},{id:"th3-ton-trong-thong-tin-06",type:"fill",q:"Trước khi dùng đồ hay tài liệu của người khác, em cần xin …",explain:"Em cần xin phép trước.",answer:["phép"]},{id:"th3-ton-trong-thong-tin-07",type:"tf",q:"Đăng ảnh xấu của bạn lên mạng để trêu là việc vui, nên làm.",explain:"Sai. Việc đó làm bạn buồn và là thiếu tôn trọng bạn.",answer:!1},{id:"th3-ton-trong-thong-tin-08",type:"mc",q:"Ở phòng máy, em muốn cài một trò chơi. Em phải làm gì?",explain:"Máy dùng chung, cần thầy cô cho phép mới được cài.",options:["Tự cài vào ngay","Hỏi thầy cô trước","Cài lén khi vắng cô"],answer:1},{id:"th3-ton-trong-thong-tin-09",type:"tf",q:"Gõ lời lẽ thô tục khi chơi trò chơi trên mạng là bình thường.",explain:"Sai. Em luôn dùng lời lẽ lịch sự, kể cả khi chơi trò chơi.",answer:!1}]},{questions:[{id:"th3-ton-trong-thong-tin-10",type:"mc",q:"Bạn Dũng để quên quyển nhật kí trên bàn. Em nên làm gì?",emoji:"📔",explain:"Nhật kí là thông tin riêng của bạn, em không đọc.",options:["Không đọc, trả lại bạn","Đọc to cho cả lớp nghe","Chụp ảnh đăng lên mạng"],answer:0},{id:"th3-ton-trong-thong-tin-11",type:"match",q:"Nối việc làm với ý nghĩa của nó.",explain:"Những việc làm này thể hiện ứng xử đúng mực.",pairs:[["Xin phép trước khi dùng máy của bạn","Tôn trọng người khác"],["Bình luận lịch sự","Lời nói đẹp trên mạng"],["Giữ gìn máy tính ở phòng máy","Bảo vệ tài sản chung"]]},{id:"th3-ton-trong-thong-tin-12",type:"tf",q:"Ảnh chụp chung với các bạn, em nên hỏi ý các bạn trước khi đăng lên mạng.",explain:"Đúng. Ảnh có các bạn nên cần các bạn đồng ý.",answer:!0},{id:"th3-ton-trong-thong-tin-13",type:"mc",q:"Lan đọc được một tin đồn chưa rõ đúng sai về một bạn cùng lớp. Lan nên làm gì?",explain:"Tin đồn có thể sai và làm bạn buồn, không nên lan truyền.",options:["Không chia sẻ tin đó","Chia sẻ cho nhiều người","Kể thêm cho hấp dẫn"],answer:0},{id:"th3-ton-trong-thong-tin-14",type:"multi",q:"Khi dùng máy tính ở phòng máy, việc nào là đúng?",explain:"Ăn quà trên bàn phím làm bẩn và hỏng máy chung.",options:["Không tự ý xóa tệp","Ăn quà vặt trên bàn phím","Làm theo hướng dẫn của thầy cô","Giữ gìn bàn phím, chuột"],answers:[0,2,3]},{id:"th3-ton-trong-thong-tin-15",type:"mc",q:"Bạn nhờ Phúc xem giúp bài trình chiếu. Phúc thấy một lỗi chính tả. Phúc nên làm gì?",explain:"Phúc góp ý để bạn tự sửa bài của mình.",options:["Tự xóa cả bài của bạn","Chê bạn trước cả lớp","Chỉ cho bạn tự sửa"],answer:2},{id:"th3-ton-trong-thong-tin-16",type:"tf",q:"Máy tính của bạn đang mở thì em có thể xem các tệp của bạn mà không cần hỏi.",explain:"Sai. Em vẫn phải hỏi bạn trước khi xem.",answer:!1},{id:"th3-ton-trong-thong-tin-17",type:"mc",q:"Câu bình luận nào lịch sự dưới bức tranh bạn đăng?",emoji:"🎨",explain:"Lời khen chân thành là lời bình luận lịch sự.",options:["Xấu quá, thôi đi!","Bạn vẽ đẹp quá!","Ai thèm xem chứ!"],answer:1},{id:"th3-ton-trong-thong-tin-18",type:"mc",q:"Dùng xong máy tính ở phòng máy, em nên làm gì?",explain:"Giữ gọn gàng giúp bảo vệ máy dùng chung.",options:["Để bàn phím, chuột bừa bộn","Rút dây chuột mang về nhà","Xếp chuột, bàn phím gọn gàng"],answer:2}]},{questions:[{id:"th3-ton-trong-thong-tin-19",type:"mc",q:"Khoa thấy tờ giấy ghi mật khẩu của bạn để quên trên bàn. Khoa nên làm gì?",explain:"Khoa không xem, trả lại và nhắc bạn cất kĩ.",options:["Gấp lại, trả và nhắc bạn","Dùng thử để đăng nhập","Đọc to cho cả lớp nghe"],answer:0},{id:"th3-ton-trong-thong-tin-20",type:"mc",q:"Minh muốn dùng một bức tranh của Vy cho bài trình chiếu. Minh nên làm gì?",explain:"Dùng tranh của bạn cần xin phép và ghi tên người vẽ.",options:["Dùng và nói tranh là của mình","Hỏi Vy, ghi tên Vy dưới tranh","Sửa tranh rồi nhận là của mình"],answer:1},{id:"th3-ton-trong-thong-tin-21",type:"order",q:"Sắp xếp các bước khi muốn dùng máy tính của bố.",explain:"Xin phép, chờ đồng ý rồi dùng đúng việc được cho phép.",items:["Hỏi xin phép bố","Chờ bố đồng ý","Chỉ dùng phần việc bố cho phép"]},{id:"th3-ton-trong-thong-tin-22",type:"multi",q:"Trong nhóm tin nhắn của lớp, có người nói lời trêu chọc một bạn. Em nên làm gì?",explain:"Gửi thêm hình trêu bạn làm bạn tổn thương.",options:["Gửi thêm hình trêu bạn","Không hùa theo","Nhắn các bạn nói lời tử tế","Báo thầy cô nếu việc trêu chọc vẫn tiếp diễn"],answers:[1,2,3]},{id:"th3-ton-trong-thong-tin-23",type:"tf",q:"Lấy bài viết của người khác rồi nói là của mình là việc làm trung thực.",explain:"Sai. Đó là việc làm không trung thực.",answer:!1},{id:"th3-ton-trong-thong-tin-24",type:"mc",q:"Thảo vô tình làm mất tệp của bạn trong máy dùng chung. Thảo nên làm gì?",explain:"Thảo nhận lỗi và nhờ thầy cô tìm cách lấy lại tệp.",options:["Im lặng, giấu chuyện đi","Đổ lỗi cho bạn khác","Xin lỗi bạn, báo thầy cô"],answer:2},{id:"th3-ton-trong-thong-tin-25",type:"mc",q:"Trong giờ thực hành, máy của Hà bị đứng, không bấm được gì. Hà nên làm gì?",explain:"Hà báo thầy cô để được giúp, không tự ý xử lí.",options:["Giơ tay báo thầy cô","Đập vào màn hình","Tự rút dây điện ra"],answer:0},{id:"th3-ton-trong-thong-tin-26",type:"tf",q:"Trên mạng, em cũng cần lễ phép, lịch sự như khi nói chuyện trực tiếp.",explain:"Đúng. Phía bên kia màn hình cũng là người thật.",answer:!0}]}],challenge:{questions:[{id:"th3-ton-trong-thong-tin-27",type:"match",q:"Nối tình huống với cách ứng xử đúng.",explain:"Đây là những cách ứng xử tôn trọng người khác.",pairs:[["Muốn mượn máy tính bảng của chị","Xin phép chị trước"],["Thấy nhật kí của bạn","Không đọc trộm"],["Muốn dùng ảnh bạn chụp","Hỏi ý và ghi tên bạn"],["Thấy tin đồn về bạn","Không chia sẻ tiếp"]]},{id:"th3-ton-trong-thong-tin-28",type:"multi",q:"Hành động nào là chưa tôn trọng thông tin của người khác?",explain:"Hỏi ý bạn trước khi xem ảnh là tôn trọng bạn.",options:["Đổi tên tệp của bạn để trêu","Hỏi ý bạn trước khi xem ảnh","Xóa bài làm của bạn trong máy chung","Đọc trộm tin nhắn của chị"],answers:[0,2,3]},{id:"th3-ton-trong-thong-tin-29",type:"mc",q:"Ngọc mượn điện thoại của mẹ để gọi cho bà. Gọi xong, Ngọc nên làm gì?",explain:"Ngọc chỉ dùng điện thoại vào việc mẹ cho phép.",options:["Mở xem hết ảnh trong máy","Trả máy, không xem gì thêm","Đọc hết tin nhắn của mẹ"],answer:1},{id:"th3-ton-trong-thong-tin-05",type:"multi",q:"Việc nào thể hiện tôn trọng thông tin của người khác?",explain:"Đọc tin nhắn của bố khi chưa được phép là không tôn trọng.",options:["Không xem trộm nhật kí của bạn","Xin phép trước khi dùng ảnh của bạn","Không sửa bài làm của bạn","Đọc tin nhắn của bố khi bố không biết"],answers:[0,1,2]},{id:"th3-ton-trong-thong-tin-13",type:"mc",q:"Lan đọc được một tin đồn chưa rõ đúng sai về một bạn cùng lớp. Lan nên làm gì?",explain:"Tin đồn có thể sai và làm bạn buồn, không nên lan truyền.",options:["Không chia sẻ tin đó","Chia sẻ cho nhiều người","Kể thêm cho hấp dẫn"],answer:0},{id:"th3-ton-trong-thong-tin-20",type:"mc",q:"Minh muốn dùng một bức tranh của Vy cho bài trình chiếu. Minh nên làm gì?",explain:"Dùng tranh của bạn cần xin phép và ghi tên người vẽ.",options:["Dùng và nói tranh là của mình","Hỏi Vy, ghi tên Vy dưới tranh","Sửa tranh rồi nhận là của mình"],answer:1},{id:"th3-ton-trong-thong-tin-22",type:"multi",q:"Trong nhóm tin nhắn của lớp, có người nói lời trêu chọc một bạn. Em nên làm gì?",explain:"Gửi thêm hình trêu bạn làm bạn tổn thương.",options:["Gửi thêm hình trêu bạn","Không hùa theo","Nhắn các bạn nói lời tử tế","Báo thầy cô nếu việc trêu chọc vẫn tiếp diễn"],answers:[1,2,3]}]},summary:["Không tự ý xem, sửa, xóa thông tin của người khác.","Xin phép trước khi dùng máy, ảnh, bài viết của người khác.","Nói năng lịch sự, không lan truyền tin đồn, giữ gìn máy dùng chung."]}]},{id:"ung-dung-tin-hoc",title:"Ứng dụng tin học",lessons:[{id:"th3-trinh-chieu",title:"Làm quen với phần mềm trình chiếu",weeks:[25,26],learn:[{title:"Phần mềm trình chiếu",text:"Phần mềm trình chiếu giúp em tạo các trang chiếu có chữ, hình ảnh để giới thiệu, thuyết trình.",example:"🖥️ trang chiếu"},{title:"Bài trình chiếu",text:"Một bài trình chiếu gồm nhiều trang chiếu. Trang đầu thường là trang tiêu đề, có tên bài và tên người trình bày.",example:"1️⃣ tiêu đề  ·  2️⃣ 3️⃣ nội dung"},{title:"Trang chiếu dễ đọc",text:"Chữ đủ to, màu chữ nổi rõ trên màu nền, viết ngắn gọn, có hình minh họa đúng chủ đề.",example:"🔠 chữ to  ·  🖼️ hình đúng chủ đề"},{title:"Trình chiếu và lưu bài",text:"Khi trình chiếu, trang chiếu hiện to toàn màn hình. Làm xong, em lưu bài với tên dễ hiểu.",example:"💾 lưu bài"}],practice:[{questions:[{id:"th3-trinh-chieu-01",type:"mc",q:"Phần mềm trình chiếu dùng để làm gì?",explain:"Phần mềm trình chiếu giúp tạo trang chiếu để giới thiệu, thuyết trình.",options:["Nấu cơm cho cả nhà ăn","Tạo trang chiếu để thuyết trình","Giặt sạch quần áo bẩn"],answer:1},{id:"th3-trinh-chieu-02",type:"tf",q:"Một bài trình chiếu có thể gồm nhiều trang chiếu.",explain:"Đúng. Bài trình chiếu thường có nhiều trang chiếu.",answer:!0},{id:"th3-trinh-chieu-03",type:"mc",q:"Trang đầu tiên của bài trình chiếu thường là trang gì?",explain:"Trang đầu thường là trang tiêu đề.",options:["Trang tiêu đề","Trang cảm ơn","Trang để trống"],answer:0},{id:"th3-trinh-chieu-04",type:"multi",q:"Trên trang chiếu có thể có những gì?",explain:"Bánh kẹo thật không thể đặt vào trang chiếu.",options:["Màu nền","Bánh kẹo thật","Chữ","Hình ảnh"],answers:[0,2,3]},{id:"th3-trinh-chieu-05",type:"tf",q:"Trang tiêu đề thường có tên bài trình chiếu và tên người trình bày.",explain:"Đúng. Trang tiêu đề cho biết bài nói về gì và ai trình bày.",answer:!0},{id:"th3-trinh-chieu-06",type:"fill",q:"Mỗi trang trong bài trình chiếu gọi là một trang …",explain:"Đó là trang chiếu.",answer:["chiếu"]},{id:"th3-trinh-chieu-07",type:"mc",q:"Khi trình chiếu, trang chiếu thường hiện ra thế nào?",explain:"Khi trình chiếu, trang chiếu hiện toàn màn hình để mọi người cùng xem.",options:["Rất nhỏ ở góc màn hình","To, đầy cả màn hình","Không hiện ra gì cả"],answer:1},{id:"th3-trinh-chieu-08",type:"tf",q:"Không thể thêm hình ảnh vào trang chiếu.",emoji:"🖼️",explain:"Sai. Em có thể thêm hình ảnh để bài sinh động hơn.",answer:!1},{id:"th3-trinh-chieu-09",type:"mc",q:"Muốn gõ chữ vào trang chiếu, em dùng thiết bị nào?",emoji:"⌨️",explain:"Em gõ chữ bằng bàn phím.",options:["Bàn phím","Loa","Tai nghe"],answer:0}]},{questions:[{id:"th3-trinh-chieu-10",type:"mc",q:"Chi làm bài giới thiệu về gia đình. Tiêu đề nào phù hợp nhất?",emoji:"👨‍👩‍👧",explain:"Tiêu đề cần đúng với nội dung bài giới thiệu.",options:["Trò chơi vui","Gia đình em","Bài tập Toán"],answer:1},{id:"th3-trinh-chieu-11",type:"order",q:"Sắp xếp các bước làm một bài trình chiếu đơn giản.",explain:"Mở phần mềm, làm trang chiếu rồi lưu bài.",items:["Mở phần mềm trình chiếu","Tạo trang chiếu và gõ nội dung","Lưu bài trình chiếu"]},{id:"th3-trinh-chieu-12",type:"multi",q:"Trang chiếu dễ đọc có đặc điểm gì?",explain:"Chữ nhỏ xíu, dày đặc làm người xem khó đọc.",options:["Chữ nhỏ xíu, dày đặc","Chữ đủ to","Màu chữ nổi rõ trên màu nền","Ít chữ, có hình minh họa"],answers:[1,2,3]},{id:"th3-trinh-chieu-13",type:"tf",q:"Chữ màu vàng nhạt trên nền trắng rất dễ đọc.",explain:"Sai. Vàng nhạt trên nền trắng rất khó nhìn.",answer:!1},{id:"th3-trinh-chieu-14",type:"mc",q:"Nam muốn giới thiệu con mèo nhà mình. Hình nào phù hợp để đưa vào trang chiếu?",emoji:"🐱",explain:"Hình ảnh cần đúng với chủ đề bài giới thiệu.",options:["Ảnh một chiếc ô tô","Ảnh một cái bàn học","Ảnh con mèo nhà Nam"],answer:2},{id:"th3-trinh-chieu-15",type:"match",q:"Nối phần của bài trình chiếu với nội dung thường có.",explain:"Bài trình chiếu thường có trang tiêu đề, các trang nội dung và trang cuối.",pairs:[["Trang tiêu đề","Tên bài và tên người trình bày"],["Trang nội dung","Chữ và hình về chủ đề"],["Trang cuối","Lời cảm ơn người xem"]]},{id:"th3-trinh-chieu-16",type:"tf",q:"Làm xong bài trình chiếu, em cần lưu lại để lần sau mở ra dùng tiếp.",emoji:"💾",explain:"Đúng. Lưu bài giúp không bị mất bài làm.",answer:!0},{id:"th3-trinh-chieu-17",type:"mc",q:"Tên tệp nào giúp em dễ tìm lại bài trình chiếu về gia đình?",explain:"Tên tệp rõ nghĩa giúp tìm lại bài nhanh.",options:["Bài mới","abc","Gia đình em"],answer:2},{id:"th3-trinh-chieu-18",type:"mc",q:"Trang chiếu có quá nhiều chữ thì người xem sẽ thế nào?",explain:"Quá nhiều chữ làm người xem khó đọc và nhanh chán.",options:["Khó đọc, nhanh chán","Dễ nhớ hơn nhiều","Thấy đẹp mắt hơn"],answer:0}]},{questions:[{id:"th3-trinh-chieu-19",type:"mc",q:"Vy làm bài giới thiệu về trường em gồm 3 trang. Trang thứ nhất nên là gì?",emoji:"🏫",explain:"Trang đầu nên là trang tiêu đề.",options:["Ảnh sân trường không chữ","Trang tiêu đề “Trường em”","Lời cảm ơn người xem"],answer:1},{id:"th3-trinh-chieu-20",type:"order",q:"Sắp xếp các trang của bài “Con vật em yêu” cho hợp lí.",explain:"Tiêu đề trước, rồi tả con vật, cuối cùng nói tình cảm của em.",items:["Trang tiêu đề “Con vật em yêu”","Trang tả hình dáng con vật","Trang nói tình cảm của em với con vật"]},{id:"th3-trinh-chieu-21",type:"multi",q:"Bài trình chiếu “Mùa xuân quê em” nên có những hình ảnh nào?",emoji:"🌸",explain:"Người tuyết không phải hình ảnh mùa xuân ở quê em.",options:["Hoa đào, hoa mai","Cây cối đâm chồi","Người tuyết"],answers:[0,1]},{id:"th3-trinh-chieu-22",type:"mc",q:"Tùng đặt chữ màu đen trên nền màu đen. Có vấn đề gì?",explain:"Chữ cùng màu với nền thì không nhìn thấy được.",options:["Chữ hiện rất rõ","Không đọc được chữ","Trang rất đẹp mắt"],answer:1},{id:"th3-trinh-chieu-23",type:"tf",q:"Khi trình bày trước lớp, em nói rõ ràng, chỉ vào nội dung trên trang chiếu.",explain:"Đúng. Nói rõ ràng giúp các bạn dễ theo dõi.",answer:!0},{id:"th3-trinh-chieu-24",type:"mc",q:"Phúc làm xong bài nhưng tắt máy mà chưa lưu. Điều gì có thể xảy ra?",explain:"Chưa lưu mà tắt máy thì bài có thể bị mất.",options:["Bài làm có thể bị mất","Bài tự in ra giấy","Không có gì xảy ra"],answer:0},{id:"th3-trinh-chieu-25",type:"mc",q:"Hà muốn trình bày bài cho cả lớp xem. Hà nên làm gì?",explain:"Trình chiếu toàn màn hình giúp cả lớp nhìn rõ.",options:["Thu nhỏ cửa sổ thật bé lại","Chọn trình chiếu toàn màn hình","Tắt màn hình rồi nói tiếp"],answer:1},{id:"th3-trinh-chieu-26",type:"multi",q:"Việc nào giúp bài trình chiếu hay hơn?",explain:"Quá nhiều màu chói mắt làm khó nhìn.",options:["Kiểm tra chính tả","Dùng thật nhiều màu chói mắt","Chọn hình đúng chủ đề","Viết ngắn gọn"],answers:[0,2,3]}]}],challenge:{questions:[{id:"th3-trinh-chieu-27",type:"order",q:"Sắp xếp các bước làm bài trình chiếu giới thiệu về em.",explain:"Lên ý tưởng, làm trang tiêu đề, trang nội dung rồi lưu và tập trình bày.",items:["Nghĩ xem sẽ giới thiệu những gì","Tạo trang tiêu đề","Tạo các trang nội dung","Lưu bài và tập trình bày"]},{id:"th3-trinh-chieu-28",type:"mc",q:"Trang chiếu của Ngọc chữ nhỏ, màu nhạt, rất nhiều chữ. Ngọc nên sửa thế nào?",explain:"Viết ngắn gọn, chữ to và màu rõ giúp trang chiếu dễ đọc.",options:["Thêm thật nhiều chữ nữa","Viết gọn, chữ to, màu rõ","Xóa hết, để trang trống"],answer:1},{id:"th3-trinh-chieu-29",type:"tf",q:"Trong bài trình chiếu, chữ và hình ảnh không cần đúng với chủ đề.",explain:"Sai. Nội dung chữ và hình ảnh cần đúng chủ đề của bài.",answer:!1},{id:"th3-trinh-chieu-11",type:"order",q:"Sắp xếp các bước làm một bài trình chiếu đơn giản.",explain:"Mở phần mềm, làm trang chiếu rồi lưu bài.",items:["Mở phần mềm trình chiếu","Tạo trang chiếu và gõ nội dung","Lưu bài trình chiếu"]},{id:"th3-trinh-chieu-12",type:"multi",q:"Trang chiếu dễ đọc có đặc điểm gì?",explain:"Chữ nhỏ xíu, dày đặc làm người xem khó đọc.",options:["Chữ nhỏ xíu, dày đặc","Chữ đủ to","Màu chữ nổi rõ trên màu nền","Ít chữ, có hình minh họa"],answers:[1,2,3]},{id:"th3-trinh-chieu-19",type:"mc",q:"Vy làm bài giới thiệu về trường em gồm 3 trang. Trang thứ nhất nên là gì?",emoji:"🏫",explain:"Trang đầu nên là trang tiêu đề.",options:["Ảnh sân trường không chữ","Trang tiêu đề “Trường em”","Lời cảm ơn người xem"],answer:1},{id:"th3-trinh-chieu-20",type:"order",q:"Sắp xếp các trang của bài “Con vật em yêu” cho hợp lí.",explain:"Tiêu đề trước, rồi tả con vật, cuối cùng nói tình cảm của em.",items:["Trang tiêu đề “Con vật em yêu”","Trang tả hình dáng con vật","Trang nói tình cảm của em với con vật"]}]},summary:["Phần mềm trình chiếu giúp tạo các trang chiếu có chữ và hình ảnh.","Trang đầu là trang tiêu đề; chữ to, màu rõ, ngắn gọn giúp dễ đọc.","Làm xong, em lưu bài với tên dễ hiểu."]},{id:"th3-hoc-tap-giai-tri",title:"Học tập và giải trí với máy tính",weeks:[27,28],learn:[{title:"Phần mềm học tập",text:"Có phần mềm giúp em luyện gõ phím, luyện dùng chuột, học toán, học tiếng Anh qua trò chơi.",example:"⌨️ luyện gõ  ·  🖱️ luyện chuột"},{title:"Xem video học tập",text:"Em có thể xem video tìm hiểu thiên nhiên, loài vật, lịch sử, văn hóa quê hương.",example:"🐘 loài vật  ·  🏯 di tích"},{title:"Luyện gõ phím",text:"Bắt đầu từ hàng phím cơ sở; gõ chậm mà đúng trước, rồi tăng tốc dần; kiên trì luyện mỗi ngày.",example:"A S D F  ·  J K L"},{title:"Dùng máy tính hợp lí",text:"Chỉ dùng phần mềm, trò chơi phù hợp lứa tuổi, được người lớn cho phép; xen kẽ nghỉ ngơi, vận động.",example:"⏰ đúng giờ  ·  🤸 vận động"}],practice:[{questions:[{id:"th3-hoc-tap-giai-tri-01",type:"mc",q:"Phần mềm luyện gõ phím giúp em điều gì?",emoji:"⌨️",explain:"Phần mềm luyện gõ giúp em gõ đúng ngón và nhanh dần.",options:["Nấu được món ăn ngon","Gõ đúng ngón, nhanh dần","Chạy nhanh hơn các bạn"],answer:1},{id:"th3-hoc-tap-giai-tri-02",type:"tf",q:"Máy tính có thể giúp em học tập qua video, trò chơi học tập.",explain:"Đúng. Dùng hợp lí, máy tính giúp em học tốt hơn.",answer:!0},{id:"th3-hoc-tap-giai-tri-03",type:"multi",q:"Em có thể học gì qua máy tính?",explain:"Tập bơi phải học ở bể bơi thật.",options:["Luyện gõ phím","Học tiếng Anh qua bài hát","Xem video về các loài vật","Tập bơi dưới nước"],answers:[0,1,2]},{id:"th3-hoc-tap-giai-tri-04",type:"tf",q:"Chơi trò chơi trên máy tính càng lâu càng tốt cho sức khỏe.",explain:"Sai. Chơi quá lâu hại mắt và sức khỏe.",answer:!1},{id:"th3-hoc-tap-giai-tri-05",type:"mc",q:"Khi luyện gõ, em nên bắt đầu từ hàng phím nào?",explain:"Em bắt đầu từ hàng phím cơ sở, nơi đặt tay.",options:["Hàng phím số","Hàng phím dưới","Hàng phím cơ sở"],answer:2},{id:"th3-hoc-tap-giai-tri-06",type:"mc",q:"Video nào giúp em tìm hiểu lịch sử, văn hóa quê hương?",emoji:"🏯",explain:"Video giới thiệu di tích, lễ hội giúp em hiểu về quê hương.",options:["Video về di tích, lễ hội","Video quảng cáo đồ chơi","Video trò chơi bắn súng"],answer:0},{id:"th3-hoc-tap-giai-tri-07",type:"fill",q:"Khi luyện gõ phím, em nên gõ chậm mà … trước, rồi tăng tốc dần.",explain:"Gõ đúng trước, nhanh sau.",answer:["đúng","chính xác"]},{id:"th3-hoc-tap-giai-tri-08",type:"tf",q:"Em chỉ nên dùng phần mềm, trò chơi phù hợp lứa tuổi và được người lớn cho phép.",explain:"Đúng. Người lớn giúp em chọn phần mềm phù hợp.",answer:!0},{id:"th3-hoc-tap-giai-tri-09",type:"mc",q:"Dùng máy tính một lúc lâu, em nên làm gì?",emoji:"🤸",explain:"Nghỉ ngơi, vận động giúp mắt và cơ thể khỏe.",options:["Đứng dậy nghỉ, vận động nhẹ","Ngồi tiếp mãi không nghỉ","Dụi mắt thật mạnh nhiều lần"],answer:0}]},{questions:[{id:"th3-hoc-tap-giai-tri-10",type:"match",q:"Nối phần mềm với điều em học được.",explain:"Mỗi phần mềm giúp em học một điều.",pairs:[["Phần mềm luyện gõ","Gõ phím đúng ngón"],["Trò chơi luyện chuột","Nháy, kéo thả chuột khéo léo"],["Video về thiên nhiên","Biết thêm về cây cối, con vật"]]},{id:"th3-hoc-tap-giai-tri-11",type:"mc",q:"Trò chơi kéo quả táo thả vào giỏ giúp em luyện kĩ năng gì?",emoji:"🍎",explain:"Kéo thả là thao tác với chuột.",options:["Gõ phím","Ca hát","Dùng chuột"],answer:2},{id:"th3-hoc-tap-giai-tri-12",type:"tf",q:"Học qua trò chơi trên máy tính, nếu dùng hợp lí, có thể giúp em nhớ bài lâu hơn.",explain:"Đúng. Trò chơi học tập giúp việc học vui và dễ nhớ.",answer:!0},{id:"th3-hoc-tap-giai-tri-13",type:"multi",q:"Đâu là cách dùng máy tính để giải trí lành mạnh?",explain:"Chơi suốt đêm có hại cho sức khỏe.",options:["Chơi suốt đêm không ngủ","Nghe nhạc thiếu nhi","Vẽ tranh trên máy tính","Chơi trò chơi trí tuệ vừa sức"],answers:[1,2,3]},{id:"th3-hoc-tap-giai-tri-14",type:"mc",q:"Đang luyện gõ, Bình gõ sai nhiều. Bình nên làm gì?",explain:"Gõ chậm, đặt tay đúng hàng phím cơ sở giúp gõ đúng hơn.",options:["Bỏ cuộc, không luyện nữa","Gõ thật mạnh cho nhanh","Gõ chậm lại, đặt tay đúng"],answer:2},{id:"th3-hoc-tap-giai-tri-15",type:"tf",q:"Xem video về lịch sử, văn hóa không phải là cách học tập.",explain:"Sai. Đó là một cách học tập bổ ích trên máy tính.",answer:!1},{id:"th3-hoc-tap-giai-tri-16",type:"mc",q:"Bạn rủ Lan chơi một trò chơi có nhiều cảnh bạo lực. Lan nên làm gì?",explain:"Trò chơi bạo lực không phù hợp với Lan.",options:["Đồng ý chơi ngay","Từ chối, chọn trò khác","Rủ thêm em nhỏ chơi"],answer:1},{id:"th3-hoc-tap-giai-tri-17",type:"mc",q:"Xem video học tập xong, em nên làm gì để nhớ lâu?",explain:"Kể lại hoặc ghi lại giúp em nhớ lâu.",options:["Quên ngay cho nhẹ đầu","Xem video khác không liên quan","Kể lại điều đã học"],answer:2},{id:"th3-hoc-tap-giai-tri-18",type:"multi",q:"Khi dùng máy tính để học, việc làm nào đúng?",explain:"Vừa ăn vừa gõ phím dễ làm bẩn, hỏng bàn phím.",options:["Ngồi đúng tư thế","Dùng trong thời gian bố mẹ cho phép","Chọn phần mềm học tập phù hợp","Vừa ăn vừa gõ phím"],answers:[0,1,2]}]},{questions:[{id:"th3-hoc-tap-giai-tri-19",type:"mc",q:"Dũng muốn tìm hiểu về các loài chim. Dũng nên chọn gì?",emoji:"🐦",explain:"Video về các loài chim đúng với điều Dũng muốn tìm hiểu.",options:["Trò chơi đua xe tốc độ","Video về các loài chim","Video quảng cáo kẹo"],answer:1},{id:"th3-hoc-tap-giai-tri-20",type:"mc",q:"Nam đang chơi trò chơi học toán thì đến giờ mẹ dặn phải nghỉ. Nam nên làm gì?",explain:"Nam giữ đúng giờ đã hứa với mẹ.",options:["Xin chơi thêm cả buổi","Chơi lén khi mẹ đi vắng","Dừng chơi, tắt máy"],answer:2},{id:"th3-hoc-tap-giai-tri-21",type:"order",q:"Sắp xếp một buổi luyện gõ phím hợp lí.",explain:"Chuẩn bị tư thế, luyện gõ, rồi nghỉ ngơi.",items:["Ngồi đúng tư thế, đặt tay lên hàng phím cơ sở","Luyện gõ theo bài trong phần mềm","Nghỉ tay, thư giãn mắt"]},{id:"th3-hoc-tap-giai-tri-22",type:"multi",q:"Vy muốn luyện dùng chuột cho khéo. Vy có thể chọn trò chơi nào?",explain:"Nghe kể chuyện không luyện thao tác chuột.",options:["Trò chơi nháy chuột vào quả bóng","Trò chơi tô màu bằng chuột","Nghe kể chuyện qua loa","Trò chơi kéo thả ghép hình"],answers:[0,1,3]},{id:"th3-hoc-tap-giai-tri-23",type:"tf",q:"Khi chơi trò chơi trên máy tính, em không cần giữ tư thế ngồi đúng.",explain:"Sai. Lúc nào dùng máy tính em cũng cần ngồi đúng tư thế.",answer:!1},{id:"th3-hoc-tap-giai-tri-24",type:"mc",q:"Phúc thích vẽ. Phúc có thể dùng máy tính để làm gì?",emoji:"🎨",explain:"Phần mềm vẽ giúp Phúc tạo tranh trên máy tính.",options:["Vẽ tranh bằng phần mềm vẽ","Bỏ học ở nhà để chơi máy","Xem video không phù hợp"],answer:0},{id:"th3-hoc-tap-giai-tri-25",type:"mc",q:"Chi xem video về một lễ hội ở quê mình. Video giúp Chi điều gì?",explain:"Tìm hiểu lễ hội giúp Chi hiểu và yêu quê hương.",options:["Mỏi mắt hơn mọi ngày","Hiểu, yêu quê hương hơn","Quên hết bài học cũ"],answer:1},{id:"th3-hoc-tap-giai-tri-26",type:"tf",q:"Mỗi lần dùng máy tính, em nên xen kẽ nghỉ ngơi cho mắt.",explain:"Đúng. Nghỉ ngơi giúp mắt không bị mỏi.",answer:!0}]}],challenge:{questions:[{id:"th3-hoc-tap-giai-tri-27",type:"match",q:"Nối việc làm với lợi ích.",explain:"Mỗi việc làm mang lại một lợi ích.",pairs:[["Luyện gõ mười ngón","Gõ nhanh, chính xác"],["Xem video về các loài vật","Biết thêm về thế giới tự nhiên"],["Nghỉ giải lao, vận động","Khỏe mắt, khỏe người"],["Chơi trò chơi kéo thả","Dùng chuột khéo léo"]]},{id:"th3-hoc-tap-giai-tri-28",type:"multi",q:"Hà được dùng máy tính 30 phút. Kế hoạch nào hợp lí?",explain:"Hà chọn việc bổ ích, tránh trò chơi bạo lực và người lạ.",options:["Trò chuyện với người lạ","Luyện gõ phím 15 phút","Xem video học tập 15 phút","Chơi trò chơi bạo lực"],answers:[1,2]},{id:"th3-hoc-tap-giai-tri-29",type:"mc",q:"Khi tập gõ, Khoa thấy mình gõ chậm hơn bạn. Khoa nên nghĩ thế nào?",explain:"Kiên trì luyện tập mỗi ngày, Khoa sẽ gõ nhanh hơn.",options:["Mình không bao giờ gõ được","Không cần luyện tập nữa","Kiên trì luyện sẽ tiến bộ"],answer:2},{id:"th3-hoc-tap-giai-tri-10",type:"match",q:"Nối phần mềm với điều em học được.",explain:"Mỗi phần mềm giúp em học một điều.",pairs:[["Phần mềm luyện gõ","Gõ phím đúng ngón"],["Trò chơi luyện chuột","Nháy, kéo thả chuột khéo léo"],["Video về thiên nhiên","Biết thêm về cây cối, con vật"]]},{id:"th3-hoc-tap-giai-tri-13",type:"multi",q:"Đâu là cách dùng máy tính để giải trí lành mạnh?",explain:"Chơi suốt đêm có hại cho sức khỏe.",options:["Chơi suốt đêm không ngủ","Nghe nhạc thiếu nhi","Vẽ tranh trên máy tính","Chơi trò chơi trí tuệ vừa sức"],answers:[1,2,3]},{id:"th3-hoc-tap-giai-tri-20",type:"mc",q:"Nam đang chơi trò chơi học toán thì đến giờ mẹ dặn phải nghỉ. Nam nên làm gì?",explain:"Nam giữ đúng giờ đã hứa với mẹ.",options:["Xin chơi thêm cả buổi","Chơi lén khi mẹ đi vắng","Dừng chơi, tắt máy"],answer:2},{id:"th3-hoc-tap-giai-tri-21",type:"order",q:"Sắp xếp một buổi luyện gõ phím hợp lí.",explain:"Chuẩn bị tư thế, luyện gõ, rồi nghỉ ngơi.",items:["Ngồi đúng tư thế, đặt tay lên hàng phím cơ sở","Luyện gõ theo bài trong phần mềm","Nghỉ tay, thư giãn mắt"]}]},summary:["Máy tính giúp em luyện gõ, luyện chuột, học qua video và trò chơi.","Chọn phần mềm, video phù hợp lứa tuổi, được người lớn cho phép.","Dùng máy tính đúng giờ, ngồi đúng tư thế, xen kẽ nghỉ ngơi."]}]},{id:"giai-quyet-van-de",title:"Giải quyết vấn đề với sự trợ giúp của máy tính",lessons:[{id:"th3-theo-buoc",title:"Thực hiện công việc theo các bước",weeks:[29,30],learn:[{title:"Làm theo các bước",text:"Nhiều công việc cần làm theo các bước, theo đúng thứ tự thì mới có kết quả tốt.",example:"1️⃣ ➜ 2️⃣ ➜ 3️⃣"},{title:"Sai thứ tự sẽ hỏng việc",text:"Đánh răng: lấy kem lên bàn chải trước, rồi mới chải răng, cuối cùng súc miệng.",example:"🪥 kem  ➜  chải  ➜  súc miệng"},{title:"Nói rõ từng bước",text:"Khi hướng dẫn, em dùng các từ “đầu tiên”, “tiếp theo”, “sau đó”, “cuối cùng” hoặc đánh số các bước.",example:"Đầu tiên… Tiếp theo… Cuối cùng…"},{title:"Máy tính làm theo các bước",text:"Máy tính, rô-bốt làm việc theo đúng các bước con người đưa vào.",example:"🤖 rô-bốt làm theo lệnh"}],practice:[{questions:[{id:"th3-theo-buoc-01",type:"order",q:"Sắp xếp các bước đánh răng.",emoji:"🪥",explain:"Lấy kem, chải răng rồi súc miệng.",items:["Lấy kem đánh răng lên bàn chải","Chải răng","Súc miệng bằng nước sạch"]},{id:"th3-theo-buoc-02",type:"tf",q:"Nhiều công việc cần thực hiện theo đúng thứ tự các bước.",explain:"Đúng. Làm đúng thứ tự thì công việc mới có kết quả tốt.",answer:!0},{id:"th3-theo-buoc-03",type:"order",q:"Sắp xếp các bước rửa tay.",emoji:"🧼",explain:"Làm ướt tay, xoa xà phòng, rửa sạch rồi lau khô.",items:["Làm ướt tay","Xoa xà phòng","Rửa sạch xà phòng dưới vòi nước","Lau khô tay"]},{id:"th3-theo-buoc-04",type:"mc",q:"Từ nào thường dùng để nói về bước làm đầu tiên?",explain:"Từ “đầu tiên” chỉ bước làm trước hết.",options:["Đầu tiên","Cuối cùng","Sau đó"],answer:0},{id:"th3-theo-buoc-05",type:"tf",q:"Làm sai thứ tự các bước thì kết quả lúc nào cũng vẫn đúng.",explain:"Sai. Làm sai thứ tự có thể làm hỏng việc.",answer:!1},{id:"th3-theo-buoc-06",type:"order",q:"Sắp xếp các bước gọt và ăn quả táo.",emoji:"🍎",explain:"Rửa sạch, gọt vỏ, cắt miếng rồi mới ăn.",items:["Rửa sạch quả táo","Gọt vỏ","Cắt thành miếng","Ăn táo"]},{id:"th3-theo-buoc-07",type:"fill",q:"Từ chỉ bước làm sau cùng là “cuối …”.",explain:"Bước sau cùng gọi là bước “cuối cùng”.",answer:["cùng"]},{id:"th3-theo-buoc-08",type:"mc",q:"Máy tính làm việc như thế nào?",emoji:"🖥️",explain:"Máy tính làm theo các bước con người đưa vào.",options:["Tự nghĩ ra mọi việc theo ý mình","Theo các bước con người đưa vào","Không cần ai điều khiển bao giờ"],answer:1},{id:"th3-theo-buoc-09",type:"order",q:"Sắp xếp các bước trồng cây hoa vào chậu.",emoji:"🌼",explain:"Cho đất, đặt cây, vun gốc rồi tưới nước.",items:["Cho đất vào chậu","Đặt cây con vào giữa chậu","Vun đất quanh gốc cây","Tưới nước cho cây"]}]},{questions:[{id:"th3-theo-buoc-10",type:"order",q:"Sắp xếp các bước xem một video bài học trên máy tính.",explain:"Bật máy, mở video, xem rồi tắt máy.",items:["Bật máy tính","Mở video bài học","Xem video","Tắt máy tính"]},{id:"th3-theo-buoc-11",type:"mc",q:"Khi đánh răng, nếu chải răng trước rồi mới lấy kem thì sao?",explain:"Làm sai thứ tự thì việc đánh răng không có kết quả tốt.",options:["Răng sạch hơn mọi ngày","Răng chưa được làm sạch tốt","Không có gì khác cả"],answer:1},{id:"th3-theo-buoc-12",type:"match",q:"Nối từ chỉ thứ tự với bước rửa tay.",explain:"Các từ chỉ thứ tự giúp nói rõ từng bước.",pairs:[["Đầu tiên","Làm ướt tay"],["Tiếp theo","Xoa xà phòng"],["Sau đó","Rửa sạch dưới vòi nước"],["Cuối cùng","Lau khô tay"]]},{id:"th3-theo-buoc-13",type:"tf",q:"Khi hướng dẫn bạn làm một việc, em không cần nói theo thứ tự.",explain:"Sai. Em nói rõ từng bước theo thứ tự để bạn làm theo được.",answer:!1},{id:"th3-theo-buoc-14",type:"mc",q:"Muốn mở tệp “Con mèo” nằm trong thư mục “Tranh vẽ”, bước nào làm trước?",emoji:"📁",explain:"Phải mở thư mục trước rồi mới thấy tệp bên trong.",options:["Mở tệp “Con mèo”","Mở thư mục “Tranh vẽ”","Tắt máy tính"],answer:1},{id:"th3-theo-buoc-15",type:"order",q:"Sắp xếp các bước đi bộ qua đường ở nơi có đèn tín hiệu.",emoji:"🚦",explain:"Dừng lại, quan sát, chờ đèn xanh rồi mới sang đường.",items:["Dừng lại trên vỉa hè","Quan sát đèn tín hiệu","Chờ đèn xanh cho người đi bộ","Đi sang đường trên vạch kẻ"]},{id:"th3-theo-buoc-16",type:"multi",q:"Từ nào dùng để nói thứ tự các bước của một công việc?",explain:"“Xinh đẹp” không chỉ thứ tự.",options:["Tiếp theo","Cuối cùng","Xinh đẹp","Đầu tiên"],answers:[0,1,3]},{id:"th3-theo-buoc-17",type:"tf",q:"Rô-bốt đồ chơi chỉ di chuyển đúng khi nhận đúng các lệnh theo thứ tự.",emoji:"🤖",explain:"Đúng. Rô-bốt làm theo lệnh theo đúng thứ tự.",answer:!0},{id:"th3-theo-buoc-18",type:"mc",q:"Lan làm bánh nhưng cho khuôn vào lò nướng trước khi trộn bột. Kết quả thế nào?",emoji:"🧁",explain:"Chưa có bột thì không thể nướng ra bánh.",options:["Bánh ngon hơn hẳn","Bánh to gấp đôi","Không làm được bánh"],answer:2}]},{questions:[{id:"th3-theo-buoc-19",type:"order",q:"Rô-bốt cần đi đến ô có ngôi sao: đi thẳng 2 bước, rẽ phải, đi thẳng 1 bước. Sắp xếp các lệnh.",emoji:"🤖",explain:"Rô-bốt làm lần lượt từng lệnh theo đúng thứ tự.",items:["Đi thẳng 2 bước","Rẽ phải","Đi thẳng 1 bước"]},{id:"th3-theo-buoc-20",type:"mc",q:"Tùng hướng dẫn: “Bật máy, tắt máy, làm bài”. Hướng dẫn này sai ở đâu?",explain:"Thứ tự đúng là bật máy, làm bài, rồi tắt máy.",options:["Thiếu bước đi ăn cơm trưa","Phải làm bài rồi mới tắt máy","Hướng dẫn không sai gì cả"],answer:1},{id:"th3-theo-buoc-21",type:"order",q:"Sắp xếp các bước lưu một bức tranh vẽ trên máy tính.",explain:"Vẽ xong, chọn lệnh lưu, đặt tên rồi lưu.",items:["Vẽ xong bức tranh","Chọn lệnh lưu bài","Đặt tên tệp rồi lưu lại"]},{id:"th3-theo-buoc-22",type:"tf",q:"Mỗi bước trong hướng dẫn cần rõ ràng để người khác làm theo được.",explain:"Đúng. Bước rõ ràng thì làm theo mới đúng.",answer:!0},{id:"th3-theo-buoc-23",type:"mc",q:"Ngọc nấu cơm theo các bước: vo gạo, cho gạo và nước vào nồi, cắm điện, bật nút nấu. Bước đầu tiên là gì?",emoji:"🍚",explain:"Vo gạo là bước đầu tiên.",options:["Bật nút nấu","Vo gạo","Cắm điện"],answer:1},{id:"th3-theo-buoc-24",type:"mc",q:"Bước nào còn thiếu khi rửa tay: làm ướt tay, …, rửa sạch dưới vòi nước, lau khô tay?",explain:"Sau khi làm ướt tay là bước xoa xà phòng.",options:["Đi ngủ trưa","Ăn cơm trưa","Xoa xà phòng"],answer:2},{id:"th3-theo-buoc-25",type:"order",q:"Sắp xếp các bước gọi điện chúc mừng sinh nhật bà cùng bố mẹ.",emoji:"📞",explain:"Bấm số, chờ bà nghe máy rồi chào và chúc mừng bà.",items:["Nhờ bố mẹ bấm số của bà","Chờ bà nghe máy","Chào bà và nói lời chúc mừng"]},{id:"th3-theo-buoc-26",type:"mc",q:"Hà viết: “Bước 1: Lấy cốc. Bước 2: Rót nước. Bước 3: Uống nước.” Hướng dẫn đã đúng thứ tự chưa?",emoji:"🥛",explain:"Lấy cốc, rót nước rồi uống là đúng thứ tự.",options:["Sai, phải uống trước","Đã đúng thứ tự","Sai, phải rót trước"],answer:1}]}],challenge:{questions:[{id:"th3-theo-buoc-27",type:"order",q:"Đi từ lớp học đến phòng máy: ra khỏi lớp, đi thẳng đến cầu thang, lên tầng 2, rẽ trái vào phòng máy. Sắp xếp các bước.",explain:"Làm lần lượt từng bước theo đúng hướng dẫn.",items:["Ra khỏi lớp","Đi thẳng đến cầu thang","Lên tầng 2","Rẽ trái vào phòng máy"]},{id:"th3-theo-buoc-28",type:"mc",q:"Rô-bốt đang quay mặt về phía trước. Rô-bốt nhận lệnh “rẽ phải” hai lần. Bây giờ rô-bốt quay mặt về phía nào?",emoji:"🤖",explain:"Rẽ phải hai lần thì rô-bốt quay ngược lại, hướng về phía sau.",options:["Phía sau","Phía trước","Bên trái"],answer:0},{id:"th3-theo-buoc-29",type:"multi",q:"Vì sao cần làm việc theo các bước?",explain:"Làm theo các bước giúp công việc gọn gàng, không lộn xộn.",options:["Để làm việc thật lộn xộn","Để không bỏ sót việc","Để làm đúng, làm nhanh","Để người khác làm theo được"],answers:[1,2,3]},{id:"th3-theo-buoc-03",type:"order",q:"Sắp xếp các bước rửa tay.",emoji:"🧼",explain:"Làm ướt tay, xoa xà phòng, rửa sạch rồi lau khô.",items:["Làm ướt tay","Xoa xà phòng","Rửa sạch xà phòng dưới vòi nước","Lau khô tay"]},{id:"th3-theo-buoc-12",type:"match",q:"Nối từ chỉ thứ tự với bước rửa tay.",explain:"Các từ chỉ thứ tự giúp nói rõ từng bước.",pairs:[["Đầu tiên","Làm ướt tay"],["Tiếp theo","Xoa xà phòng"],["Sau đó","Rửa sạch dưới vòi nước"],["Cuối cùng","Lau khô tay"]]},{id:"th3-theo-buoc-19",type:"order",q:"Rô-bốt cần đi đến ô có ngôi sao: đi thẳng 2 bước, rẽ phải, đi thẳng 1 bước. Sắp xếp các lệnh.",emoji:"🤖",explain:"Rô-bốt làm lần lượt từng lệnh theo đúng thứ tự.",items:["Đi thẳng 2 bước","Rẽ phải","Đi thẳng 1 bước"]},{id:"th3-theo-buoc-20",type:"mc",q:"Tùng hướng dẫn: “Bật máy, tắt máy, làm bài”. Hướng dẫn này sai ở đâu?",explain:"Thứ tự đúng là bật máy, làm bài, rồi tắt máy.",options:["Thiếu bước đi ăn cơm trưa","Phải làm bài rồi mới tắt máy","Hướng dẫn không sai gì cả"],answer:1}]},summary:["Nhiều công việc cần làm theo các bước, đúng thứ tự.","Dùng “đầu tiên, tiếp theo, cuối cùng” để nói rõ các bước.","Máy tính, rô-bốt làm theo đúng các bước con người đưa vào."]},{id:"th3-chia-nho",title:"Chia nhỏ nhiệm vụ để dễ giải quyết",weeks:[31,32],learn:[{title:"Chia việc lớn thành việc nhỏ",text:"Một việc lớn có thể chia thành nhiều việc nhỏ, dễ làm hơn.",example:"🧹 dọn phòng  ➜  gấp chăn · xếp sách · quét nhà"},{title:"Làm xong từng việc nhỏ",text:"Làm xong hết các việc nhỏ thì việc lớn cũng hoàn thành. Không được bỏ sót việc nhỏ nào.",example:"✅ ✅ ✅  ➜  🎉"},{title:"Chia việc trong nhóm",text:"Có thể giao mỗi việc nhỏ cho một bạn, cả nhóm cùng làm thì nhanh xong hơn.",example:"👧 👦 👧 cùng làm"}],practice:[{questions:[{id:"th3-chia-nho-01",type:"tf",q:"Một việc lớn có thể chia thành nhiều việc nhỏ hơn.",explain:"Đúng. Chia nhỏ giúp việc lớn dễ làm hơn.",answer:!0},{id:"th3-chia-nho-02",type:"multi",q:"Việc “dọn góc học tập” có thể chia thành những việc nhỏ nào?",explain:"Đi xem phim không phải việc dọn góc học tập.",options:["Lau bàn học","Cất bút vào hộp","Đi xem phim","Xếp sách vở"],answers:[0,1,3]},{id:"th3-chia-nho-03",type:"mc",q:"Chia nhỏ một việc lớn giúp em điều gì?",explain:"Việc nhỏ dễ làm và ít bị bỏ sót hơn.",options:["Làm khó hơn trước","Làm lâu hơn rất nhiều","Dễ làm, không bỏ sót"],answer:2},{id:"th3-chia-nho-04",type:"tf",q:"Khi chia việc cho cả nhóm, mỗi bạn làm một phần thì công việc nhanh xong hơn.",explain:"Đúng. Cùng chia nhau làm giúp xong việc nhanh hơn.",answer:!0},{id:"th3-chia-nho-05",type:"mc",q:"Việc nào là một phần của việc “chuẩn bị đi học”?",emoji:"🎒",explain:"Soạn sách vở là một việc nhỏ khi chuẩn bị đi học.",options:["Nằm ngủ trưa trên giường","Soạn sách vở vào cặp","Xem phim hoạt hình mới"],answer:1},{id:"th3-chia-nho-06",type:"fill",q:"Một việc lớn có thể chia thành nhiều việc … để dễ làm.",explain:"Việc lớn chia thành nhiều việc nhỏ.",answer:["nhỏ"]},{id:"th3-chia-nho-07",type:"mc",q:"Việc “nấu bữa cơm” có thể chia thành những việc nhỏ nào?",emoji:"🍲",explain:"Nấu cơm, nấu canh, rán trứng là các phần của bữa cơm.",options:["Nấu cơm, nấu canh, rán trứng","Quét sân, tưới cây, phơi đồ","Đi học, làm bài, đọc truyện"],answer:0},{id:"th3-chia-nho-08",type:"tf",q:"Khi chia nhỏ nhiệm vụ, bỏ qua một việc nhỏ thì việc lớn vẫn hoàn thành đầy đủ.",explain:"Sai. Phải làm xong mọi việc nhỏ thì việc lớn mới hoàn thành.",answer:!1},{id:"th3-chia-nho-09",type:"multi",q:"Việc “trang trí lớp học” có thể gồm những việc nhỏ nào?",explain:"Đánh răng không phải việc trang trí lớp học.",options:["Dán tranh lên tường","Treo cờ hoa","Đặt chậu cây xanh","Đánh răng"],answers:[0,1,2]}]},{questions:[{id:"th3-chia-nho-10",type:"match",q:"Nối việc lớn với một việc nhỏ trong đó.",explain:"Mỗi việc lớn gồm nhiều việc nhỏ.",pairs:[["Tổ chức sinh nhật","Mua bánh sinh nhật"],["Dọn phòng ngủ","Gấp chăn màn"],["Làm bài trình chiếu","Tạo trang tiêu đề"],["Chăm sóc cây","Tưới nước"]]},{id:"th3-chia-nho-11",type:"mc",q:"Nhóm của Minh có 3 bạn làm báo tường. Cách chia việc nào hợp lí?",emoji:"📰",explain:"Mỗi bạn một phần như viết bài, vẽ tranh, trang trí là hợp lí.",options:["Cả ba bạn ngồi chờ cô giáo","Mỗi bạn nhận một phần việc","Một bạn làm hết, hai bạn chơi"],answer:1},{id:"th3-chia-nho-12",type:"order",q:"Sắp xếp các việc nhỏ khi chuẩn bị bữa ăn.",explain:"Nấu xong, bày bát đũa rồi mời cả nhà ăn.",items:["Nấu thức ăn","Bày bát đũa lên bàn","Mời cả nhà vào ăn"]},{id:"th3-chia-nho-13",type:"tf",q:"Bài trình chiếu nhiều trang không thể chia cho các bạn trong nhóm cùng làm.",explain:"Sai. Mỗi bạn có thể làm một vài trang rồi ghép lại.",answer:!1},{id:"th3-chia-nho-14",type:"mc",q:"Lan làm bài trình chiếu “Bốn mùa”. Cách chia nhỏ nào hợp lí?",explain:"Mỗi trang một mùa giúp bài rõ ràng, dễ làm.",options:["Viết cả bốn mùa vào một trang","Mỗi trang nói về một mùa","Không chia, làm đến đâu hay đến đó"],answer:1},{id:"th3-chia-nho-15",type:"multi",q:"Việc “chuẩn bị đi dã ngoại” có thể chia thành những việc nhỏ nào?",explain:"Thức khuya xem phim không giúp gì cho chuyến dã ngoại.",options:["Thức khuya xem phim","Chuẩn bị đồ ăn, nước uống","Chuẩn bị mũ, áo","Xin phép bố mẹ"],answers:[1,2,3]},{id:"th3-chia-nho-16",type:"tf",q:"Làm xong các việc nhỏ, em cần kiểm tra lại xem việc lớn đã hoàn thành chưa.",explain:"Đúng. Kiểm tra lại giúp không bỏ sót việc.",answer:!0},{id:"th3-chia-nho-17",type:"mc",q:"Chi cần học thuộc một bài thơ có 4 khổ. Cách nào dễ hơn?",emoji:"📜",explain:"Chia nhỏ từng khổ giúp Chi dễ học thuộc.",options:["Đọc cả bài một lần rồi thôi","Học thuộc từng khổ một","Để đến sáng mai mới học"],answer:1},{id:"th3-chia-nho-18",type:"mc",q:"Dũng phải dọn phòng gồm: gấp chăn, xếp sách, quét nhà. Dũng đã gấp chăn và xếp sách. Việc nào còn lại?",emoji:"🧹",explain:"Dũng còn phải quét nhà.",options:["Gấp chăn","Xếp sách","Quét nhà"],answer:2}]},{questions:[{id:"th3-chia-nho-19",type:"mc",q:"Lớp tổ chức hội chợ sách. Việc lớn này nên chia thế nào?",emoji:"📚",explain:"Chia thành các việc nhỏ rõ ràng và giao cho từng nhóm.",options:["Góp, xếp sách, trang trí, đón khách","Để cô giáo làm hết một mình","Ai thích làm gì thì làm nấy"],answer:0},{id:"th3-chia-nho-20",type:"order",q:"Sắp xếp các việc nhỏ để làm bài trình chiếu “Gia đình em”.",explain:"Chọn nội dung, làm trang tiêu đề, các trang nội dung, rồi lưu và tập nói.",items:["Chọn nội dung sẽ giới thiệu","Tạo trang tiêu đề","Làm các trang về từng người","Lưu bài và tập trình bày"]},{id:"th3-chia-nho-21",type:"multi",q:"Việc “chăm sóc bể cá” gồm những việc nhỏ nào?",emoji:"🐟",explain:"Thả mèo vào bể sẽ làm hại cá.",options:["Lau kính bể","Thả mèo vào bể","Cho cá ăn đúng bữa","Thay nước khi cần"],answers:[0,2,3]},{id:"th3-chia-nho-22",type:"tf",q:"Chia nhỏ nhiệm vụ chỉ dùng cho việc ở nhà, không dùng khi làm việc với máy tính.",explain:"Sai. Khi làm việc với máy tính, em cũng chia nhỏ nhiệm vụ để dễ làm.",answer:!1},{id:"th3-chia-nho-23",type:"number",q:"Khoa có 30 phút làm bài: 10 phút làm Toán, 10 phút làm Tiếng Việt, thời gian còn lại làm Tiếng Anh. Khoa làm Tiếng Anh bao nhiêu phút?",explain:"30 − 10 − 10 = 10, Khoa làm Tiếng Anh 10 phút.",answer:10,unit:"phút"},{id:"th3-chia-nho-24",type:"mc",q:"Rô-bốt cần nhặt 3 quả bóng ở 3 chỗ khác nhau. Cách chia nhỏ hợp lí là gì?",emoji:"🤖",explain:"Chia thành 3 việc nhỏ: nhặt quả thứ nhất, thứ hai, thứ ba.",options:["Nhặt cả ba quả cùng một lúc","Không nhặt quả nào cả","Nhặt lần lượt từng quả một"],answer:2},{id:"th3-chia-nho-25",type:"mc",q:"Nhóm Vy chia việc chuẩn bị văn nghệ nhưng quên giao việc mua hoa. Điều gì có thể xảy ra?",emoji:"💐",explain:"Bỏ sót việc nhỏ thì việc lớn không hoàn thành đầy đủ.",options:["Đến lúc cần lại không có hoa","Hoa tự xuất hiện trên sân khấu","Không ảnh hưởng gì đến buổi diễn"],answer:0},{id:"th3-chia-nho-26",type:"tf",q:"Khi được giao một việc nhỏ trong nhóm, em cần làm xong phần của mình đúng hạn.",explain:"Đúng. Mỗi bạn làm tốt phần mình thì cả nhóm mới xong việc.",answer:!0}]}],challenge:{questions:[{id:"th3-chia-nho-27",type:"match",q:"Nối việc lớn với các việc nhỏ.",explain:"Mỗi việc lớn được chia thành những việc nhỏ phù hợp.",pairs:[["Chuẩn bị đi học","Soạn cặp, mặc đồng phục"],["Đón Tết","Dọn nhà, gói bánh"],["Làm thiệp chúc mừng","Gấp giấy, vẽ, viết lời chúc"]]},{id:"th3-chia-nho-28",type:"order",q:"Sắp xếp các việc nhỏ để tưới cây ngoài vườn.",emoji:"🪴",explain:"Lấy bình, hứng nước, tưới cây rồi cất bình.",items:["Lấy bình tưới","Hứng nước vào bình","Tưới nước vào gốc cây","Cất bình tưới vào chỗ cũ"]},{id:"th3-chia-nho-29",type:"multi",q:"Điều nào đúng khi chia nhỏ nhiệm vụ?",explain:"Phải làm xong tất cả việc nhỏ thì việc lớn mới xong.",options:["Có thể giao việc nhỏ cho từng người","Chỉ cần làm một việc nhỏ là xong việc lớn","Các việc nhỏ gộp lại phải đủ việc lớn","Mỗi việc nhỏ nên rõ ràng"],answers:[0,2,3]},{id:"th3-chia-nho-10",type:"match",q:"Nối việc lớn với một việc nhỏ trong đó.",explain:"Mỗi việc lớn gồm nhiều việc nhỏ.",pairs:[["Tổ chức sinh nhật","Mua bánh sinh nhật"],["Dọn phòng ngủ","Gấp chăn màn"],["Làm bài trình chiếu","Tạo trang tiêu đề"],["Chăm sóc cây","Tưới nước"]]},{id:"th3-chia-nho-11",type:"mc",q:"Nhóm của Minh có 3 bạn làm báo tường. Cách chia việc nào hợp lí?",emoji:"📰",explain:"Mỗi bạn một phần như viết bài, vẽ tranh, trang trí là hợp lí.",options:["Cả ba bạn ngồi chờ cô giáo","Mỗi bạn nhận một phần việc","Một bạn làm hết, hai bạn chơi"],answer:1},{id:"th3-chia-nho-19",type:"mc",q:"Lớp tổ chức hội chợ sách. Việc lớn này nên chia thế nào?",emoji:"📚",explain:"Chia thành các việc nhỏ rõ ràng và giao cho từng nhóm.",options:["Góp, xếp sách, trang trí, đón khách","Để cô giáo làm hết một mình","Ai thích làm gì thì làm nấy"],answer:0},{id:"th3-chia-nho-20",type:"order",q:"Sắp xếp các việc nhỏ để làm bài trình chiếu “Gia đình em”.",explain:"Chọn nội dung, làm trang tiêu đề, các trang nội dung, rồi lưu và tập nói.",items:["Chọn nội dung sẽ giới thiệu","Tạo trang tiêu đề","Làm các trang về từng người","Lưu bài và tập trình bày"]}]},summary:["Việc lớn có thể chia thành nhiều việc nhỏ, dễ làm hơn.","Làm xong tất cả việc nhỏ thì việc lớn mới hoàn thành.","Chia việc nhỏ cho từng bạn giúp cả nhóm làm nhanh hơn."]},{id:"th3-dieu-kien",title:"Công việc có điều kiện: nếu… thì…",weeks:[33,35],learn:[{title:"Việc làm có điều kiện",text:"Có những việc em làm hay không là tùy theo điều kiện. Ta nói bằng câu “Nếu… thì…”.",example:"🌧️ Nếu trời mưa thì em mang áo mưa."},{title:"Điều kiện và việc làm",text:"Phần sau “nếu” là điều kiện, phần sau “thì” là việc làm. Điều kiện xảy ra thì làm việc đó.",example:"Nếu đèn đỏ  ➜  thì dừng lại"},{title:"Máy tính làm theo điều kiện",text:"Máy tính, trò chơi cũng làm theo điều kiện: nếu em trả lời đúng thì được cộng điểm.",example:"🎮 đúng  ➜  ⭐ cộng điểm"}],practice:[{questions:[{id:"th3-dieu-kien-01",type:"mc",q:"Nếu trời mưa thì em nên làm gì khi ra đường?",emoji:"🌧️",explain:"Trời mưa thì mặc áo mưa hoặc che ô.",options:["Mang chăn ra sân phơi","Mặc áo mưa hoặc che ô","Đi tắm nắng ngoài sân"],answer:1},{id:"th3-dieu-kien-02",type:"tf",q:"“Nếu đèn đỏ thì dừng lại” là câu nói về việc làm có điều kiện.",emoji:"🚦",explain:"Đúng. Đèn đỏ là điều kiện, dừng lại là việc làm.",answer:!0},{id:"th3-dieu-kien-03",type:"match",q:"Nối điều kiện với việc làm phù hợp.",explain:"Mỗi điều kiện đi với một việc làm phù hợp.",pairs:[["Nếu trời nắng","thì đội mũ"],["Nếu bị đau bụng","thì báo bố mẹ"],["Nếu tay bẩn","thì rửa tay"],["Nếu buồn ngủ","thì đi ngủ"]]},{id:"th3-dieu-kien-04",type:"mc",q:"Trong câu “Nếu trời lạnh thì em mặc áo ấm”, điều kiện là gì?",emoji:"🧥",explain:"Phần sau chữ “nếu” là điều kiện: trời lạnh.",options:["Em mặc áo ấm","Trời lạnh","Chiếc áo ấm"],answer:1},{id:"th3-dieu-kien-05",type:"fill",q:"Hoàn thành câu: Nếu trời tối … em bật đèn.",explain:"Câu đầy đủ là: Nếu trời tối thì em bật đèn.",answer:["thì"]},{id:"th3-dieu-kien-06",type:"tf",q:"Việc có điều kiện vẫn phải làm dù điều kiện không xảy ra.",explain:"Sai. Việc có điều kiện chỉ làm khi điều kiện xảy ra.",answer:!1},{id:"th3-dieu-kien-07",type:"mc",q:"Trong câu “Nếu đói bụng thì em ăn cơm”, việc em làm là gì?",explain:"Phần sau chữ “thì” là việc làm: ăn cơm.",options:["Đói bụng","Ăn cơm","Đi ngủ"],answer:1},{id:"th3-dieu-kien-08",type:"mc",q:"Nếu đèn tín hiệu cho người đi bộ màu xanh thì em làm gì?",explain:"Đèn xanh cho người đi bộ thì em sang đường cẩn thận.",options:["Đứng yên chờ mãi","Chạy ngược trở lại","Sang đường cẩn thận"],answer:2},{id:"th3-dieu-kien-09",type:"tf",q:"Nếu trời nắng to thì em nên mặc áo mưa khi ra đường.",emoji:"☀️",explain:"Sai. Trời nắng to thì em đội mũ, mặc áo chống nắng.",answer:!1}]},{questions:[{id:"th3-dieu-kien-10",type:"mc",q:"Trò chơi có luật: “Nếu trả lời đúng thì được cộng điểm”. An trả lời đúng. Điều gì xảy ra?",emoji:"⭐",explain:"Điều kiện “trả lời đúng” xảy ra nên An được cộng điểm.",options:["An bị trừ điểm","An được cộng điểm","Trò chơi tắt đi"],answer:1},{id:"th3-dieu-kien-11",type:"mc",q:"Quy định: “Nếu hết giờ ra chơi thì vào lớp”. Trống báo hết giờ ra chơi vang lên. Em làm gì?",emoji:"🥁",explain:"Điều kiện hết giờ ra chơi đã xảy ra nên em vào lớp.",options:["Chơi tiếp","Đi về nhà","Vào lớp"],answer:2},{id:"th3-dieu-kien-12",type:"tf",q:"Câu “Em đánh răng mỗi sáng” là câu có dạng “nếu… thì…”.",explain:"Sai. Câu này không có điều kiện “nếu… thì…”.",answer:!1},{id:"th3-dieu-kien-13",type:"match",q:"Nối việc em làm trên máy tính với điều xảy ra.",explain:"Máy tính làm việc theo điều kiện: nếu em làm thao tác thì có kết quả tương ứng.",pairs:[["Nháy đúp vào thư mục","Thư mục được mở ra"],["Nháy vào nút phát bài hát","Bài hát được phát"],["Kéo thả quả táo vào giỏ","Quả táo nằm trong giỏ"]]},{id:"th3-dieu-kien-14",type:"multi",q:"Câu nào là câu có điều kiện?",explain:"Câu có điều kiện có dạng “nếu… thì…”.",options:["Em thích ăn táo","Hôm nay là thứ Hai","Nếu trời mưa thì em mang ô","Nếu em chăm học thì em tiến bộ"],answers:[2,3]},{id:"th3-dieu-kien-15",type:"mc",q:"Quy định: “Nếu hết bút chì thì mua bút mới”. Hà vẫn còn bút chì. Hà có cần mua bút mới không?",emoji:"✏️",explain:"Điều kiện “hết bút chì” chưa xảy ra nên chưa cần mua.",options:["Không cần mua","Phải mua ngay","Mua mười cái"],answer:0},{id:"th3-dieu-kien-16",type:"tf",q:"Nếu điều kiện không xảy ra thì không cần làm việc đi kèm điều kiện đó.",explain:"Đúng. Việc có điều kiện chỉ làm khi điều kiện xảy ra.",answer:!0},{id:"th3-dieu-kien-17",type:"mc",q:"Rô-bốt nhận lệnh: “Nếu gặp tường thì rẽ trái”. Rô-bốt đang đi và gặp tường. Rô-bốt sẽ làm gì?",emoji:"🤖",explain:"Điều kiện “gặp tường” xảy ra nên rô-bốt rẽ trái.",options:["Rẽ phải","Đi xuyên tường","Rẽ trái"],answer:2},{id:"th3-dieu-kien-18",type:"mc",q:"Câu nào viết đúng dạng “nếu… thì…”?",explain:"Câu đúng: “Nếu” đứng trước điều kiện, “thì” đứng trước việc làm.",options:["Nếu trời tối thì bật đèn","Trời tối nếu thì bật đèn","Thì trời tối nếu bật đèn"],answer:0}]},{questions:[{id:"th3-dieu-kien-19",type:"mc",q:"Quy định: “Nếu đến lớp muộn thì xin phép cô trước khi vào lớp”. Nam đến lớp muộn. Nam nên làm gì?",explain:"Nam đến muộn nên phải xin phép cô trước khi vào lớp.",options:["Chạy thẳng vào chỗ","Xin phép cô rồi vào","Đứng ngoài, không vào"],answer:1},{id:"th3-dieu-kien-20",type:"mc",q:"Luật trò chơi: “Nếu bóng màu đỏ thì nháy chuột vào bóng, nếu bóng màu xanh thì bỏ qua”. Gặp bóng màu xanh, em làm gì?",emoji:"🎈",explain:"Bóng màu xanh thì bỏ qua, không nháy chuột.",options:["Nháy chuột vào bóng","Tắt trò chơi đi","Bỏ qua quả bóng"],answer:2},{id:"th3-dieu-kien-21",type:"match",q:"Nối tình huống với việc nên làm.",explain:"Mỗi tình huống có một việc làm an toàn đi kèm.",pairs:[["Nếu người lạ nhắn tin làm quen","thì báo bố mẹ"],["Nếu thấy quảng cáo lạ","thì không bấm vào"],["Nếu mắt mỏi khi dùng máy","thì nghỉ ngơi"]]},{id:"th3-dieu-kien-22",type:"tf",q:"Mẹ dặn: “Nếu làm xong bài thì được xem hoạt hình”. Vy chưa làm xong bài nhưng vẫn xem hoạt hình. Vy đã làm đúng lời mẹ.",explain:"Sai. Điều kiện “làm xong bài” chưa xảy ra nên Vy chưa được xem.",answer:!1},{id:"th3-dieu-kien-23",type:"mc",q:"Mẹ dặn: “Nếu trời nắng thì đội mũ, nếu trời mưa thì mặc áo mưa”. Hôm nay trời mưa. Em làm gì khi ra ngoài?",emoji:"☔",explain:"Trời mưa nên em mặc áo mưa.",options:["Chỉ đội mũ","Không mang gì","Mặc áo mưa"],answer:2},{id:"th3-dieu-kien-24",type:"mc",q:"Máy tưới cây tự động làm theo quy tắc: “Nếu đất khô thì tưới nước”. Đất đang ẩm. Máy sẽ làm gì?",emoji:"🌱",explain:"Điều kiện “đất khô” không xảy ra nên máy không tưới.",options:["Không tưới nước","Tưới nước ngay","Tưới thật nhiều"],answer:0},{id:"th3-dieu-kien-25",type:"multi",q:"Câu “nếu… thì…” nào là lời khuyên đúng?",explain:"Trời mưa mà đem chăn ra phơi là không hợp lí.",options:["Nếu thấy cháy thì báo ngay người lớn","Nếu trời mưa thì đem chăn ra phơi","Nếu tay bẩn thì rửa tay bằng xà phòng"],answers:[0,2]},{id:"th3-dieu-kien-26",type:"tf",q:"Nếu em nháy chuột vào nút “Thoát” thì trò chơi đóng lại; đây là máy tính làm việc theo điều kiện.",explain:"Đúng. Có thao tác của em thì máy tính mới làm việc tương ứng.",answer:!0}]}],challenge:{questions:[{id:"th3-dieu-kien-27",type:"mc",q:"Luật trò chơi: “Nếu được từ 8 điểm trở lên thì được huy hiệu vàng, nếu dưới 8 điểm thì được huy hiệu bạc”. Lan được 9 điểm. Lan nhận huy hiệu gì?",emoji:"🏅",explain:"9 điểm là từ 8 điểm trở lên nên Lan được huy hiệu vàng.",options:["Huy hiệu vàng","Huy hiệu bạc","Không có gì"],answer:0},{id:"th3-dieu-kien-28",type:"mc",q:"Luật trò chơi: “Nếu được từ 8 điểm trở lên thì được huy hiệu vàng, nếu dưới 8 điểm thì được huy hiệu bạc”. Bình được 7 điểm. Bình nhận huy hiệu gì?",emoji:"🥈",explain:"7 điểm là dưới 8 điểm nên Bình được huy hiệu bạc.",options:["Huy hiệu vàng","Huy hiệu bạc","Không có gì"],answer:1},{id:"th3-dieu-kien-29",type:"order",q:"Rô-bốt có lệnh: “Nếu gặp ô có quả táo thì nhặt táo”. Rô-bốt đi qua: ô trống, ô có táo, ô trống. Sắp xếp việc rô-bốt làm.",emoji:"🍎",explain:"Rô-bốt chỉ nhặt táo ở ô có táo, các ô trống thì đi qua.",items:["Đi qua ô trống thứ nhất","Nhặt quả táo","Đi qua ô trống thứ hai"]},{id:"th3-dieu-kien-03",type:"match",q:"Nối điều kiện với việc làm phù hợp.",explain:"Mỗi điều kiện đi với một việc làm phù hợp.",pairs:[["Nếu trời nắng","thì đội mũ"],["Nếu bị đau bụng","thì báo bố mẹ"],["Nếu tay bẩn","thì rửa tay"],["Nếu buồn ngủ","thì đi ngủ"]]},{id:"th3-dieu-kien-17",type:"mc",q:"Rô-bốt nhận lệnh: “Nếu gặp tường thì rẽ trái”. Rô-bốt đang đi và gặp tường. Rô-bốt sẽ làm gì?",emoji:"🤖",explain:"Điều kiện “gặp tường” xảy ra nên rô-bốt rẽ trái.",options:["Rẽ phải","Đi xuyên tường","Rẽ trái"],answer:2},{id:"th3-dieu-kien-20",type:"mc",q:"Luật trò chơi: “Nếu bóng màu đỏ thì nháy chuột vào bóng, nếu bóng màu xanh thì bỏ qua”. Gặp bóng màu xanh, em làm gì?",emoji:"🎈",explain:"Bóng màu xanh thì bỏ qua, không nháy chuột.",options:["Nháy chuột vào bóng","Tắt trò chơi đi","Bỏ qua quả bóng"],answer:2},{id:"th3-dieu-kien-23",type:"mc",q:"Mẹ dặn: “Nếu trời nắng thì đội mũ, nếu trời mưa thì mặc áo mưa”. Hôm nay trời mưa. Em làm gì khi ra ngoài?",emoji:"☔",explain:"Trời mưa nên em mặc áo mưa.",options:["Chỉ đội mũ","Không mang gì","Mặc áo mưa"],answer:2}]},summary:["Có những việc chỉ làm khi điều kiện xảy ra; ta nói bằng câu “Nếu… thì…”.","Phần sau “nếu” là điều kiện, phần sau “thì” là việc làm.","Máy tính, rô-bốt cũng làm việc theo điều kiện."]}]}],g={grade:3,subject:n,title:h,review:t,topics:i};export{g as default,c as grade,t as review,n as subject,h as title,i as topics};
